    [49] = "GothamMedium", [48] = "Gotham", [50] = "GothamBold", [51] = "GothamBlack", [52] = "RobotoMono",
}

local SCALES: { [number]: number } = {
    [0] = 1, 1, 0.98, 0.95, 1.1, 1.08, 1.12, 1,
    1.02, 1.12, 0.95, 1.02, 1.04, 1.06, 1.04, 0.96,
