local CUSTOM: { [number]: { Url: string, File: string, Name: string, Weight: number, Advances: { number } } } = {
    [53] = { Url = "https://raw.githubusercontent.com/rsms/inter/v3.19/docs/font-files/Inter-Medium.otf", File = "Inter-Medium.otf", Name = "Inter Medium", Weight = 500, Advances = { 746,827,1126,1794,1812,2332,1833,612,1064,1064,1469,1875,810,1304,797,1035,1819,1331,1727,1814,1842,1746,1790,1630,1778,1790,797,810,1875,1875,1875,1480,2725,1971,1842,2071,2032,1698,1650,2109,2090,759,1554,1871,1589,2528,2103,2163,1800,2164,1816,1812,1833,2077,1971,2754,1876,1928,1799,1064,1035,1064,1338,1295,1400,1603,1762,1599,1762,1654,1039,1738,1695,701,701,1567,701,2488,1682,1696,1738,1738,1082,1509,1047,1674,1595,2323,1552,1595,1553,1064,964,1064,1875 } },
    [54] = { Url = "https://raw.githubusercontent.com/rsms/inter/v3.19/docs/font-files/Inter-SemiBold.otf", File = "Inter-SemiBold.otf", Name = "Inter SemiBold", Weight = 600, Advances = { 699,870,1115,1811,1828,2376,1866,600,1108,1108,1530,1894,831,1312,818,1066,1878,1354,1750,1835,1875,1781,1825,1653,1819,1825,818,831,1894,1894,1894,1532,2814,2038,1851,2094,2040,1711,1649,2126,2095,774,1579,1906,1594,2552,2086,2182,1812,2184,1832,1828,1858,2066,2038,2835,1944,1984,1838,1108,1066,1108,1355,1318,1400,1618,1775,1626,1775,1669,1062,1761,1726,734,734,1602,734,2528,1717,1712,1759,1759,1117,1546,1070,1713,1622,2358,1584,1622,1582,1108,1008,1108,1894 } },
}
local UNITS = 2816
local FONT_FOLDER = "OkloUI Fonts"

local faces: { [number]: any } = {}
local started: { [number]: boolean } = {}
Fonts.version = 0

local function fetchBytes(url: string): string?
    local ok, response = pcall(function()
        return request({ Url = url, Method = "GET" })
    end)
    if not ok or type(response) ~= "table" then
        return nil
    end
    local status = tonumber(response.StatusCode) or 0
    if status ~= 0 and (status < 200 or status >= 400) then
        return nil
    end
    local body = response.Body
    return if type(body) == "string" and #body > 10000 then body else nil
end

local function build(index: number)
    local entry = CUSTOM[index]
    if type(getcustomasset) ~= "function" or type(request) ~= "function" or not Storage.ensureFolder(FONT_FOLDER) then
        return
    end
    local path = FONT_FOLDER .. "/" .. entry.File
    if not Storage.isFile(path) then
        local body = fetchBytes(entry.Url)
        if not body or not Storage.write(path, body) then
            return
        end
    end
    local ok, asset = pcall(getcustomasset, path)
    if not ok or type(asset) ~= "string" or asset == "" then
        return
    end
    local family = FONT_FOLDER .. "/" .. entry.Name:gsub("%s", "") .. ".json"
    local json = game:GetService("HttpService"):JSONEncode({
        name = entry.Name,
        faces = { { name = "Regular", weight = 400, style = "normal", assetId = asset } },
    })
    if not Storage.write(family, json) then
        return
    end
    local made, font = pcall(function()
        return Font.new((getcustomasset :: any)(family))
    end)
    if made and font ~= nil then
        faces[index] = font
        Fonts.version += 1
    end
end

function Fonts.face(index: number): any
    local face = faces[index]
    if face ~= nil then
        return face
    end
    if CUSTOM[index] and not started[index] and type(task) == "table" then
        started[index] = true
        task.spawn(function()
            pcall(build, index)
        end)
    end
    return nil
end

local ratios: { [number]: number } = {}

local function advanceWidth(index: number, text: string, size: number): number?
    local entry = CUSTOM[index]
    if not entry or faces[index] == nil then
        return nil
    end
    local advances = entry.Advances
    local ok, total = pcall(function(): number
        local sum = 0
        for _, code in utf8.codes(text) do
            sum += if code >= 32 and code <= 126 then advances[code - 31] else 1800
        end
        return sum
    end)
    if not ok then
        return nil
    end
    return total * size / UNITS
end

function Fonts.measure(index: number, text: string, size: number): number?
    local width = advanceWidth(index, text, size)
    return if width then width * (ratios[index] or 1) else nil
end

function Fonts.wantsSample(index: number): boolean
    return CUSTOM[index] ~= nil and faces[index] ~= nil
end

function Fonts.learn(index: number, text: string, size: number, drawn: number)
    local width = advanceWidth(index, text, size)
    if not width or width < 40 or type(drawn) ~= "number" or drawn <= 0 then
        return
    end
    local ratio = drawn / width
    if ratio < 0.6 or ratio > 1.3 then
        return
    end
    local old = ratios[index]
    if not old or math.abs(ratio - old) > 0.012 then
        ratios[index] = if old then old + (ratio - old) * 0.5 else ratio
    end
end

local resolved: { [number]: any } = {}

function Fonts.find(name: string): number
    for index = 0, Fonts.COUNT - 1 do
        if Fonts.NAMES[index] == name then
            return index
        end
    end
    return Fonts.DEFAULT
end

function Fonts.boldOf(index: number): number?
    return BOLDS[index]
end

function Fonts.scale(index: number): number
    return SCALES[index] or 1
end

function Fonts.enum(index: number): any
    local cached = resolved[index]
    if cached then
        return cached
    end
    local name = ENUMS[index] or ENUMS[Fonts.DEFAULT]
    local font = Enum.Font.Ubuntu
    local fallback = if ENUMS[index] then FALLBACKS[index] else FALLBACKS[Fonts.DEFAULT]
    for _, candidate in { name, fallback } do
        local ok, found = pcall(function()
            return (Enum.Font :: any)[candidate]
        end)
        if ok and found ~= nil then
            font = found
            break
        end
    end
    resolved[index] = font
    return font
end

return Fonts
end
modules["ui/geometry"] = function(...)

local Geometry = {}

local HALF_PI = math.pi * 0.5

function Geometry.outlineMetrics(width: number, height: number, radius: number): (number, number, number, number, number)
    local r = math.clamp(radius, 0, math.min(width, height) * 0.5)
    local straightW = math.max(0, width - r * 2)
    local straightH = math.max(0, height - r * 2)
    local arc = math.pi * r * 0.5
    local perimeter = (straightW + straightH) * 2 + arc * 4
    return r, straightW, straightH, arc, math.max(1, perimeter)
end

function Geometry.outlinePoint(distance: number, width: number, height: number, radius: number): Vector2
    local r, straightW, straightH, arc, perimeter = Geometry.outlineMetrics(width, height, radius)
    local d = distance % perimeter
    local arcSafe = math.max(0.001, arc)

    if d <= straightW then
        return Vector2.new(r + d, 0)
    end
    d -= straightW
    if d <= arc then
        local angle = -HALF_PI + (d / arcSafe) * HALF_PI
        return Vector2.new(width - r + math.cos(angle) * r, r + math.sin(angle) * r)
    end
    d -= arc
    if d <= straightH then
        return Vector2.new(width, r + d)
    end
    d -= straightH
    if d <= arc then
        local angle = (d / arcSafe) * HALF_PI
        return Vector2.new(width - r + math.cos(angle) * r, height - r + math.sin(angle) * r)
    end
    d -= arc
    if d <= straightW then
        return Vector2.new(width - r - d, height)
    end
    d -= straightW
    if d <= arc then
        local angle = HALF_PI + (d / arcSafe) * HALF_PI
        return Vector2.new(r + math.cos(angle) * r, height - r + math.sin(angle) * r)
    end
    d -= arc
    if d <= straightH then
        return Vector2.new(0, height - r - d)
    end
    d -= straightH
    local angle = math.pi + (d / arcSafe) * HALF_PI
    return Vector2.new(r + math.cos(angle) * r, r + math.sin(angle) * r)
end

function Geometry.clipLine(x0: number, y0: number, x1: number, y1: number, left: number, top: number, right: number, bottom: number): (Vector2?, Vector2?)
    local dx = x1 - x0
    local dy = y1 - y0
    local t0, t1 = 0, 1

    local function clip(p: number, q: number): boolean
        if math.abs(p) < 0.000001 then
            return q >= 0
        end
        local r = q / p
        if p < 0 then
            if r > t1 then
                return false
            end
            if r > t0 then
                t0 = r
            end
        else
            if r < t0 then
                return false
            end
            if r < t1 then
                t1 = r
            end
        end
        return true
    end

    if clip(-dx, x0 - left) and clip(dx, right - x0) and clip(-dy, y0 - top) and clip(dy, bottom - y0) then
        return Vector2.new(x0 + dx * t0, y0 + dy * t0), Vector2.new(x0 + dx * t1, y0 + dy * t1)
    end
    return nil, nil
end

function Geometry.insideArea(x: number, y: number, left: number, top: number, right: number, bottom: number, bottomRadius: number): boolean
    if x < left or x > right or y < top or y > bottom then
        return false
    end
    local radius = math.clamp(bottomRadius, 0, math.min((right - left) * 0.5, bottom - top))
    if radius <= 0 or y <= bottom - radius then
        return true
    end
    local dy = y - (bottom - radius)
    if x < left + radius then
        local dx = x - (left + radius)
        return dx * dx + dy * dy <= radius * radius
    elseif x > right - radius then
        local dx = x - (right - radius)
        return dx * dx + dy * dy <= radius * radius
    end
    return true
end

function Geometry.rowInset(y: number, width: number, height: number, radius: number): number
    local r = math.clamp(radius, 0, math.min(width, height) * 0.5)
    if r <= 0 then
        return 0
    end
    local dy
    if y < r then
        dy = r - y
    elseif y > height - r then
        dy = y - (height - r)
    else
        return 0
    end
    return r - math.sqrt(math.max(0, r * r - dy * dy))
end

function Geometry.columnInset(x: number, width: number, height: number, radius: number): number
    return Geometry.rowInset(x, height, width, radius)
end

return Geometry
end
modules["ui/hits"] = function(...)

local import: (string) -> any = ...
local Util: typeof(require("../core/util")) = import("core/util")

local Hits = {}

export type Region = {
    key: any,
    position: Vector2,
    size: Vector2,

    click: (() -> ())?,

    drag: ((mouse: Vector2) -> ())?,

    press: ((mouse: Vector2) -> ())?,

    shield: boolean?,

    start: Vector2?,
    moved: boolean?,

    wheel: ((delta: number) -> ())?,

    rightClick: (() -> ())?,
}

local regions: { Region } = {}
local previous: { Region } = {}
local pending: Region? = nil
local dragging: Region? = nil
local CLICK_SLACK = 4
local suspended = false
local clipPosition: Vector2? = nil
local clipSize: Vector2? = nil

function Hits.suspend(state: boolean)
    suspended = state
end

function Hits.isSuspended(): boolean
    return suspended
end

function Hits.begin()
    previous, regions = regions, previous
    table.clear(regions)
end

function Hits.setClip(position: Vector2?, size: Vector2?)
    clipPosition, clipSize = position, size
end

function Hits.getClip(): (Vector2?, Vector2?)
    return clipPosition, clipSize
end

function Hits.add(region: Region)
    if suspended then
        return
    end
    if clipPosition and clipSize then
        local left = math.max(region.position.X, clipPosition.X)
        local top = math.max(region.position.Y, clipPosition.Y)
        local right = math.min(region.position.X + region.size.X, clipPosition.X + clipSize.X)
        local bottom = math.min(region.position.Y + region.size.Y, clipPosition.Y + clipSize.Y)
        if right <= left or bottom <= top then
            return
        end
        region.position, region.size = Vector2.new(left, top), Vector2.new(right - left, bottom - top)
    end
    regions[#regions + 1] = region
end

function Hits.at(point: Vector2): Region?
    for index = #previous, 1, -1 do
        local region = previous[index]
        if Util.contains(point, region.position, region.size) then
            return region
        end
    end
    return nil
end

function Hits.wheel(point: Vector2, delta: number): boolean
    for index = #previous, 1, -1 do
        local region = previous[index]
        if region.wheel and Util.contains(point, region.position, region.size) then
            pcall(region.wheel, delta)
            return true
        end
        if region.shield and Util.contains(point, region.position, region.size) then
            return false
        end
    end
    return false
end

function Hits.rightClick(point: Vector2): boolean
    local region = Hits.at(point)
    if region and region.rightClick then
        pcall(region.rightClick)
        return true
    end
    return false
end

function Hits.hover(point: Vector2): any
    local region = Hits.at(point)
    return region and region.key or nil
end

function Hits.isPressed(key: any): boolean
    return pending ~= nil and pending.key == key
end

function Hits.isDragging(key: any): boolean
    return dragging ~= nil and dragging.key == key
end

function Hits.busy(): boolean
    return pending ~= nil or dragging ~= nil
end

function Hits.heldKey(): any
    if dragging then
        return dragging.key
    end
    return pending and pending.key or nil
end

function Hits.press(point: Vector2): boolean
    local region = Hits.at(point)
    if not region or region.shield then
        return region ~= nil
    end
    if region.drag then
        dragging = region
        region.start, region.moved = point, region.click == nil
        if region.press then
            pcall(region.press, point)
        end
        if region.click == nil then
            pcall(region.drag, point)
        end
    elseif region.click then
        pending = region
    end
    return true
end

function Hits.hold(point: Vector2)
    if dragging and dragging.drag then
        if not dragging.moved and dragging.start and (point - dragging.start).Magnitude >= 5 then
            dragging.moved = true
        end
        if dragging.moved then
            pcall(dragging.drag, point)
        end
    end
end

function Hits.release(point: Vector2)
    local region = pending
    local dragged = dragging
    pending = nil
    dragging = nil
    if dragged and dragged.click and not dragged.moved then
        region = dragged
    end
    if region and region.click then
        local position, size = region.position, region.size
        if point.X >= position.X - CLICK_SLACK and point.X <= position.X + size.X + CLICK_SLACK
            and point.Y >= position.Y - CLICK_SLACK and point.Y <= position.Y + size.Y + CLICK_SLACK then
            pcall(region.click)
        end
    end
end

function Hits.cancel()
    pending = nil
    dragging = nil
end

return Hits
end
