local Maid = {}
Maid.__index = Maid

function Maid.new()
    return setmetatable({ items = {} }, Maid)
end

function Maid:Give(item)
    self.items[#self.items + 1] = item
    return item
end

function Maid:Clean()
    local items = self.items
    self.items = {}
    for index = #items, 1, -1 do
        local item = items[index]
        pcall(function()
            local kind = typeof(item)
            if kind == "RBXScriptConnection" then
                item:Disconnect()
            elseif kind == "Instance" then
                item:Destroy()
            elseif kind == "function" then
                item()
            elseif kind == "table" and type(item.Destroy) == "function" then
                item:Destroy()
            end
        end)
    end
end

local Root = Maid.new()

local lastNotice = {}
local function notify(title, description, kind, duration)
    local key = title .. "|" .. tostring(description)
    if os.clock() - (lastNotice[key] or -math.huge) < 2 then
        return
    end
    lastNotice[key] = os.clock()
    pcall(function()
        Library:Notify({ Title = title, Description = description, Type = kind or "Info", Duration = duration or 4 })
    end)
end

-- toggle() below records every UI toggle here. (Library.Options never existed, so the old setFlag threw on every call:
-- Auto Farm could not switch its helper options on, errored 25 times and was shut off by the error guard.)
local UIObjects = {}

local function setFlag(flag, value)
    local option = UIObjects[flag]
    if option and option.SetValue then
        option:SetValue(value)
        if value == false then
            Flags[flag] = false
        end
    else
        Flags[flag] = value
    end
end

-- Match report telemetry (core). The reporter half lives further down, next to the frame loops.
local ReportCfg = {
    Webhook = "PASTE_WEBHOOK_URL_HERE", -- hard-coded Discord webhook removed; reports stay off unless you set your own
    MinMatchSeconds = 45,  -- matches shorter than this are not reported
    PeriodicSeconds = 600, -- fallback report interval if no match start/end is ever detected
    Hotkey = Enum.KeyCode.F8, -- press to send a report right now
    ConsoleLines = 120,
}

local Tel = {
    counts = {}, samples = {}, onTime = {}, events = {}, errors = {}, console = {},
    startedAt = os.clock(), matchIndex = 1, lastInGame = nil, lostSince = nil,
    sending = false, lastSend = -math.huge, lastAuto = os.clock(), finished = false,
    errorSent = false, pendingError = false, seenTransition = false,
}

function Tel.count(key, amount)
    Tel.counts[key] = (Tel.counts[key] or 0) + (amount or 1)
end

function Tel.sample(key, value)
    if type(value) ~= "number" or value ~= value then
        return
    end
    local s = Tel.samples[key]
    if not s then
        s = { n = 0, sum = 0, min = math.huge, max = -math.huge }
        Tel.samples[key] = s
    end
    s.n += 1
    s.sum += value
    if value < s.min then s.min = value end
    if value > s.max then s.max = value end
end

function Tel.event(text)
    local list = Tel.events
    list[#list + 1] = ("[%6.1fs] %s"):format(os.clock() - Tel.startedAt, text)
    if #list > 80 then
        table.remove(list, 1)
    end
end

function Tel.error(feature, err)
    local e = Tel.errors[feature]
    if not e then
        e = { count = 0, first = string.sub(tostring(err), 1, 900), last = "" }
        Tel.errors[feature] = e
        Tel.event(feature .. " threw an error")
    end
    e.count += 1
    e.last = string.sub(tostring(err), 1, 900)
    Tel.pendingError = true
end

local Faults = {}
local function guarded(feature, flag, fn)
    return function(...)
        local ok, err = xpcall(fn, function(e)
            return debug.traceback(tostring(e), 2)
        end, ...)
        if ok then
            return
        end
        Tel.error(feature, err)
        local count = (Faults[feature] or 0) + 1
        Faults[feature] = count
        if count == 1 then
            warn(("[JHub] %s error: %s"):format(feature, tostring(err)))
        end
        if count >= 25 then -- [mine] a feature that keeps throwing is switched off instead of spamming every frame
            Faults[feature] = 0
            warn(("[JHub] %s disabled after repeated errors"):format(feature))
            Tel.event(feature .. " DISABLED after repeated errors")
            if flag then
                setFlag(flag, false)
            end
            notify(feature, "Disabled after repeated errors. See the console.", "Error", 6)
        end
    end
end

local function guiParent()
    local ok, hidden = pcall(function()
        return gethui()
    end)
    if ok and hidden then
        return hidden
    end
    return CoreGui
end

local FLAT = Vector3.new(1, 0, 1)

local function flatDistance(a, b)
    local dx, dz = a.X - b.X, a.Z - b.Z
    return math.sqrt(dx * dx + dz * dz)
end

local function finiteVector(v)
    return typeof(v) == "Vector3" and v.X == v.X and v.Y == v.Y and v.Z == v.Z
        and math.abs(v.X) < 1e6 and math.abs(v.Y) < 1e6 and math.abs(v.Z) < 1e6
end

----------------------------------------------------------------------------------------------------
-- Remote resolver (missing remotes gate features instead of erroring)
----------------------------------------------------------------------------------------------------
local Remotes = { cache = {} }

local function remoteService(serviceName)
    local node = ReplicatedStorage
    for _, name in ipairs(GameData.RemoteRoot) do
        node = node and node:FindFirstChild(name)
    end
    return node and node:FindFirstChild(serviceName)
end

local function remote(serviceName, remoteName)
    local key = serviceName .. "." .. remoteName
    local cached = Remotes.cache[key]
    if cached and cached.Parent then
        return cached
    end
    Remotes.cache[key] = nil
    local service = remoteService(serviceName)
    local found = service and service:FindFirstChild(remoteName)
    if found and found:IsA("RemoteEvent") then
        Remotes.cache[key] = found
        return found
    end
    return nil
end

local function fire(serviceName, remoteName, ...)
    local target = remote(serviceName, remoteName)
    if not target then
        Tel.count("fire_missing." .. serviceName .. "." .. remoteName)
        return false
    end
    local ok = pcall(target.FireServer, target, ...)
    Tel.count((ok and "fire." or "fire_fail.") .. serviceName .. "." .. remoteName)
    return ok
end

local function needRemotes(serviceName, names)
    return function()
        for _, name in ipairs(names) do
            if not remote(serviceName, name) then
                return false, ("%s.%s not found on this build. Feature gated."):format(serviceName, name)
            end
        end
        return true
    end
end

local function needAll(...)
    local checks = { ... }
    return function()
        for _, check in ipairs(checks) do
            local ok, why = check()
            if not ok then
                return false, why
            end
        end
        return true
    end
end

local function needFunction(name)
    return function()
        if type(Env[name]) == "function" then
            return true
        end
        return false, ("Executor function %s is unavailable. Feature gated."):format(name)
    end
end

