-- World snapshot
----------------------------------------------------------------------------------------------------
-- No waiting here: in the lobby and in the Blacktop showcase the folder does not exist yet. Waiting 10s delayed the whole
-- script and then left Characters nil for good, so nothing worked after the match started. It is picked up when it appears
-- (see the watcher in the start up section).
local Characters = Workspace:FindFirstChild(GameData.CharactersFolder)

local function isOtherCharacter(model)
    return model:IsA("Model") and model.Name ~= LocalPlayer.Name and model.Name ~= GameData.IgnoredCharacterName
end

local function holdsBall(model)
    local folder = model and model:FindFirstChild("Attributes")
    local value = folder and folder:FindFirstChild("Basketball")
    if not value then
        return false
    end
    if value:IsA("ObjectValue") then
        return value.Value ~= nil -- [live] Value was set while holding; the not-holding state is unverified
    end
    return true
end

local function teamOf(model)
    local team = model:GetAttribute("TeamIndex")
    if team == nil then
        team = model:GetAttribute("Team")
    end
    return team
end

local function sameTeam(a, b)
    local ta, tb = teamOf(a), teamOf(b)
    return ta ~= nil and tb ~= nil and ta == tb
end

local Ctx = { frame = 0, char = nil, hrp = nil, hasBall = false, action = "", others = {}, othersFrame = -1,
    hoopPos = nil, hoopDist = math.huge }

local Hoops = { list = {}, watching = nil, checkedAt = -math.huge }

function Hoops.refresh()
    local folder = Workspace:FindFirstChild(GameData.HoopsFolder)
    local list = {}
    if folder then
        for _, model in ipairs(folder:GetChildren()) do
            if model:IsA("Model") then
                local ok, cframe = pcall(model.GetBoundingBox, model)
                if ok and finiteVector(cframe.Position) then
                    list[#list + 1] = cframe.Position
                end
            end
        end
        if Hoops.watching ~= folder then
            Hoops.watching = folder
            Root:Give(folder.ChildAdded:Connect(Hoops.refresh))
            Root:Give(folder.ChildRemoved:Connect(Hoops.refresh))
        end
    end
    Hoops.list = list
end

function Hoops.nearest(position)
    local best, bestDistance = nil, math.huge
    for _, hoop in ipairs(Hoops.list) do
        local distance = flatDistance(position, hoop)
        if distance < bestDistance then
            best, bestDistance = hoop, distance
        end
    end
    return best, bestDistance
end

local Meter -- forward declaration, defined in the Perfect Timing section

function Ctx.update()
    Ctx.frame += 1
    local char = Characters and Characters:FindFirstChild(LocalPlayer.Name)
    if char ~= Ctx.char then
        Ctx.char = char
        if Meter then
            Meter.bindCharacter(char)
        end
    end
    local hrp = char and char:FindFirstChild("HumanoidRootPart")
    Ctx.hrp = hrp
    Ctx.action = char and (char:GetAttribute("Action") or "") or ""
    Ctx.hasBall = char ~= nil and holdsBall(char)
    if hrp and #Hoops.list > 0 then
        Ctx.hoopPos, Ctx.hoopDist = Hoops.nearest(hrp.Position)
    else
        Ctx.hoopPos, Ctx.hoopDist = nil, math.huge
    end
    if os.clock() - Hoops.checkedAt > 3 and #Hoops.list == 0 then
        Hoops.checkedAt = os.clock()
        Hoops.refresh()
    end
end

function Ctx.getOthers()
    if Ctx.othersFrame == Ctx.frame then
        return Ctx.others
    end
    local list = {}
    if Characters then
        for _, model in ipairs(Characters:GetChildren()) do
            if isOtherCharacter(model) then
                local hrp = model:FindFirstChild("HumanoidRootPart")
                if hrp and finiteVector(hrp.Position) then
                    list[#list + 1] = { model = model, hrp = hrp }
                end
            end
        end
    end
    Ctx.others, Ctx.othersFrame = list, Ctx.frame
    return list
end

----------------------------------------------------------------------------------------------------
-- Physics proxy (needed by glide, speed and block push). Found through getgc, rescanned after respawn.
----------------------------------------------------------------------------------------------------
local Proxy = { part = nil, scanning = false, lastScan = -math.huge }

local function proxyAlive()
    return Proxy.part ~= nil and Proxy.part.Parent ~= nil
end

local function scanProxy()
    if Proxy.scanning or type(getgc) ~= "function" or os.clock() - Proxy.lastScan < 3 then
        return
    end
    Proxy.scanning = true
    Proxy.lastScan = os.clock()
    task.spawn(function()
        local ok, objects = pcall(getgc, true)
        if ok and type(objects) == "table" then
            for index = 1, #objects do
                local object = objects[index]
                if type(object) == "table" then
                    local readOk, value = pcall(rawget, object, "ProxyCharacter") -- [orig] key name
                    if readOk and typeof(value) == "Instance" and value:IsA("BasePart") and value.Parent then
                        Proxy.part = value
                        break
                    end
                end
                if index % 4000 == 0 then
                    task.wait()
                    if not Alive then
                        break
                    end
                end
            end
        end
        Proxy.scanning = false
    end)
end

local function getProxy()
    if proxyAlive() then
        return Proxy.part, Proxy.part:FindFirstChild("MovementVelocity") -- [orig] child name
    end
    scanProxy()
    return nil, nil
end

----------------------------------------------------------------------------------------------------
-- Perfect timing, auto calibrate
----------------------------------------------------------------------------------------------------
local Thresholds = table.clone(GameData.Meter.Threshold)

local Calibration = { dirty = false }

function Calibration.load()
    pcall(function()
        if isfile and isfile(GameData.Files.Calibration) then
            local data = HttpService:JSONDecode(readfile(GameData.Files.Calibration))
            local limit = GameData.Meter.ThresholdLimit
            if data._v ~= 3 then -- saved with the old release timing; its offsets no longer apply, start from the defaults
                return
            end
            for meterType, value in pairs(data) do
                if Thresholds[meterType] ~= nil and type(value) == "number" and value == value and math.abs(value) <= limit
                    and math.abs(value - GameData.Meter.Threshold[meterType]) <= (meterType == "Vertical" and 0.4 or 0.06) then -- a runaway saved value is dropped
                    Thresholds[meterType] = value
                end
            end
        end
    end)
end

function Calibration.save()
    pcall(function()
        if writefile then
            local out = table.clone(Thresholds)
            out._v = 3
            writefile(GameData.Files.Calibration, HttpService:JSONEncode(out))
        end
    end)
end

function Calibration.touch()
    if Calibration.dirty then
        return
    end
    Calibration.dirty = true
    task.delay(2, function()
        Calibration.dirty = false
        Calibration.save()
    end)
end

function Calibration.reset()
    Thresholds = table.clone(GameData.Meter.Threshold)
    pcall(function()
        if isfile and delfile and isfile(GameData.Files.Calibration) then
            delfile(GameData.Files.Calibration)
        end
    end)
end

Meter = { active = false, released = false, kind = "Vertical", token = 0, forceUntil = -math.huge, connection = nil }

function Meter.wanted()
    return Flags.PerfectTiming or os.clock() < Meter.forceUntil
end

function Meter.force()
    Meter.forceUntil = os.clock() + GameData.Meter.ForceWindowSeconds
end

function Meter.release(by)
    if Meter.released then
        return
    end
    Meter.releasedBy = Meter.pendingTag or by or "meter"
    Meter.releaseValue = Meter.lastValue
    Meter.releaseDir = Meter.dir
    Meter.released = true
    Meter.active = false
    fire("InputService", "Shoot", { Shoot = false }) -- [orig] argument shape
end

function Meter.readValue(offset, kind)
    if typeof(offset) == "Vector2" or typeof(offset) == "Vector3" then
        return GameData.Meter.UsesXAxis[kind] and offset.X or offset.Y
    elseif type(offset) == "number" then
        return offset
    end
    return nil
end

-- The meter value travels one way during a shot. Which way is learned from the shot itself (-1 falling, +1 rising)
-- instead of being assumed per meter type, because a wrong assumption releases on the very first sample ("Very Early").
-- It releases once the value has travelled past the threshold, and never before two samples have shown the direction.
function Meter.isReady(offset, kind)
    local value = Meter.readValue(offset, kind)
    if value == nil or value ~= value then
        return false
    end
    local now = os.clock()
    Meter.lastValue, Meter.sampT = value, now
    if Meter.firstValue == nil then
        Meter.firstValue, Meter.firstT = value, now
        return false
    end
    if Meter.dir == nil then
        local moved = value - Meter.firstValue
        if math.abs(moved) < 0.002 then
            return false
        end
        Meter.dir = moved > 0 and 1 or -1
    end
    -- Peak guard: the meter travels out to its far end and comes back. If it has turned around without ever reaching the
    -- release point (a threshold that is out of reach for this shot type), release now at the end of its travel instead of
    -- waiting for the 0.8s failsafe, which lands long after the meter has come back. Not used for calibration.
    if Meter.peak == nil or (Meter.dir < 0 and value < Meter.peak) or (Meter.dir > 0 and value > Meter.peak) then
        Meter.peak = value
    elseif math.abs(value - Meter.peak) > 0.015 and math.abs(Meter.peak) > 0.5 then
        Meter.pendingTag = "peak"
        return true
    end
    -- The server replicates the meter in coarse steps, so "first sample past the threshold" lands anywhere inside a
    -- step (often wider than the green window). Fit the speed over the whole shot instead, and let Meter.extrapolate
    -- release on the exact frame the meter is predicted to be at the threshold.
    if now - Meter.firstT > 0.01 then
        Meter.rate = (value - Meter.firstValue) / (now - Meter.firstT)
    end
    return Meter.crossed(now)
end

function Meter.target(kind)
    local threshold = Thresholds[kind] or -0.85
    local slack = Flags.PingMode and (LocalPlayer:GetNetworkPing() * 2) or 0
    local adjust = (Flags.ReleaseAdjust or 0) / 100 -- positive = release later
    return threshold + Meter.dir * (adjust - slack)
end

-- True when the meter, extended along its measured speed to this moment plus the trip to the server, is at the target.
function Meter.crossed(now)
    if Meter.dir == nil or Meter.lastValue == nil then
        return false
    end
    local target = Meter.target(Meter.kind)
    local rate = Meter.rate
    local estimate = Meter.lastValue
    if rate and Meter.sampT then
        -- never extrapolate more than a quarter second past the last real sample
        estimate = estimate + rate * math.min(now - Meter.sampT, 0.25)
        estimate = estimate + rate * math.min(LocalPlayer:GetNetworkPing(), 0.15)
    end
    if Meter.dir > 0 then
        return estimate >= target
    end
    return estimate <= target
end

-- Runs every frame while a shot is armed, so the release is frame-exact rather than tied to when the server's meter
-- updates arrive.
function Meter.extrapolate()
    if not Meter.active or Meter.released or not Meter.wanted() or Meter.dir == nil or not Meter.rate then
        return
    end
    if Meter.crossed(os.clock()) then
        Meter.release("meter")
    end
end

function Meter.bindCharacter(char)
    if not Meter.hb then
        Meter.hb = RunService.Heartbeat:Connect(guarded("Perfect Timing", "PerfectTiming", Meter.extrapolate))
        Root:Give(Meter.hb)
    end
    if Meter.connection then
        Meter.connection:Disconnect()
        Meter.connection = nil
    end
    if not char then
        return
    end
    Meter.connection = char:GetAttributeChangedSignal("meterOffset"):Connect(function() -- [orig] attribute name
        if not Alive or not Meter.active or Meter.released or not Meter.wanted() then
            return
        end
        Meter.sawOffset = true
        if Meter.isReady(char:GetAttribute("meterOffset"), Meter.kind) then
            Meter.release("meter")
        end
    end)
end

function Meter.onRegister(owner, kind)
    if not Meter.wanted() or owner ~= Ctx.char then
        return
    end
    Meter.kind = (type(kind) == "string" and kind ~= "") and kind or "Vertical"
    if Meter.active and not Meter.released then
        return
    end
    Meter.active, Meter.released = true, false
    Meter.sawOffset, Meter.firstValue, Meter.dir, Meter.lastValue = false, nil, nil, nil
    Meter.firstT, Meter.sampT, Meter.rate, Meter.releasedBy = nil, nil, nil, nil
    Meter.peak, Meter.pendingTag = nil, nil
    Meter.token += 1
    local token = Meter.token
    -- Failsafe for meters that never report an offset. It used to fire at a flat 0.8s. Now it scales with the shot speed
    -- and, if the meter is still reporting, waits one more round before giving up.
    local wait = GameData.Meter.FallbackReleaseSeconds
    local speed = Ctx.char and Ctx.char:GetAttribute("ShotSpeed")
    if type(speed) == "number" and speed > 0.05 and speed < 1 then
        wait = wait / speed
    end
    local function failsafe(final)
        if Alive and token == Meter.token and Meter.active and not Meter.released and Meter.wanted() then
            if Meter.sawOffset and not final then
                task.delay(wait, failsafe, true)
            else
                -- the meter moved but the threshold was never reached: the saved threshold is out of reach, go back to default
                local base = GameData.Meter.Threshold[Meter.kind]
                if Meter.sawOffset and base and Thresholds[Meter.kind] ~= base then
                    Thresholds[Meter.kind] = base
                    Calibration.touch()
                end
                Meter.release("failsafe")
            end
        end
    end
    task.delay(wait, failsafe, false)
end

function Meter.onUnregister(owner)
    if owner == Ctx.char then
        Meter.active, Meter.released = false, false
        Meter.token += 1
    end
end

-- Auto Calibrate: feedback grade 5 is green, below 5 is early, above 5 is late. The threshold moves along the meter's own
-- direction. Misses in the same direction double the step and a flip halves it, so a threshold that is far off is fixed
-- in a handful of shots instead of creeping 0.04 at a time.
Meter.search = {}

function Meter.onFeedback(owner, _, grade) -- [orig] (character, _, grade)
    if owner ~= Ctx.char then
        return
    end
    local index = tonumber(grade)
    Meter.lastGrade, Meter.lastBy = index, Meter.releasedBy
    local kind = Meter.kind
    if index == 5 then
        Meter.search[kind] = nil
        return
    end
    if not Flags.AutoCalibrate or not index then
        return
    end
    local dir = Meter.releaseDir or Meter.dir
    -- only learn from releases the meter made itself; a blind or failsafe release says nothing about the threshold
    if not dir or Meter.releasedBy ~= "meter" then
        return
    end
    -- [live] one feedback grade is about 0.05 of meter travel (grade 3 at -0.872, grade 2 at -0.805 on the same meter).
    -- Move straight toward green by the grade distance instead of the tiny table steps, damped by 0.7 so it settles.
    local side = index < 5 and 1 or -1 -- 1 = release later, -1 = release earlier
    local move = math.min(math.abs(5 - index), 3) * 0.04 * 0.7
    local limit = GameData.Meter.ThresholdLimit
    local base = GameData.Meter.Threshold[kind] or -0.85
    -- calibration may never wander further than this from the default. It used to be 0.25: the Funnel meter drifted to -1.09
    -- (the meter only reaches about -0.99 on an E shot), so E shots never reached the release point at all.
    local band = kind == "Vertical" and 0.4 or 0.06
    Thresholds[kind] = math.clamp((Thresholds[kind] or base) + dir * side * move, base - band, base + band)
    Meter.releasedBy = nil -- one lesson per shot
    Calibration.touch()
end

-- [mine] The meter remotes may not exist yet when JHub loads (lobby, or the first seconds of a match), and the game can
-- recreate them. A one-time bind left Perfect Timing dead at the start of a game, so this keeps checking and rebinds.
local function bindMeterRemotes()
    local bound = {}
    local function attach(key, serviceName, remoteName, feature, flag, handler)
        local target = remote(serviceName, remoteName)
        if not target or (bound[key] and bound[key].target == target) then
            return
        end
        if bound[key] then
            pcall(bound[key].connection.Disconnect, bound[key].connection)
        end
        bound[key] = { target = target, connection = target.OnClientEvent:Connect(guarded(feature, flag, handler)) }
    end
    local function bindAll()
        attach("register", "MeterService", "RegisterPacket", "Perfect Timing", "PerfectTiming", Meter.onRegister)
        attach("unregister", "MeterService", "UnregisterPacket", "Perfect Timing", "PerfectTiming", Meter.onUnregister)
        attach("feedback", "InterfaceService", "ShowFeedback", "Auto Calibrate", "AutoCalibrate", Meter.onFeedback)
    end
    bindAll()
    task.spawn(function()
        while Alive do
            task.wait(0.2)
            bindAll()
        end
    end)
    Root:Give(function()
        for _, entry in pairs(bound) do
            pcall(entry.connection.Disconnect, entry.connection)
        end
        bound = {}
    end)
end

----------------------------------------------------------------------------------------------------
-- Range rings (client-side parts parented under the camera)
----------------------------------------------------------------------------------------------------
local Visuals = { folder = nil }

local function visualsFolder()
    local parent = Workspace.CurrentCamera or Workspace
    if not Visuals.folder or not Visuals.folder.Parent then
        local folder = Instance.new("Folder")
        folder.Name = "JHub_Visuals"
        folder.Parent = parent
        Visuals.folder = folder
    elseif Visuals.folder.Parent ~= parent then
        Visuals.folder.Parent = parent
    end
    return Visuals.folder
end

local Ring = {}
Ring.__index = Ring
local SEGMENTS = 40 -- [orig]

function Ring.new(name, color)
    local self = setmetatable({ parts = {}, cx = 0, cy = 0, cz = 0, radius = -1 }, Ring)
    local folder = visualsFolder()
    for index = 1, SEGMENTS do
        local part = Instance.new("Part")
        part.Name = name .. index
        part.Anchored = true
        part.CanCollide = false
        part.CanQuery = false
        part.CanTouch = false
        part.Material = Enum.Material.Neon
        part.Color = color
        part.Transparency = 0.15
        part.CastShadow = false
        part.Parent = folder
        self.parts[index] = part
    end
    return self
end

function Ring:Update(cx, cy, cz, radius)
    if math.abs(cx - self.cx) < 0.05 and math.abs(cy - self.cy) < 0.05 and math.abs(cz - self.cz) < 0.05 and radius == self.radius then
        return true
    end
    local length = 2 * radius * math.sin(math.pi / SEGMENTS) + 0.05
    local step = (2 * math.pi) / SEGMENTS
    for index = 1, SEGMENTS do
        local part = self.parts[index]
        if not part or not part.Parent then
            return false
        end
        local a0 = (index - 1) * step
        local mid = a0 + step / 2
        local px, pz = cx + math.cos(mid) * radius, cz + math.sin(mid) * radius
        local dx, dz = math.cos(a0 + step / 2 + math.pi / 2), math.sin(a0 + step / 2 + math.pi / 2)
        part.Size = Vector3.new(length, 0.06, 0.06)
        part.CFrame = CFrame.lookAt(Vector3.new(px, cy, pz), Vector3.new(px + dx, cy, pz + dz))
    end
    self.cx, self.cy, self.cz, self.radius = cx, cy, cz, radius
    return true
end

function Ring:Destroy()
    for _, part in ipairs(self.parts) do
        pcall(part.Destroy, part)
    end
    self.parts = {}
end

local Rings = { range = nil, contest = nil }
local rayParams = RaycastParams.new()
rayParams.FilterType = Enum.RaycastFilterType.Exclude

local function groundY(hrp)
    rayParams.FilterDescendantsInstances = { Ctx.char, Visuals.folder, Proxy.part } -- [live] the physics proxy is a Part in workspace
    local hit = Workspace:Raycast(hrp.Position, Vector3.new(0, -20, 0), rayParams)
    if hit then
        return hit.Position.Y + 0.05
    end
    return hrp.Position.Y - 3
end

local function stepRings()
    local hrp = Ctx.hrp
    local wantRange = Flags.ShowRange and hrp ~= nil and Ctx.hoopPos ~= nil
    local wantContest = Flags.ShowContest and hrp ~= nil
    if not wantRange and Rings.range then
        Rings.range:Destroy()
        Rings.range = nil
    end
    if not wantContest and Rings.contest then
        Rings.contest:Destroy()
        Rings.contest = nil
    end
    if not (wantRange or wantContest) then
        return
    end
    local y = groundY(hrp)
    if wantRange then
        Rings.range = Rings.range or Ring.new("JH_Range", Color3.fromRGB(255, 60, 60))
        local hoop = Ctx.hoopPos
        if not Rings.range:Update(hoop.X, y, hoop.Z, Flags.ShootRange) then
            Rings.range:Destroy()
            Rings.range = nil
        end
    end
    if wantContest then
        Rings.contest = Rings.contest or Ring.new("JH_Contest", Color3.fromRGB(255, 255, 255))
        local position = hrp.Position
        if not Rings.contest:Update(position.X, y, position.Z, Flags.ContestRange) then
            Rings.contest:Destroy()
            Rings.contest = nil
        end
    end
end

Root:Give(function()
    if Rings.range then Rings.range:Destroy() end
    if Rings.contest then Rings.contest:Destroy() end
    if Visuals.folder then Visuals.folder:Destroy() end
end)

----------------------------------------------------------------------------------------------------
-- Offense: auto shoot, self lob, smart jelly
----------------------------------------------------------------------------------------------------
local Latch = { shoot = false, lob = false, jelly = false, backOut = 0 }

local function canAct()
    local char = Ctx.char
    if not char or not Ctx.hasBall or Ctx.action ~= "" then
        return false
    end
    return not char:GetAttribute("Debounce")
end

local function contested()
    local hrp = Ctx.hrp
    if not hrp or not Ctx.char then
        return false
    end
    for _, other in ipairs(Ctx.getOthers()) do
        if not sameTeam(Ctx.char, other.model) and flatDistance(hrp.Position, other.hrp.Position) <= Flags.ContestRange then
            return true
        end
    end
    return false
end

local function stepOffense()
    if not Ctx.hasBall then
        Latch.shoot, Latch.lob, Latch.jelly = false, false, false
        return
    end
    if not canAct() then
        return
    end
    -- [mine] Back Out: Auto Shoot is armed and in range but an opponent is on top of us. Instead of standing there, do a
    -- dribble move to shake them, then try again once the move is over (at most every 0.7s).
    if Flags.AutoShoot and Flags.AntiContest and Flags.BackOut and Ctx.hoopDist <= Flags.ShootRange
        and contested() and os.clock() - Latch.backOut > 0.7 then
        Latch.backOut = os.clock()
        local moves = GameData.AnkleMoves
        fire("InputService", "Dribble", moves[math.random(#moves)], false, Vector3.zero)
        return
    end
    -- If several are enabled the first eligible one wins the frame: Auto Shoot, then Self Lob, then Smart Jelly.
    if Flags.AutoShoot and not Latch.shoot and Ctx.hoopDist <= Flags.ShootRange and not (Flags.AntiContest and contested()) then
        Latch.shoot = true
        Meter.force()
        fire("InputService", "Shoot", { Shoot = true, Input = "E" })
        return
    end
    if Flags.AutoSelfLob and not Latch.lob and Ctx.hoopDist <= Flags.LobRange then
        Latch.lob = true
        fire("InputService", "Clutch", true)
        fire("InputService", "Pass", { Player = LocalPlayer.Name, PassType = 4 })
        task.delay(0.4, function()
            if Alive and Flags.AutoSelfLob then
                fire("InputService", "Shoot", { Shoot = true, Input = "E", UseSpace = true })
                fire("InputService", "Jump")
            end
        end)
        return
    end
    if Flags.SmartJelly and not Latch.jelly and Ctx.hoopDist <= Flags.JellyRange then
        Latch.jelly = true
        local char = Ctx.char
        Meter.force()
        fire("InputService", "Shoot", { Shoot = true, Input = "E", UseSpace = true })
        fire("InputService", "Jump")
        task.spawn(function()
            local waited = 0
            repeat
                task.wait(0.03)
                waited += 0.03
            until (char:GetAttribute("Action") or "") ~= "" or waited > 0.5 or not Alive
            local action = char:GetAttribute("Action") or ""
            if not Alive or not Flags.SmartJelly or (action ~= "Dunking" and action ~= "ContactLayup") then
                return
            end
            task.wait(0.4)
            if not Alive or not Flags.SmartJelly then return end
            Meter.force()
            fire("InputService", "Shoot", { Shoot = true, Input = "E", UseSpace = true })
            fire("InputService", "Jump")
            task.wait(0.12)
            fire("InputService", "Shoot", { Shoot = false })
            task.wait(0.1)
            if not Alive or not Flags.SmartJelly then return end
            fire("InputService", "Shoot", { Shoot = true, Input = "E", UseSpace = true })
            fire("InputService", "Jump")
            task.wait(0.13)
            fire("InputService", "Shoot", { Shoot = false })
        end)
    end
end

----------------------------------------------------------------------------------------------------
-- Dribble: glide, speed, ankle breaker, moves, combos
----------------------------------------------------------------------------------------------------
local Glide = { dribble = 0, shot = 0 }

local function glideStep(state, active, targetAction, multiplier, dt, proxy)
    if not active then
        return 0
    end
    if Ctx.action == targetAction then
        state = math.min(state + dt * 5, 1)
    else
        state = math.max(state - dt * 8, 0)
    end
    if state > 0.01 then
        local velocity = proxy.AssemblyLinearVelocity * FLAT
        if velocity.Magnitude > 0.5 then
            proxy.CFrame += velocity.Unit * (multiplier - 1) * state * dt * 10 -- [orig] formula
        end
    end
    return state
end

local function stepMovement(dt)
    if not (Flags.DribbleGlide or Flags.ShotGlide or Flags.SpeedEnabled) then
        Glide.dribble, Glide.shot = 0, 0
        return
    end
    local proxy = getProxy()
    if not proxy or not Ctx.char then
        return
    end
    Glide.dribble = glideStep(Glide.dribble, Flags.DribbleGlide, "Dribbling", Flags.GlideSpeed / 10, dt, proxy)
    Glide.shot = glideStep(Glide.shot, Flags.ShotGlide, "Shooting", Flags.ShotGlideSpeed / 10, dt, proxy)
    if Flags.SpeedEnabled then
        local velocity = proxy.AssemblyLinearVelocity * FLAT
        local multiplier = Flags.SpeedMult / 10
        if velocity.Magnitude > 0.5 and multiplier > 1 then
            proxy.CFrame += velocity.Unit * (multiplier - 1) * velocity.Magnitude * dt -- [orig] formula
        end
    end
end

local Ankle = { connections = {}, last = 0 }

local function hookAnimator(animator)
    if Ankle.connections[animator] then
        return
    end
    local model = animator:FindFirstAncestorOfClass("Model")
    if not model or not isOtherCharacter(model) then
        return
    end
    Ankle.connections[animator] = animator.AnimationPlayed:Connect(function(track)
        if not Alive or not Flags.AutoAnkle or os.clock() - Ankle.last < 0.5 then
            return
        end
        local id = track.Animation and track.Animation.AnimationId or ""
        if not GameData.AnkleAnimationIds[id] then
            return
        end
        local hrp, theirs = Ctx.hrp, model:FindFirstChild("HumanoidRootPart")
        if hrp and theirs and (hrp.Position - theirs.Position).Magnitude <= Flags.AnkleRange then
            Ankle.last = os.clock()
            local moves = GameData.AnkleMoves
            fire("InputService", "Dribble", moves[math.random(#moves)], false, Vector3.zero)
        end
    end)
end

local function bindAnkleBreaker()
    if not Characters then
        return
    end
    for _, descendant in ipairs(Characters:GetDescendants()) do
        if descendant:IsA("Animator") then
            hookAnimator(descendant)
        end
    end
    Root:Give(Characters.DescendantAdded:Connect(function(descendant)
        if descendant:IsA("Animator") then
            hookAnimator(descendant)
        end
    end))
    Root:Give(function()
        for _, connection in pairs(Ankle.connections) do
            pcall(connection.Disconnect, connection)
        end
        Ankle.connections = {}
    end)
end

local function playMove(move)
    local note = Env.__JHubRecNote -- Capture: moves you play from your own JHub keybinds / combo (the game never sees a key)
    if note then
        pcall(note, move.input)
    end
    return fire("InputService", "Dribble", move.input, move.dir, Vector3.zero)
end

local Combo = { running = false, token = 0 }

function Combo.stop()
    Combo.token += 1
    Combo.running = false
end

function Combo.play()
    if Combo.running then
        Combo.stop()
        return
    end
    local sequence = table.clone(Flags.ComboMoves)
    if #sequence == 0 then
        notify("Combo", "Pick at least one move first.", "Warning")
        return
    end
    Combo.token += 1
    local token = Combo.token
    Combo.running = true
    task.spawn(function()
        repeat
            for _, name in ipairs(sequence) do
                if not Alive or Combo.token ~= token then
                    break
                end
                local move = MovesByName[name]
                if move and playMove(move) then
                    local waited = 0
                    repeat
                        task.wait(0.05)
                        waited += 0.05
                    until (Ctx.action ~= "Dribbling") or waited > 0.6 or Combo.token ~= token -- [orig] timings
                end
                task.wait(0.05)
            end
        until not Flags.LoopCombo or not Alive or Combo.token ~= token
        if Combo.token == token then
            Combo.running = false
        end
    end)
end

Root:Give(function()
    Combo.stop()
end)

----------------------------------------------------------------------------------------------------
-- Dribble keybind override [mine]
-- When one of the game's dribble keys (Z X C V, taken from the Moves table) is bound to a JHub dribble move or the
-- combo, the game must not also do its own dribble from that key. Two layers:
--   1. A ContextActionService sink at very high priority, so the game's own input handlers see the key as already
--      used. Only bound dribble keys are sunk; unbound keys and every other key are untouched.
--   2. A __namecall gate on InputService.Dribble: FireServer calls made by game code are dropped while a bound key
--      is held (or was released a moment ago) AND the call's input string contains that key's letter. Calls made
--      by JHub itself pass through, and so do game dribbles on keys that have no JHub bind.
-- Unverified on a live match: the sink only helps if the game reads keys through ContextActionService or checks
-- gameProcessed, and the gate only helps if the game fires the remote with remote:FireServer(...). Both layers
-- are there so that either one is enough.
----------------------------------------------------------------------------------------------------
local ContextActionService = game:GetService("ContextActionService")

local Override = {
    keyNames = function()
        return {}
    end, -- replaced once the window exists: returns the key names bound to dribble moves and the combo
    letters = {}, -- [letter] = true while that game dribble key has a JHub bind
    pads = {}, -- [button name] = KeyCode while that controller button has a JHub dribble bind
    padSeen = {}, -- [button name] = os.clock() when a bound controller button was last pressed or seen held
    seen = {}, -- [letter] = os.clock() when a bound key was last pressed or seen held
    holdWindow = 0.6, -- seconds after release in which game-made dribbles on that key are still dropped
    signature = "",
    action = "JHub_DribbleOverride",
}

local DribbleKeys = {}
for _, move in ipairs(Moves) do
    for letter in move.input:gmatch("%a") do
        DribbleKeys[letter:upper()] = true
    end
end

local function keyCodeOf(letter)
    local ok, code = pcall(function()
        return Enum.KeyCode[letter]
    end)
    return ok and code or nil
end

local function sinkInput()
    return Enum.ContextActionResult.Sink
end

function Override.refresh()
    local letters, list, pads, padList = {}, {}, {}, {}
    for _, name in ipairs(Override.keyNames()) do
        local raw = tostring(name)
        local letter = raw:upper()
        if #letter == 1 and DribbleKeys[letter] and not letters[letter] then
            letters[letter] = true
            list[#list + 1] = letter
        elseif (raw:sub(1, 6) == "Button" or raw:sub(1, 3) == "DPad") and not pads[raw] then
            -- A controller button bound to a dribble move: the game's own controller dribble on it must not also play.
            local code = keyCodeOf(raw)
            if code then
                pads[raw] = code
                padList[#padList + 1] = raw
            end
        end
    end
    table.sort(list)
    table.sort(padList)
    local signature = table.concat(list, ",") .. "|" .. table.concat(padList, ",")
    if signature == Override.signature then
        return
    end
    Override.signature = signature
    Override.letters = letters
    Override.pads = pads
    if #padList > 0 then
        warn("[JHub] Controller dribble binds are replacing the game's: " .. table.concat(padList, ", "))
    end
    pcall(ContextActionService.UnbindAction, ContextActionService, Override.action)
    if #list > 0 or #padList > 0 then
        local codes = {}
        for _, letter in ipairs(list) do
            local code = keyCodeOf(letter)
            if code then
                codes[#codes + 1] = code
            end
        end
        for _, raw in ipairs(padList) do
            codes[#codes + 1] = pads[raw]
        end
        if #codes > 0 then
            pcall(ContextActionService.BindActionAtPriority, ContextActionService, Override.action, sinkInput, false, 4000, table.unpack(codes))
        end
    end
end

local function letterHeld(letter, now)
    if not Override.letters[letter] then
        return false
    end
    local code = keyCodeOf(letter)
    if code and UserInputService:IsKeyDown(code) then
        return true
    end
    return now - (Override.seen[letter] or -math.huge) < Override.holdWindow
end

-- Called from the gate with the arguments of a game-made InputService.Dribble call.
function Override.shouldDrop(first)
    local now = os.clock()
    -- A bound controller button was just pressed: the game's own controller dribble combos (Z X C V) are dropped for a
    -- moment, so the move on that button is the only one played. Hand switches ("H") and everything else pass.
    if next(Override.pads) ~= nil then
        for name in pairs(Override.pads) do
            local held = now - (Override.padSeen[name] or -math.huge) < Override.holdWindow
            if held then
                if type(first) ~= "string" then
                    return true
                end
                for letter in first:gmatch("%a") do
                    if DribbleKeys[letter:upper()] then
                        return true
                    end
                end
                break
            end
        end
    end
    if next(Override.letters) == nil then
        return false
    end
    if type(first) == "string" then
        for letter in first:gmatch("%a") do
            if letterHeld(letter:upper(), now) then
                return true
            end
        end
        return false
    end
    for letter in pairs(Override.letters) do -- unknown argument shape: drop anything while a bound key is down
        if letterHeld(letter, now) then
            return true
        end
    end
    return false
end

function Override.step()
    Override.refresh()
    local now = os.clock()
    for name, code in pairs(Override.pads) do
        local okDown, down = pcall(function()
            return UserInputService:IsGamepadButtonDown(Enum.UserInputType.Gamepad1, code)
        end)
        if okDown and down then
            Override.padSeen[name] = now
        end
    end
    for letter in pairs(Override.letters) do
        local code = keyCodeOf(letter)
        if code and UserInputService:IsKeyDown(code) then
            Override.seen[letter] = now
        end
    end
end

Root:Give(UserInputService.InputBegan:Connect(function(input)
    if input.UserInputType == Enum.UserInputType.Keyboard then
        local letter = input.KeyCode.Name
        if Override.letters[letter] then
            Override.seen[letter] = os.clock() -- also when the key was already used by the UI or the game
        end
    elseif Override.pads[input.KeyCode.Name] then
        Override.padSeen[input.KeyCode.Name] = os.clock() -- controller button, also when the game already used it
    end
end))

Root:Give(function()
    Override.keyNames = function()
        return {}
    end
    Override.refresh()
    local gate = Env.__JHubDribbleGate
    if gate then
        gate.enabled = false -- the hook stays installed but inert, same as the clutch gate
    end
end)

local function installDribbleGate()
    local dribble = remote("InputService", "Dribble")
    if not dribble then
        return false, "InputService.Dribble not found. Game dribble blocking gated."
    end
    if type(hookmetamethod) ~= "function" or type(newcclosure) ~= "function" or type(getnamecallmethod) ~= "function" then
        return false, "hookmetamethod/newcclosure/getnamecallmethod unavailable. Only the input sink is active for dribble binds."
    end
    local gate = Env.__JHubDribbleGate
    if not gate then
        gate = { enabled = false, remote = nil, installed = false, drop = nil }
        Env.__JHubDribbleGate = gate
    end
    gate.remote = dribble
    gate.drop = Override.shouldDrop
    gate.enabled = true
    if not gate.installed then
        local original
        original = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            if gate.enabled and self == gate.remote and getnamecallmethod() == "FireServer" then
                if not (checkcaller and checkcaller()) then
                    local ok, drop = pcall(gate.drop, ...)
                    if ok and drop then
                        return nil
                    end
                end
            end
            return original(self, ...)
        end))
        gate.installed = true
    end
    return true
end

----------------------------------------------------------------------------------------------------
-- Defense: auto block, auto guard
----------------------------------------------------------------------------------------------------
local Block = { connections = {}, last = 0 }

-- [live] The game's own Space key (Input/Keyboard module) fires InputService.Shoot with
-- { Shoot = true, Input = "E", UseSpace = true }, then InputService.Jump with NO arguments, and on key up
-- InputService.Shoot with { Shoot = false }. Auto Block used to send Jump(true) and Jump(false), which is not
-- what the game sends. Not confirmed to produce a block on this build: no in-range opponent shot was available to test.
local BLOCK_RELEASE_DELAY = 0.15 -- [orig] hold time before the key-up equivalent
local function pressBlockJump()
    fire("InputService", "Shoot", { Shoot = true, Input = "E", UseSpace = true })
    fire("InputService", "Jump")
    task.delay(BLOCK_RELEASE_DELAY, function()
        fire("InputService", "Shoot", { Shoot = false }) -- always released, even if JHub unloads in between
    end)
end

local function onShooterAction(model)
    if not Alive or not Flags.AutoBlock or os.clock() - Block.last < 0.8 then
        return
    end
    local function shooting()
        local action = model:GetAttribute("Action") or ""
        return action == "Shooting" or action == "Dunking"
    end
    if not shooting() then
        return
    end
    task.wait(Flags.BlockDelay / 1000) -- [orig] pump fake filter
    if not Alive or not Flags.AutoBlock or not shooting() or not model.Parent then
        return
    end
    local mine = Ctx.char
    if not mine or Ctx.hasBall then -- with the ball, the same input would start a dunk or shot
        return
    end
    if Flags.BlockTeamCheck and sameTeam(mine, model) then
        return
    end
    local myHrp, theirHrp = mine:FindFirstChild("HumanoidRootPart"), model:FindFirstChild("HumanoidRootPart")
    if not myHrp or not theirHrp or (myHrp.Position - theirHrp.Position).Magnitude > Flags.BlockRange then
        return
    end
    Block.last = os.clock()
    local direction = (theirHrp.Position - myHrp.Position) * FLAT
    local _, movement = getProxy()
    if direction.Magnitude > 0.1 and movement then
        task.spawn(function()
            for _ = 1, 10 do
                if not Alive or not movement.Parent then
                    break
                end
                movement.Velocity = direction.Unit * 30 -- [orig]
                RunService.Heartbeat:Wait()
            end
        end)
    end
    task.delay(0.05, pressBlockJump)
end

local function hookShooter(model)
    if Block.connections[model] or not isOtherCharacter(model) then
        return
    end
    Block.connections[model] = model:GetAttributeChangedSignal("Action"):Connect(function()
        task.spawn(guarded("Auto Block", "AutoBlock", onShooterAction), model)
    end)
end

local function bindBlock()
    if not Characters then
        return
    end
    for _, model in ipairs(Characters:GetChildren()) do
        hookShooter(model)
    end
    Root:Give(Characters.ChildAdded:Connect(function(model)
        task.wait(0.5)
        hookShooter(model)
    end))
    Root:Give(Characters.ChildRemoved:Connect(function(model)
        local connection = Block.connections[model]
        if connection then
            connection:Disconnect()
            Block.connections[model] = nil
        end
    end))
    Root:Give(function()
        for _, connection in pairs(Block.connections) do
            pcall(connection.Disconnect, connection)
        end
        Block.connections = {}
    end)
end

local Guard = { vector = nil, lastSprint = 0, targetModel = nil, attackedHoop = nil, keyDown = false }

-- [mine] Auto Guard used to wait for you to hold G yourself. It now holds the real G key while it has a target,
-- so the game puts you in the guard stance and the movement override has something to steer.
local function setGuardKey(down)
    if down and UserInputService:GetFocusedTextBox() then
        down = false -- never type G into chat
    end
    if Guard.keyDown == down then
        return
    end
    Guard.keyDown = down
    local ok, vim = pcall(game.GetService, game, "VirtualInputManager")
    if ok and vim then
        pcall(vim.SendKeyEvent, vim, down, Enum.KeyCode.G, false, game)
    end
    -- [fix] A fake G key only reaches the game's keyboard handler. While you play on a controller the game listens to the
    -- gamepad handler instead (L2 by default), so the stance never started. Then send what both handlers send: the HoldG
    -- remote. On keyboard and mouse nothing changes, the key press alone is enough there (and was before).
    local okLast, lastInput = pcall(function()
        return UserInputService:GetLastInputType()
    end)
    if okLast and lastInput and string.find(lastInput.Name, "Gamepad", 1, true) then
        fire("InputService", "HoldG", { HoldingG = down })
    end
end
Root:Give(function()
    setGuardKey(false)
end)
local Farm = { vector = nil } -- Auto Farm state, filled in by the Auto Farm section
local GUARD_MIN_HEADING_SPEED = 2 -- [mine] studs/s below which the target's facing is used instead of its velocity
local GUARD_HOOP_SWITCH_MARGIN = 0.35 -- [mine] dot-product lead another hoop needs before the guard switches sides

local function chooseGuardTarget()
    local mine = Ctx.char
    local best, bestDistance = nil, math.huge
    local others = Ctx.getOthers()
    Tel.sample("guard.cand_others", #others)
    for _, other in ipairs(others) do
        local eligible = not (Flags.GuardTeamCheck and sameTeam(mine, other.model))
        if not eligible then
            Tel.count("guard.cand_same_team")
        elseif Flags.GuardBallOnly then
            eligible = holdsBall(other.model)
            if not eligible then
                Tel.count("guard.cand_no_ball")
            end
        end
        if eligible then
            local distance = (Ctx.hrp.Position - other.hrp.Position).Magnitude
            if distance < bestDistance then
                best, bestDistance = other, distance
            end
        end
    end
    if not best and not Tel.noTargetDumped then
        Tel.noTargetDumped = true
        local rows = { ("me team=%s teamIndex=%s"):format(tostring(mine:GetAttribute("Team")), tostring(mine:GetAttribute("TeamIndex"))) }
        for i = 1, math.min(#others, 8) do
            local m = others[i].model
            rows[#rows + 1] = ("%s team=%s teamIndex=%s holdsBall=%s"):format(m.Name, tostring(m:GetAttribute("Team")), tostring(m:GetAttribute("TeamIndex")), tostring(holdsBall(m)))
        end
        Tel.event(("Auto Guard found no target. %d other characters: %s"):format(#others, table.concat(rows, "; ")))
    end
    return best
end

-- [live] every character has Attributes.Goal, an ObjectValue whose Value is the Part Workspace.Hoops._HoopN.Goal.
-- Team 1 pointed at _Hoop1 and team 2 at _Hoop2; the one ball handler seen (team 1) stood near _Hoop1 with the
-- defenders. That reads as "the hoop this player scores on", but only that single sample supports it.
local function targetGoalPosition(model)
    local folder = model:FindFirstChild("Attributes")
    local goal = folder and folder:FindFirstChild("Goal")
    local part = goal and goal:IsA("ObjectValue") and goal.Value
    if part and part:IsA("BasePart") and part:IsDescendantOf(Workspace) and finiteVector(part.Position) then
        return part.Position
    end
    return nil
end

-- The hoop the target is attacking is the one the guard must stand in front of. Hoops.nearest was wrong here:
-- on the target's own half the nearest hoop is the one they defend, which put the guard behind them.
local function chooseAttackedHoop(target)
    local goal = targetGoalPosition(target.model)
    if goal then
        Tel.count("guard.hoop_goal")
        return goal
    end
    -- [mine] fallback when the target has no usable Goal: the hoop they are moving or facing toward.
    Tel.count("guard.hoop_fallback")
    local list = Hoops.list
    if #list == 0 then
        return nil
    end
    if #list == 1 then
        return list[1]
    end
    local position = target.hrp.Position
    local heading = target.hrp.AssemblyLinearVelocity * FLAT
    if heading.Magnitude < GUARD_MIN_HEADING_SPEED then
        heading = target.hrp.CFrame.LookVector * FLAT
    end
    if heading.Magnitude < 1e-3 then
        return Guard.attackedHoop
    end
    heading = heading.Unit
    local best, bestScore, previousScore = nil, -math.huge, nil
    for _, hoop in ipairs(list) do
        local toHoop = (hoop - position) * FLAT
        if toHoop.Magnitude > 0.5 then
            local score = heading:Dot(toHoop.Unit)
            if score > bestScore then
                best, bestScore = hoop, score
            end
            if hoop == Guard.attackedHoop then
                previousScore = score
            end
        end
    end
    if best and previousScore and best ~= Guard.attackedHoop and bestScore - previousScore < GUARD_HOOP_SWITCH_MARGIN then
        return Guard.attackedHoop -- hysteresis: don't flip sides while the target turns or stops
    end
    return best
end

local function stepGuard()
    Guard.vector = nil
    if not Flags.AutoGuard or not Ctx.char or not Ctx.hrp then
        if not Farm.gHeld then -- Auto Farm's Hold G owns the key while it has it down
            setGuardKey(false)
        end
        return
    end
    Tel.count("guard.frames_on")
    -- With Auto Farm on, the Auto Farm "Hold G" option decides whether G is pressed at all, so turning it off there really
    -- turns it off even if Auto Guard is still on from an old saved setting.
    local farmOwnsG = Flags.AutoFarm and not Flags.FarmHoldG
    if Flags.GuardHoldG and not farmOwnsG then
        local wantG = chooseGuardTarget() ~= nil
        -- [mine] The game drops the guard stance by itself after a shot, a block or a jump, while our key state still
        -- says "down", so the key was never pressed again and the guard did not resume after a missed shot and rebound.
        -- If the game says we are not guarding for a moment while we want to, release the key so it presses fresh.
        local now = os.clock()
        if Guard.keyDown and wantG and Ctx.char:GetAttribute("HoldingG") ~= true then
            Guard.notHeldSince = Guard.notHeldSince or now
            if now - Guard.notHeldSince > 0.25 then
                setGuardKey(false)
                Guard.notHeldSince = nil
                Guard.rePress = now
            end
        else
            Guard.notHeldSince = nil
        end
        if wantG and Guard.rePress and now - Guard.rePress < 0.05 then
            wantG = false -- one frame up so the game sees a new key press
        end
        setGuardKey(wantG)
    elseif Guard.keyDown and not Farm.gHeld then
        setGuardKey(false)
    end
    if not (Ctx.char:GetAttribute("HoldingG") or Guard.keyDown) then -- [live] HoldingG is false when G is not held
        Guard.targetModel, Guard.attackedHoop = nil, nil
        return
    end
    Tel.count("guard.frames_g")
    local target = chooseGuardTarget()
    if not target then
        Tel.count("guard.no_target")
        Guard.targetModel, Guard.attackedHoop = nil, nil
        return
    end
    Tel.count("guard.frames_target")
    if Guard.targetModel ~= target.model then
        Guard.targetModel, Guard.attackedHoop = target.model, nil
    end
    local camera = Workspace.CurrentCamera
    if not camera then
        Tel.count("guard.no_camera")
        return
    end
    local hoop = chooseAttackedHoop(target)
    if not hoop then
        Tel.count("guard.no_hoop")
        return
    end
    if Guard.attackedHoop and Guard.attackedHoop ~= hoop then
        Tel.count("guard.hoop_switches")
    end
    Guard.attackedHoop = hoop
    if flatDistance(Ctx.hrp.Position, hoop) < flatDistance(target.hrp.Position, hoop) then
        Tel.count("guard.between")
    end
    local predicted = target.hrp.Position + target.hrp.AssemblyLinearVelocity * FLAT * 0.25 -- [orig]
    local toHoop = (hoop - predicted) * FLAT
    local stand = predicted
    if toHoop.Magnitude > 0.5 then
        stand = predicted + toHoop.Unit * math.min(Flags.GuardDist or Defaults.GuardDist or 4, toHoop.Magnitude) -- never past the hoop
    end
    local delta = (stand - Ctx.hrp.Position) * FLAT
    local magnitude = delta.Magnitude
    if magnitude < 1e-3 then
        Tel.count("guard.at_stand")
        return
    end
    -- Camera-relative move vector built from the camera's flattened axes so a pitched camera doesn't shrink it.
    local cameraCFrame = camera.CFrame
    local look = cameraCFrame.LookVector * FLAT
    if look.Magnitude < 1e-3 then
        look = cameraCFrame.UpVector * FLAT -- camera pointing straight up or down
    end
    local right = cameraCFrame.RightVector * FLAT
    if look.Magnitude < 1e-3 or right.Magnitude < 1e-3 then
        return
    end
    look, right = look.Unit, right.Unit
    local direction = delta.Unit
    Guard.vector = Vector3.new(direction:Dot(right), 0, -direction:Dot(look)) * math.clamp(magnitude, 0.1, 1)
    Tel.count("guard.vector_frames")
    Tel.sample("guard.stand_error", magnitude)
    Tel.sample("guard.target_dist", flatDistance(Ctx.hrp.Position, target.hrp.Position))
end

local ControlsOverride = { installed = false }

local function installControlsOverride()
    if ControlsOverride.installed then
        return true
    end
    local scripts = LocalPlayer:FindFirstChild("PlayerScripts")
    local playerModule = scripts and scripts:FindFirstChild("PlayerModule")
    if not playerModule then
        return false, "PlayerModule not found. Auto Guard gated."
    end
    local ok, module = pcall(require, playerModule)
    if not ok then
        return false, "PlayerModule could not be required. Auto Guard gated."
    end
    local gotControls, controls = pcall(function()
        return module:GetControls()
    end)
    if not gotControls or type(controls) ~= "table" or type(controls.GetMoveVector) ~= "function" then
        return false, "Controls.GetMoveVector not found. Auto Guard gated."
    end
    local original = controls.GetMoveVector
    local function wrapper(self, ...)
        local base = original(self, ...)
        local farmVector = Farm.vector
        if Alive and Flags.AutoFarm and farmVector and typeof(base) == "Vector3" then
            return farmVector -- Auto Farm drives movement completely
        end
        local vector = Guard.vector
        Tel.count("guard.wrapper_calls")
        if Alive and Flags.AutoGuard and vector and typeof(base) == "Vector3" then
            Tel.count("guard.wrapper_applied")
            local strength = math.clamp((Flags.GuardStrength or Defaults.GuardStrength or 4) / 10, 0, 1)
            return vector * strength + base * (1 - strength)
        end
        return base
    end
    controls.GetMoveVector = wrapper
    ControlsOverride.installed = true
    Root:Give(function()
        if controls.GetMoveVector == wrapper then
            controls.GetMoveVector = original
        end
    end)
    return true
end

local function stepGuardSprint()
    if not (Flags.GuardSprint and Flags.AutoGuard and Ctx.char) or Flags.AutoFarm then
        return
    end
    -- [mine] original fired Sprint every frame; now only when the character is not already sprinting
    if (Ctx.char:GetAttribute("HoldingG") or Guard.keyDown) and not Ctx.char:GetAttribute("Sprinting") and os.clock() - Guard.lastSprint > 0.25 then
        Guard.lastSprint = os.clock()
        fire("InputService", "Sprint", true) -- [orig]
    end
end

----------------------------------------------------------------------------------------------------
-- Local player: attribute writers and anti clutch
----------------------------------------------------------------------------------------------------
-- [orig] These write attributes on the local character. Whether the server honours them is unverified.
local function writeAttribute(char, name, value)
    if char:GetAttribute(name) ~= value then
        char:SetAttribute(name, value)
    end
end

local function stepAttributes()
    local char = Ctx.char
    if not char then
        return
    end
    if Flags.InfStamina then writeAttribute(char, "Stamina", 100) end
    if Flags.AutoTakeover then writeAttribute(char, "TakeoverFill", 100) end
    if Flags.NoCold then writeAttribute(char, "Cold", false) end
    if Flags.NoDebounce then writeAttribute(char, "Debounce", false) end
    if Flags.NoStun then
        writeAttribute(char, "CanMove", true)
        writeAttribute(char, "CanTurn", true)
    end
end

local function installClutchGate()
    local clutch = remote("InputService", "Clutch")
    if not clutch then
        return false, "InputService.Clutch not found. Anti Clutch gated."
    end
    if type(hookmetamethod) ~= "function" or type(newcclosure) ~= "function" or type(getnamecallmethod) ~= "function" then
        return false, "hookmetamethod/newcclosure/getnamecallmethod unavailable. Anti Clutch gated."
    end
    local gate = Env.__JHubClutchGate
    if not gate then
        gate = { enabled = false, remote = nil, installed = false }
        Env.__JHubClutchGate = gate
    end
    gate.remote = clutch
    if not gate.installed then
        local original
        original = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            if gate.enabled and self == gate.remote and getnamecallmethod() == "FireServer" then
                local first = ...
                -- [orig] calls whose first argument is not `true` are dropped. [mine] only calls made by game code.
                if first ~= true and not (checkcaller and checkcaller()) then
                    return nil
                end
            end
            return original(self, ...)
        end))
        gate.installed = true
    end
    Root:Give(function()
        gate.enabled = false -- the hook stays installed but inert: it cannot be proven unreachable
    end)
    return true, gate
end

----------------------------------------------------------------------------------------------------
-- Visuals: lighting, camera, spectate, ESP, HUD
----------------------------------------------------------------------------------------------------
local Lights = { effects = {}, saved = nil }

local function applyPostEffects(remove)
    for _, child in ipairs(Lighting:GetChildren()) do
        if child:IsA("PostEffect") then
            if remove then
                if Lights.effects[child] == nil then
                    Lights.effects[child] = child.Enabled
                end
                child.Enabled = false
            elseif Lights.effects[child] ~= nil then
                child.Enabled = Lights.effects[child]
                Lights.effects[child] = nil
            end
        end
    end
end

local function applyFullbright(enabled)
    if enabled then
        if not Lights.saved then
            Lights.saved = {
                Ambient = Lighting.Ambient, OutdoorAmbient = Lighting.OutdoorAmbient,
                GlobalShadows = Lighting.GlobalShadows, Brightness = Lighting.Brightness,
            }
        end
        Lighting.Ambient = Color3.fromRGB(255, 255, 255)
        Lighting.OutdoorAmbient = Color3.fromRGB(255, 255, 255)
        Lighting.GlobalShadows = false
        Lighting.Brightness = 5
    elseif Lights.saved then
        for property, value in pairs(Lights.saved) do
            Lighting[property] = value -- [mine] restores what the place had, not hardcoded defaults
        end
        Lights.saved = nil
    end
end

Root:Give(function()
    applyPostEffects(false)
    applyFullbright(false)
end)

local Camera = { fovBefore = nil, subjectBefore = nil }

local function stepCamera()
    local camera = Workspace.CurrentCamera
    if not camera then
        return
    end
    if Flags.FOVEnabled then
        Camera.fovBefore = Camera.fovBefore or camera.FieldOfView
        camera.FieldOfView = Flags.FOVVal
    elseif Camera.fovBefore then
        camera.FieldOfView = Camera.fovBefore
        Camera.fovBefore = nil
    end
    if Flags.Spectating and Flags.SpectateTarget and Characters then
        local model = Characters:FindFirstChild(Flags.SpectateTarget)
        local head = model and model:FindFirstChild("Head")
        if head then
            Camera.subjectBefore = Camera.subjectBefore or camera.CameraSubject
            if camera.CameraSubject ~= head then
                camera.CameraSubject = head
            end
        end
    elseif Camera.subjectBefore then
        if Camera.subjectBefore.Parent then
            camera.CameraSubject = Camera.subjectBefore
        end
        Camera.subjectBefore = nil
    end
end

Root:Give(function()
    local camera = Workspace.CurrentCamera
    if camera and Camera.fovBefore then
        camera.FieldOfView = Camera.fovBefore
    end
    if camera and Camera.subjectBefore and Camera.subjectBefore.Parent then
        camera.CameraSubject = Camera.subjectBefore
    end
end)

local ESP = { folder = nil, items = {}, accumulator = 0 }
local MAX_HIGHLIGHTS = 30 -- [mine] stay under the engine's concurrent Highlight cap

local function clearESP()
    for model, highlight in pairs(ESP.items) do
        pcall(highlight.Destroy, highlight)
        ESP.items[model] = nil
    end
end

local function stepESP(dt)
    ESP.accumulator += dt
    if ESP.accumulator < 0.1 then
        return
    end
    ESP.accumulator = 0
    if not Flags.ESP or not Ctx.char then
        clearESP()
        return
    end
    if not ESP.folder or not ESP.folder.Parent then
        ESP.folder = Instance.new("Folder")
        ESP.folder.Name = "JHub_ESP"
        ESP.folder.Parent = guiParent()
    end
    local seen, count = {}, 0
    for _, other in ipairs(Ctx.getOthers()) do
        local model = other.model
        local teammate = sameTeam(Ctx.char, model)
        if count < MAX_HIGHLIGHTS and (Flags.ESPTeammates or not teammate) then
            count += 1
            seen[model] = true
            local highlight = ESP.items[model]
            if not highlight or not highlight.Parent then
                highlight = Instance.new("Highlight")
                highlight.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop
                highlight.FillTransparency = 0.75
                highlight.OutlineTransparency = 0
                highlight.Adornee = model
                highlight.Parent = ESP.folder
                ESP.items[model] = highlight
            end
            local color = teammate and Colors.Teammate or Colors.Opponent
            if holdsBall(model) then
                color = Colors.BallCarrier
            end
            highlight.FillColor, highlight.OutlineColor = color, color
        end
    end
    for model, highlight in pairs(ESP.items) do
        if not seen[model] then
            pcall(highlight.Destroy, highlight)
            ESP.items[model] = nil
        end
    end
end

Root:Give(function()
    clearESP()
    if ESP.folder then ESP.folder:Destroy() end
end)

local HUD = { gui = nil, label = nil, accumulator = 0 }

local function destroyHUD()
    if HUD.gui then
        HUD.gui:Destroy()
    end
    HUD.gui, HUD.label = nil, nil
end

local function stepHUD(dt)
    HUD.accumulator += dt
    if HUD.accumulator < 0.2 then
        return
    end
    HUD.accumulator = 0
    if not Flags.HUD then
        destroyHUD()
        return
    end
    if not HUD.gui or not HUD.gui.Parent then
        local gui = Instance.new("ScreenGui")
        gui.Name = "JHub_HUD"
        gui.ResetOnSpawn = false
        gui.IgnoreGuiInset = true
        gui.DisplayOrder = 9990
        local label = Instance.new("TextLabel")
        label.BackgroundColor3 = Color3.fromRGB(12, 12, 16)
        label.BackgroundTransparency = 0.25
        label.BorderSizePixel = 0
        label.Position = UDim2.fromOffset(10, 10)
        label.Size = UDim2.fromOffset(250, 128)
        label.TextXAlignment = Enum.TextXAlignment.Left
        label.TextYAlignment = Enum.TextYAlignment.Top
        label.Font = Enum.Font.Code
        label.TextSize = 13
        label.TextColor3 = Color3.fromRGB(215, 215, 225)
        label.Parent = gui
        Instance.new("UIPadding", label).PaddingLeft = UDim.new(0, 8)
        gui.Parent = guiParent()
        HUD.gui, HUD.label = gui, label
    end
    local char = Ctx.char
    local lines = {
        ("JHub %s  ping %dms"):format(VERSION, math.floor(LocalPlayer:GetNetworkPing() * 1000 + 0.5)),
        ("action: %s   ball: %s"):format(Ctx.action == "" and "-" or Ctx.action, Ctx.hasBall and "yes" or "no"),
        ("hoop: %s / range %d"):format(Ctx.hoopDist < math.huge and ("%.1f"):format(Ctx.hoopDist) or "n/a", Flags.ShootRange),
        ("meter: %s  thr %.3f"):format(Meter.kind, Thresholds[Meter.kind] or 0),
        char and ("team: %s/%s  InGame: %s"):format(tostring(char:GetAttribute("TeamIndex")), tostring(char:GetAttribute("Team")), tostring(char:GetAttribute("InGame"))) or "team: no character",
        ("proxy: %s"):format(proxyAlive() and "ok" or (type(getgc) == "function" and "not found" or "no getgc")),
    }
    HUD.label.Text = table.concat(lines, "\n")
end

Root:Give(destroyHUD)

local AFK = { connection = nil }

local function setAntiAFK(enabled)
    if enabled and not AFK.connection then
        AFK.connection = LocalPlayer.Idled:Connect(function()
            local ok, virtualUser = pcall(game.GetService, game, "VirtualUser")
            if ok and virtualUser then
                virtualUser:CaptureController()
                virtualUser:ClickButton2(Vector2.new())
            end
        end)
    elseif not enabled and AFK.connection then
        AFK.connection:Disconnect()
        AFK.connection = nil
    end
end

Root:Give(function()
    setAntiAFK(false)
end)

do
----------------------------------------------------------------------------------------------------
-- Match reports (sent to the Discord webhook in ReportCfg)
----------------------------------------------------------------------------------------------------
local function fmtSample(key, digits)
    local s = Tel.samples[key]
    if not s or s.n == 0 then
        return "no samples"
    end
    local f = "avg %." .. (digits or 2) .. "f  min %." .. (digits or 2) .. "f  max %." .. (digits or 2) .. "f  (n=%d)"
    return f:format(s.sum / s.n, s.min, s.max, s.n)
end

local function sampleAvg(key)
    local s = Tel.samples[key]
    return s and s.n > 0 and s.sum / s.n or nil
end

function Tel.reset()
    Tel.counts, Tel.samples, Tel.onTime, Tel.events, Tel.errors = {}, {}, {}, {}, {}
    Tel.startedAt = os.clock()
    Tel.matchIndex += 1
    Tel.finished = false
    Tel.errorSent = false
    Tel.pendingError = false
    Tel.noTargetDumped = false
    if Farm.Rec then
        Farm.Rec.matchStart = os.time() -- the capture file sent with the report covers events from here
    end
end

local function describeExecutor()
    local name, version = "unknown", ""
    if type(identifyexecutor) == "function" then
        local ok, n, v = pcall(identifyexecutor)
        if ok then
            name, version = tostring(n), tostring(v or "")
        end
    end
    return name .. " " .. version
end

local function findIssues()
    local issues = {}
    local function add(text)
        issues[#issues + 1] = text
    end
    local c, on = Tel.counts, Tel.onTime
    local function n(key)
        return c[key] or 0
    end

    -- Auto Guard pipeline: flag on -> G held -> target found -> hoop + camera -> vector -> controls override applied
    if (on.AutoGuard or 0) > 3 then
        if n("guard.frames_g") == 0 then
            add(("Auto Guard was on for %.0fs but the HoldingG attribute was never true (G not detected, or you never held it)."):format(on.AutoGuard))
        elseif n("guard.frames_target") == 0 then
            local others = sampleAvg("guard.cand_others") or 0
            add(("Auto Guard: G was held (%d frames) but no target was found. Other characters per frame: %.1f. Rejected as teammates: %d, rejected for not holding the ball: %d. (Team Check: %s, Ball Handler Only: %s)"):format(n("guard.frames_g"), others, n("guard.cand_same_team"), n("guard.cand_no_ball"), tostring(Flags.GuardTeamCheck), tostring(Flags.GuardBallOnly)))
        elseif n("guard.frames_target") > 0 and n("guard.vector_frames") == 0 then
            add(("Auto Guard: target found but no move vector was built (no hoop: %d frames, no camera: %d frames)."):format(n("guard.no_hoop"), n("guard.no_camera")))
        elseif n("guard.vector_frames") > 0 and n("guard.wrapper_applied") == 0 then
            add(("Auto Guard: a vector was built (%d frames) but the Controls.GetMoveVector override never applied it. Override installed: %s, wrapper calls: %d."):format(n("guard.vector_frames"), tostring(ControlsOverride.installed), n("guard.wrapper_calls")))
        end
        if n("guard.vector_frames") > 60 then
            local between = n("guard.between") / n("guard.vector_frames")
            if between < 0.4 then
                add(("Auto Guard: you were between the target and the hoop only %.0f%% of guard frames, so it may be standing on the wrong side."):format(between * 100))
            end
            if n("guard.hoop_switches") / n("guard.vector_frames") > 0.02 then
                add(("Auto Guard: the attacked hoop flipped %d times, so it is probably switching sides."):format(n("guard.hoop_switches")))
            end
            local err = sampleAvg("guard.stand_error")
            if err and err > 8 then
                add(("Auto Guard: average distance to the stand point was %.1f studs, so it is not converging on the target."):format(err))
            end
        end
    end
    if on.AutoGuard and not ControlsOverride.installed then
        add("Auto Guard is on but the controls override is NOT installed (PlayerModule or GetMoveVector problem).")
    end

    -- Auto features that should have fired a remote
    if ((on.AutoShoot or 0) > 10 or (on.PerfectTiming or 0) > 10) and (on._hasBall or 0) > 10 and n("fire.InputService.Shoot") == 0 then
        add(("Auto Shoot / Perfect Timing was on and you held the ball %.0fs but InputService.Shoot never fired."):format(on._hasBall))
    end
    if (on.AutoBlock or 0) > 120 and n("fire.InputService.Jump") == 0 then
        add("Auto Block was on for 2+ minutes and InputService.Jump never fired (may be normal if no shots happened near you).")
    end

    for key, value in pairs(c) do
        if string.sub(key, 1, 10) == "fire_fail." then
            add(("Remote %s errored %d times when fired."):format(string.sub(key, 11), value))
        elseif string.sub(key, 1, 13) == "fire_missing." then
            add(("Remote %s could not be found %d times."):format(string.sub(key, 14), value))
        end
    end
    for feature, e in pairs(Tel.errors) do
        add(("%s threw %d error(s). First: %s"):format(feature, e.count, (string.gsub(string.sub(e.first, 1, 160), "\n", " | "))))
    end
    if (on.SpeedEnabled or on.ShotGlide or on.DribbleGlide or on.AutoBlock) and not proxyAlive() then
        add("A feature that needs the physics proxy is on but the proxy was not found (getgc).")
    end
    local fps, ping = sampleAvg("fps"), sampleAvg("ping")
    if fps and fps < 25 then
        add(("Low average FPS: %.0f."):format(fps))
    end
    if ping and ping > 200 then
        add(("High average ping: %.0fms."):format(ping))
    end
    if not Characters then
        add("workspace.Characters was not found.")
    end
    if #Hoops.list == 0 then
        add("No hoops found in workspace.Hoops.")
    end
    return issues
end

function Tel.build(reason)
    local out = {}
    local function add(text)
        out[#out + 1] = text
    end
    local duration = os.clock() - Tel.startedAt
    local c, on = Tel.counts, Tel.onTime
    local issues = findIssues()

    add(("==== JHub match report #%d ===="):format(Tel.matchIndex))
    add("reason: " .. tostring(reason))
    add(("version: %s   duration: %.0fs   in match: %.0fs"):format(VERSION, duration, on._inGame or 0))
    add("executor: " .. describeExecutor())
    add("place: " .. tostring(game.PlaceId))
    add("")

    add(("---- FLAGGED ISSUES (%d) ----"):format(#issues))
    if #issues == 0 then
        add("none detected automatically")
    end
    for _, issue in ipairs(issues) do
        add("- " .. issue)
    end
    add("")

    add("---- features on this match (seconds enabled) ----")
    local names = {}
    for key in pairs(on) do
        if string.sub(key, 1, 1) ~= "_" then
            names[#names + 1] = key
        end
    end
    table.sort(names, function(a, b) return on[a] > on[b] end)
    for _, key in ipairs(names) do
        add(("%-16s %6.0fs"):format(key, on[key]))
    end
    if #names == 0 then
        add("none")
    end
    add(("holding ball: %.0fs   holding G: %.0fs"):format(on._hasBall or 0, on._holdingG or 0))
    add("")

    add("---- settings changed from defaults ----")
    local changed = {}
    for key, default in pairs(Defaults) do
        if Flags[key] ~= default then
            changed[#changed + 1] = ("%s = %s (default %s)"):format(key, tostring(Flags[key]), tostring(default))
        end
    end
    table.sort(changed)
    add(#changed > 0 and table.concat(changed, "\n") or "none")
    add("")

    add("---- Auto Guard diagnostics ----")
    local function g(key)
        return c["guard." .. key] or 0
    end
    add(("frames flag on: %d | G held: %d | target found: %d | no target: %d"):format(g("frames_on"), g("frames_g"), g("frames_target"), g("no_target")))
    add(("no camera: %d | no hoop: %d | vector built: %d | at stand point: %d"):format(g("no_camera"), g("no_hoop"), g("vector_frames"), g("at_stand")))
    add(("override installed: %s | wrapper calls: %d | wrapper applied: %d"):format(tostring(ControlsOverride.installed), g("wrapper_calls"), g("wrapper_applied")))
    add(("hoop from target Goal: %d | hoop fallback: %d | hoop switches: %d | between target and hoop: %d"):format(g("hoop_goal"), g("hoop_fallback"), g("hoop_switches"), g("between")))
    add(("candidates: %s | rejected same team: %d | rejected no ball: %d"):format(fmtSample("guard.cand_others", 1), g("cand_same_team"), g("cand_no_ball")))
    add("distance to stand point: " .. fmtSample("guard.stand_error"))
    add("distance to target: " .. fmtSample("guard.target_dist"))
    add("")

    add("---- remote activity ----")
    local remoteLines = {}
    for key, value in pairs(c) do
        if string.sub(key, 1, 5) == "fire." or string.sub(key, 1, 10) == "fire_fail." or string.sub(key, 1, 13) == "fire_missing." then
            remoteLines[#remoteLines + 1] = ("%s = %d"):format(key, value)
        end
    end
    table.sort(remoteLines)
    add(#remoteLines > 0 and table.concat(remoteLines, "\n") or "no remotes fired")
    add("")

    add("---- errors ----")
    local any = false
    for feature, e in pairs(Tel.errors) do
        any = true
        add(("[%s] x%d"):format(feature, e.count))
        add("first: " .. e.first)
        if e.last ~= e.first then
            add("last: " .. e.last)
        end
    end
    if not any then
        add("none")
    end
    add("")

    add("---- performance ----")
    add("fps: " .. fmtSample("fps", 0))
    add("ping ms: " .. fmtSample("ping", 0))
    add("")

    add("---- environment ----")
    local missing = {}
    for service, list in pairs({ Input = GameData.Remotes.Input, Meter = GameData.Remotes.Meter, Interface = GameData.Remotes.Interface, Player = GameData.Remotes.Player }) do
        for _, name in ipairs(list) do
            if not remote(service .. "Service", name) then
                missing[#missing + 1] = service .. "Service." .. name
            end
        end
    end
    add("missing remotes: " .. (#missing > 0 and table.concat(missing, ", ") or "none"))
    add(("proxy alive: %s | hoops: %d | Characters: %s | meter: %s"):format(tostring(proxyAlive()), #Hoops.list, tostring(Characters ~= nil), tostring(Meter and Meter.kind)))
    local shifted = {}
    for kind, value in pairs(Thresholds) do
        if value ~= GameData.Meter.Threshold[kind] then
            shifted[#shifted + 1] = ("%s %.3f (default %.3f)"):format(kind, value, GameData.Meter.Threshold[kind] or 0)
        end
    end
    add("thresholds moved by calibration: " .. (#shifted > 0 and table.concat(shifted, ", ") or "none"))
    local char = Ctx.char
    if char then
        local attrs = {}
        for _, name in ipairs({ "Action", "Debounce", "Stamina", "TakeoverFill", "Cold", "CanMove", "CanTurn", "HoldingG", "Sprinting", "TeamIndex", "Team", "InGame" }) do
            attrs[#attrs + 1] = name .. "=" .. tostring(char:GetAttribute(name))
        end
        add("character attributes: " .. table.concat(attrs, ", "))
    else
        add("character: none")
    end
    add("")

    add("---- timeline ----")
    add(#Tel.events > 0 and table.concat(Tel.events, "\n") or "no events")
    add("")

    add(("---- console (last %d lines) ----"):format(#Tel.console))
    add(table.concat(Tel.console, "\n"))

    local text = table.concat(out, "\n")
    if #text > 600000 then
        text = string.sub(text, -600000)
    end
    return text, issues
end

local function httpRequest(options)
    local fn = request or http_request or (syn and syn.request) or (http and http.request) or (fluxus and fluxus.request)
    if not fn then
        return nil, "no request function in this executor"
    end
    local ok, res = pcall(fn, options)
    if not ok then
        return nil, tostring(res)
    end
    return res
end

local function statusOk(res)
    local code = res and (res.StatusCode or res.status_code)
    return code == 200 or code == 204
end

local function postFile(summary, text, filename)
    local boundary = "JHub" .. string.gsub(HttpService:GenerateGUID(false), "-", "")
    local payload = HttpService:JSONEncode({ content = string.sub(summary, 1, 1900) })
    local body = "--" .. boundary .. "\r\nContent-Disposition: form-data; name=\"payload_json\"\r\nContent-Type: application/json\r\n\r\n" .. payload
        .. "\r\n--" .. boundary .. "\r\nContent-Disposition: form-data; name=\"files[0]\"; filename=\"" .. filename .. "\"\r\nContent-Type: text/plain\r\n\r\n" .. text
        .. "\r\n--" .. boundary .. "--\r\n"
    local res, err = httpRequest({
        Url = ReportCfg.Webhook,
        Method = "POST",
        Headers = { ["Content-Type"] = "multipart/form-data; boundary=" .. boundary },
        Body = body,
    })
    return statusOk(res), err or (res and tostring(res.StatusCode or res.status_code))
end

local function postChunks(summary, text)
    local size = 1800
    local total = math.min(math.ceil(#text / size), 12)
    local res, err = httpRequest({
        Url = ReportCfg.Webhook, Method = "POST", Headers = { ["Content-Type"] = "application/json" },
        Body = HttpService:JSONEncode({ content = string.sub(summary, 1, 1900) }),
    })
    if not statusOk(res) then
        return false, err or (res and tostring(res.StatusCode or res.status_code))
    end
    for i = 1, total do
        task.wait(0.7) -- Discord webhook rate limit
        res, err = httpRequest({
            Url = ReportCfg.Webhook, Method = "POST", Headers = { ["Content-Type"] = "application/json" },
            Body = HttpService:JSONEncode({ content = ("```\n%s\n```"):format(string.sub(text, (i - 1) * size + 1, i * size)) }),
        })
        if not statusOk(res) then
            return false, err or (res and tostring(res.StatusCode or res.status_code))
        end
    end
    return true
end

function Tel.send(reason)
    if string.find(ReportCfg.Webhook, "PASTE_", 1, true) then
        if not Tel.warnedNoHook then
            Tel.warnedNoHook = true
            warn("[JHub] Match reports are off: set ReportCfg.Webhook near the top of the script.")
            notify("JHub", "Match reports are off: webhook not set.", "Warning", 6)
        end
        return
    end
    if Tel.sending then
        return
    end
    local text, issues = Tel.build(reason)
    local summary = ("**JHub match #%d** (%s) - %d issue(s) flagged"):format(Tel.matchIndex, tostring(reason), #issues)
    for i = 1, math.min(#issues, 5) do
        summary = summary .. "\n- " .. string.sub(issues[i], 1, 200)
    end
    local filename = ("jhub_match_%d.txt"):format(Tel.matchIndex)
    local matchIndex = Tel.matchIndex
    Tel.sending = true
    Tel.lastSend = os.clock()
    task.spawn(function()
        local ok, why = postFile(summary, text, filename)
        if not ok then
            warn("[JHub] report upload failed (" .. tostring(why) .. "), retrying as text")
            ok, why = postChunks(summary, text)
        end
        if ok then
            notify("JHub", ("Match report #%d sent."):format(matchIndex), "Success", 3)
            -- Gameplay capture for this match, as its own file in the same channel. Never for error / periodic reports.
            if Flags.RecWebhook and Flags.RecOn and Farm.Rec and string.find(tostring(reason), "match ended", 1, true) then
                task.wait(1)
                pcall(function()
                    local capture = Farm.Rec.matchExport()
                    if capture then
                        local sent = postFile(("**JHub capture** %s, match #%d"):format(LocalPlayer.Name, matchIndex), capture,
                            ("jhub_capture_%s_%d.json"):format(LocalPlayer.Name, matchIndex))
                        if not sent then
                            postChunks(("**JHub capture** %s, match #%d"):format(LocalPlayer.Name, matchIndex), capture)
                        end
                    end
                end)
            end
        else
            warn("[JHub] report could not be sent: " .. tostring(why))
            if type(setclipboard) == "function" then
                pcall(setclipboard, text)
                notify("JHub", "Report send failed, copied to your clipboard instead.", "Warning", 6)
            end
        end
        Tel.sending = false
    end)
end

-- Console capture for the report (includes warn() output such as "[JHub] <feature> error")
pcall(function()
    local history = LogService:GetLogHistory()
    for i = math.max(1, #history - 40), #history do
        Tel.console[#Tel.console + 1] = "[history] " .. tostring(history[i].message)
    end
end)
Root:Give(LogService.MessageOut:Connect(function(message, messageType)
    local list = Tel.console
    list[#list + 1] = ("[%.1fs][%s] %s"):format(os.clock() - Tel.startedAt, (string.gsub(tostring(messageType), "Enum.MessageType.Message", "")), message)
    if #list > ReportCfg.ConsoleLines then
        table.remove(list, 1)
    end
end))

Root:Give(UserInputService.InputBegan:Connect(function(input, processed)
    if not processed and input.KeyCode == ReportCfg.Hotkey then
        Tel.send("manual (hotkey)")
    end
end))

local pingClock = 0
function Tel.step(dt)
    local on = Tel.onTime
    for key, value in pairs(Flags) do
        if value == true then
            on[key] = (on[key] or 0) + dt
        end
    end
    if dt > 0 then
        Tel.sample("fps", 1 / dt)
    end
    local char = Ctx.char
    if Ctx.hasBall then
        on._hasBall = (on._hasBall or 0) + dt
    end
    if char and char:GetAttribute("HoldingG") then
        on._holdingG = (on._holdingG or 0) + dt
    end
    pingClock += dt
    if pingClock >= 1 then
        pingClock = 0
        Tel.sample("ping", LocalPlayer:GetNetworkPing() * 1000)
    end

    -- Match start/end detection from the character's InGame attribute
    local inGame
    if char then
        Tel.lostSince = nil
        inGame = char:GetAttribute("InGame") == true
    else
        Tel.lostSince = Tel.lostSince or os.clock()
        inGame = os.clock() - Tel.lostSince < 4 and Tel.lastInGame == true
    end
    if inGame then
        on._inGame = (on._inGame or 0) + dt
    end
    if Tel.lastInGame == nil then
        Tel.lastInGame = inGame
        Tel.event("script started, InGame=" .. tostring(inGame))
    elseif inGame ~= Tel.lastInGame then
        Tel.lastInGame = inGame
        Tel.seenTransition = true
        if inGame then
            Tel.reset()
            Tel.event("match started (InGame became true)")
        else
            Tel.event("match ended (InGame became false)")
            if not Tel.finished and os.clock() - Tel.startedAt >= ReportCfg.MinMatchSeconds and os.clock() - Tel.lastSend > 15 then
                Tel.finished = true
                Tel.send("match ended")
            end
        end
    end

    if Tel.pendingError and not Tel.errorSent and os.clock() - Tel.lastSend > 30 then
        Tel.errorSent = true
        Tel.pendingError = false
        Tel.send("error during match")
    end
    if not Tel.seenTransition and os.clock() - Tel.lastAuto > ReportCfg.PeriodicSeconds then
        Tel.lastAuto = os.clock()
        Tel.send("periodic (no match start/end detected)")
    end
end


-- Result screen detection: PlayerGui.Summary.TextLabel stays enabled with stale text ("YOU WON") while idle,
-- but it is 0 high and fully transparent. Only fire when it actually appears, once per appearance.
local function resultShown()
    local gui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
    local summary = gui and gui:FindFirstChild("Summary")
    local label = summary and summary:FindFirstChild("TextLabel", true)
    if label and label:IsA("TextLabel") and summary.Enabled and label.Visible
        and (label.AbsoluteSize.Y > 0 or label.TextTransparency < 0.95) and label.Text ~= "" then
        return label.Text, ("size.Y=%.0f textTransparency=%.2f"):format(label.AbsoluteSize.Y, label.TextTransparency)
    end
    return nil
end
task.spawn(function()
    local shownBefore = false
    while Alive do
        task.wait(0.5)
        local ok, text, detail = pcall(resultShown)
        local shown = ok and text ~= nil
        if shown and not shownBefore and os.clock() - (Tel.lastResultAt or -math.huge) > 20 then
            Tel.lastResultAt = os.clock()
            Tel.event(("result screen appeared: %s (%s)"):format(string.sub(text, 1, 40), tostring(detail)))
            task.wait(2)
            Tel.send("match ended (result screen: " .. string.sub(text, 1, 30) .. ")")
            task.wait(1)
            Tel.reset()
        end
        shownBefore = shown
    end
end)

-- Startup check so you know the webhook works before the first match ends
task.delay(4, function()
    if Alive then
        Tel.send("startup check (webhook test)")
    end
end)
end

