----------------------------------------------------------------------------------------------------
-- Features merged in from JHub V1: Lag Switch (+ position marker), FPS Booster, V1 Auto Block
----------------------------------------------------------------------------------------------------

-- Lag Switch --------------------------------------------------------------------------------------
-- Holds back ReplicatedStorage.Replication (your position stream), so everyone else sees you frozen
-- while you keep moving. Turning it off snaps you back. While it is on, a marker shows the spot
-- where the others currently see you.
local Lag = { on = false, since = 0, char = nil, frozen = nil, ghost = nil, label = nil, toggle = nil,
    flushAt = 0, flushUntil = nil }

local function installLagGate()
    if type(hookmetamethod) ~= "function" or type(newcclosure) ~= "function" or type(getnamecallmethod) ~= "function" then
        return false, "hookmetamethod/newcclosure/getnamecallmethod unavailable. Lag Switch gated."
    end
    local rep = ReplicatedStorage:FindFirstChild("Replication")
    if not rep then
        return false, "ReplicatedStorage.Replication not found on this build. Lag Switch gated."
    end
    local gate = Env.__JHubLagGate
    if not gate then
        gate = { hold = false, remote = nil, installed = false }
        Env.__JHubLagGate = gate
    end
    gate.remote = rep
    if not gate.installed then
        local original
        original = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            if gate.hold and self == gate.remote and getnamecallmethod() == "FireServer" then
                return nil
            end
            return original(self, ...)
        end))
        gate.installed = true
    end
    return true
end

local function lagHold(hold)
    local gate = Env.__JHubLagGate
    if gate then
        gate.hold = hold
    end
end

local function clearLagGhost()
    if Lag.ghost then
        pcall(Lag.ghost.Destroy, Lag.ghost)
    end
    Lag.ghost, Lag.label = nil, nil
end

local function makeLagGhost(cframe)
    clearLagGhost()
    local part = Instance.new("Part")
    part.Name = "JHub_LagGhost"
    part.Anchored = true
    part.CanCollide = false
    part.CanQuery = false
    part.CanTouch = false
    part.Transparency = 1
    part.Size = Vector3.new(3, 5.5, 2)
    part.CFrame = cframe
    local box = Instance.new("BoxHandleAdornment")
    box.Adornee = part
    box.Size = part.Size
    box.AlwaysOnTop = true
    box.ZIndex = 5
    box.Transparency = 0.55
    box.Color3 = Color3.fromRGB(255, 60, 60)
    box.Parent = part
    local gui = Instance.new("BillboardGui")
    gui.Adornee = part
    gui.AlwaysOnTop = true
    gui.Size = UDim2.fromOffset(170, 46)
    gui.StudsOffset = Vector3.new(0, 4.5, 0)
    gui.Parent = part
    local label = Instance.new("TextLabel")
    label.BackgroundTransparency = 1
    label.Size = UDim2.fromScale(1, 1)
    label.Font = Enum.Font.GothamBold
    label.TextSize = 14
    label.TextColor3 = Color3.fromRGB(255, 90, 90)
    label.TextStrokeTransparency = 0.4
    label.Text = "LAG"
    label.Parent = gui
    part.Parent = Workspace.CurrentCamera or Workspace
    Lag.ghost, Lag.label = part, label
end

-- `assist` = switched on by Auto Farm's Lag Switch Assist. That path is separate from the Lag Switch tab: it does not
-- touch that tab's toggle, uses its own marker option, never stutters and shows no toasts.
function Lag.set(value, assist)
    value = value == true
    if value == Lag.on then
        return
    end
    if value then
        local ok, why = installLagGate()
        if not ok then
            if not assist then
                notify("Lag Switch", why, "Warning", 6)
            end
            return
        end
        local hrp = Ctx.hrp
        if not hrp then
            if not assist then
                notify("Lag Switch", "No character found.", "Warning", 4)
            end
            return
        end
        Lag.on, Lag.since, Lag.char = true, os.clock(), Ctx.char
        Lag.assist = assist == true
        Lag.frozen = hrp.Position
        Lag.flushAt = os.clock() + 0.5 + math.random() * 0.5
        Lag.flushUntil = nil
        lagHold(true)
        if (Lag.assist and Flags.FarmLagESP) or (not Lag.assist and Flags.LagESP) then
            makeLagGhost(hrp.CFrame)
        end
        if not Lag.assist then
            notify("Lag Switch", "ON - others see you frozen", "Info", 2)
        end
    else
        local wasAssist = Lag.assist
        Lag.on, Lag.assist = false, false
        lagHold(false)
        clearLagGhost()
        if not wasAssist then
            notify("Lag Switch", "OFF - snapped back", "Info", 2)
        end
    end
end

local function lagRelease(why)
    if not Lag.on then
        return
    end
    if Lag.toggle and not Lag.assist then
        Lag.toggle:SetValue(false)
    end
    Lag.set(false) -- no-op when the toggle callback already did it
    if why and not Lag.assist then
        notify("Lag Switch", why, "Info", 3)
    end
end

local function stepLag()
    if not Lag.on then
        return
    end
    local hrp = Ctx.hrp
    if not hrp or Ctx.char ~= Lag.char then
        lagRelease("Released: character changed")
        return
    end
    local now = os.clock()
    local elapsed = now - Lag.since
    if elapsed > (Lag.assist and 10 or Flags.LagMax) then
        lagRelease("Auto released")
        return
    end
    local wantEsp = Lag.assist and Flags.FarmLagESP or (not Lag.assist and Flags.LagESP)
    if not Lag.assist and Flags.LagStutter then
        if Lag.flushUntil then
            if now >= Lag.flushUntil then
                Lag.flushUntil = nil
                Lag.flushAt = now + 0.5 + math.random() * 0.5
                Lag.frozen = hrp.Position
                lagHold(true)
                if Lag.ghost then
                    Lag.ghost.CFrame = hrp.CFrame
                end
            end
        elseif now >= Lag.flushAt then
            Lag.flushUntil = now + 0.06
            lagHold(false)
        end
    end
    if wantEsp and not Lag.ghost then
        makeLagGhost(CFrame.new(Lag.frozen))
    elseif not wantEsp and Lag.ghost then
        clearLagGhost()
    end
    if Lag.label then
        Lag.label.Text = ("%s  %.1fs / %ds\n%d studs away"):format(Lag.assist and "FARM LAG" or "LAG", elapsed,
            Lag.assist and Farm.LAG_MAX or Flags.LagMax, math.floor((hrp.Position - Lag.frozen).Magnitude + 0.5))
    end
end

Root:Give(function()
    Lag.on = false
    lagHold(false)
    clearLagGhost()
end)

-- FPS Booster -------------------------------------------------------------------------------------
-- Master toggle applies whichever options are ticked and keeps cleaning up new objects as they appear.
-- Everything it changes is remembered and put back when the booster is turned off or JHub unloads.
local Gfx = { saved = setmetatable({}, { __mode = "k" }), queue = {}, qh = 1, qt = 0, tok = 0, active = false,
    quality = nil, capSet = false }
local GFX_EFFECTS = { ParticleEmitter = true, Trail = true, Beam = true, Fire = true, Smoke = true, Sparkles = true,
    PointLight = true, SpotLight = true, SurfaceLight = true }
local GFX_POST = { BloomEffect = true, BlurEffect = true, ColorCorrectionEffect = true, DepthOfFieldEffect = true,
    SunRaysEffect = true }

local function gset(inst, prop, value)
    local ok, current = pcall(function() return inst[prop] end)
    if not ok or current == value then
        return
    end
    local record = Gfx.saved[inst]
    if not record then
        record = {}
        Gfx.saved[inst] = record
    end
    if record[prop] == nil then
        record[prop] = current
    end
    pcall(function() inst[prop] = value end)
end

local function gfxSkipTexture(d)
    if Characters and d:IsDescendantOf(Characters) then
        return true
    end
    if string.find(string.lower(d.Name), "ball", 1, true) then
        return true
    end
    local parent = d.Parent
    return parent ~= nil and string.find(string.lower(parent.Name), "ball", 1, true) ~= nil
end

function Gfx.apply(d)
    if d:FindFirstAncestor("JHub_Visuals") or string.sub(d.Name, 1, 5) == "JHub_" then
        return
    end
    local class = d.ClassName
    if Flags.GfxEffects and GFX_EFFECTS[class] then
        gset(d, "Enabled", false)
        return
    end
    if Flags.GfxPost then
        if GFX_POST[class] then
            gset(d, "Enabled", false)
            return
        elseif class == "Atmosphere" then
            gset(d, "Density", 0)
            gset(d, "Haze", 0)
            gset(d, "Glare", 0)
            return
        end
    end
    if d:IsA("BasePart") then
        if Flags.GfxShadows then
            gset(d, "CastShadow", false)
        end
        if Flags.GfxTextures and not gfxSkipTexture(d) then
            gset(d, "Material", Enum.Material.SmoothPlastic)
            gset(d, "Reflectance", 0)
            if class == "MeshPart" then
                gset(d, "TextureID", "")
            end
        end
    elseif Flags.GfxTextures and (class == "Decal" or class == "Texture") then
        if not gfxSkipTexture(d) then
            gset(d, "Transparency", 1)
        end
    elseif Flags.GfxHideOthers and class == "Accessory" and Characters and d:IsDescendantOf(Characters)
        and not d:IsDescendantOf(Ctx.char or LocalPlayer) then
        for _, part in ipairs(d:GetDescendants()) do
            if part:IsA("BasePart") then
                gset(part, "Transparency", 1)
            end
        end
    end
end

function Gfx.restore()
    for inst, record in pairs(Gfx.saved) do
        for prop, value in pairs(record) do
            pcall(function() inst[prop] = value end)
        end
    end
    Gfx.saved = setmetatable({}, { __mode = "k" })
    if Gfx.quality ~= nil then
        pcall(function() settings().Rendering.QualityLevel = Gfx.quality end)
        Gfx.quality = nil
    end
end

function Gfx.sweep()
    local token = Gfx.tok
    task.spawn(function()
        local count = 0
        for _, root in ipairs({ Lighting, Workspace }) do
            for _, d in ipairs(root:GetDescendants()) do
                if token ~= Gfx.tok or not Alive then
                    return
                end
                pcall(Gfx.apply, d)
                count += 1
                if count % 400 == 0 then
                    task.wait()
                end
            end
        end
    end)
end

function Gfx.refresh()
    Gfx.tok += 1
    Gfx.restore()
    Gfx.active = Flags.GfxBoost == true
    if not Gfx.active then
        return
    end
    if Flags.GfxLow then
        pcall(function()
            local rendering = settings().Rendering
            if Gfx.quality == nil then
                Gfx.quality = rendering.QualityLevel
            end
            rendering.QualityLevel = Enum.QualityLevel.Level01
        end)
    end
    if Flags.GfxShadows then
        gset(Lighting, "GlobalShadows", false)
    end
    Gfx.sweep()
end

function Gfx.applyCap()
    if type(setfpscap) ~= "function" then
        return
    end
    local cap = tonumber(Flags.GfxFpsCap) or 0
    if cap > 0 then
        pcall(setfpscap, cap)
        Gfx.capSet = true
    elseif Gfx.capSet then
        pcall(setfpscap, 0) -- 0 = uncapped
        Gfx.capSet = false
    end
end

local function queueGfx(d)
    if Gfx.active then
        Gfx.qt += 1
        Gfx.queue[Gfx.qt] = d
    end
end
Root:Give(Workspace.DescendantAdded:Connect(queueGfx))
Root:Give(Lighting.DescendantAdded:Connect(queueGfx))

local function stepGfx()
    local handled = 0
    while Gfx.qh <= Gfx.qt and handled < 120 do
        local d = Gfx.queue[Gfx.qh]
        Gfx.queue[Gfx.qh] = nil
        Gfx.qh += 1
        if d and d.Parent then
            pcall(Gfx.apply, d)
        end
        handled += 1
    end
    if Gfx.qh > Gfx.qt then
        Gfx.queue, Gfx.qh, Gfx.qt = {}, 1, 0
    end
end

Root:Give(function()
    Gfx.tok += 1
    Gfx.active = false
    Gfx.restore()
    if Gfx.capSet and type(setfpscap) == "function" then
        pcall(setfpscap, 0)
    end
end)

-- Auto Block (V1 logic) ---------------------------------------------------------------------------
-- Watches every opponent's Action. Times the jump to the shooter's release, reads pump fakes, also
-- contests layups and dunks, and sends the game's own Jump call (arguments copied from a real press
-- when one has been seen, otherwise a plain Jump()).
local BLK = {
    COOLDOWN = 0.9, REACT_MIN = 0.02, REACT_MAX = 0.07, SLOW_CHANCE = 0.2, SLOW_MIN = 0.03, SLOW_MAX = 0.08,
    RELEASE = 0.48, PEAK = 0.35, LEAD = 0.04, FAKE_HOLD = 0.3, FLIP_WINDOW = 0.6, LIFT = 0.8, BALL_REACH = 5,
    SHOOTER_FACING = 0.25, OWN_FACING = -0.2, POINT_BLANK = 2.5, MAX_HEIGHT = 6,
}
local BLK_SHOTS = { Shooting = true, MovingShot = true }
local BLK_FINISHES = { Layup = 7, ContactLayup = 7, ClutchLayup = 7, Dunking = 6 }
local BLK_OWN_MOVES = {
    Dribbling = true, Shooting = true, Gathering = true, Dunking = true, ContactLayup = true, Layup = true,
    Passing = true, Stealing = true, Blocking = true, Jumping = true, Rebounding = true, CatchingPass = true,
    PassTransition = true, CatchingLob = true, AwaitingPass = true, Diving = true, Pushing = true, MovingShot = true,
}
local Blk = { last = -math.huge, state = {}, ping = 0.08, pingAt = 0, random = Random.new() }

local function installJumpCapture()
    if type(hookmetamethod) ~= "function" or type(newcclosure) ~= "function" or type(getnamecallmethod) ~= "function" then
        return false
    end
    local jump = remote("InputService", "Jump")
    if not jump then
        return false
    end
    local gate = Env.__JHubJumpCapture
    if not gate then
        gate = { enabled = true, remote = nil, installed = false, args = nil }
        Env.__JHubJumpCapture = gate
    end
    gate.remote = jump
    gate.enabled = true
    if not gate.installed then
        local original
        original = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
            if gate.enabled and self == gate.remote and getnamecallmethod() == "FireServer"
                and not (checkcaller and checkcaller()) then
                gate.args = table.pack(...)
            end
            return original(self, ...)
        end))
        gate.installed = true
    end
    return true
end

Root:Give(function()
    local gate = Env.__JHubJumpCapture
    if gate then
        gate.enabled = false
    end
end)

local function sendBlockJump()
    local gate = Env.__JHubJumpCapture
    local args = gate and gate.args
    if type(args) == "table" then
        fire("InputService", "Jump", table.unpack(args, 1, args.n or #args))
    else
        fire("InputService", "Jump")
    end
    Tel.count("block.sent")
end

local function blockPing(now)
    if now < Blk.pingAt then
        return Blk.ping
    end
    Blk.pingAt = now + 0.25
    local value
    local ok, raw = pcall(function()
        return game:GetService("Stats").Network.ServerStatsItem["Data Ping"]:GetValue()
    end)
    if ok and type(raw) == "number" and raw == raw and raw > 0 then
        value = raw / 1000
    else
        value = LocalPlayer:GetNetworkPing() * 2
    end
    value = math.min(value, 0.6)
    Blk.ping += (value - Blk.ping) * 0.3
    return Blk.ping
end

local function flat(v)
    return Vector3.new(v.X, 0, v.Z)
end

local function blockFree(character)
    if character:GetAttribute("Stunned") == true then
        return false
    end
    return character:GetAttribute("CanMove") ~= false or character:GetAttribute("Action") == "Dribbling"
end

local function blockForced(character)
    local action = character:GetAttribute("Action")
    if action == "Moving" or action == "Fouled" or action == "Inbounding" or action == "Stunned" then
        return true
    end
    if character:GetAttribute("CanMove") == false then
        return not (type(action) == "string" and BLK_OWN_MOVES[action])
    end
    return false
end

local function blockReact()
    local value = BLK.REACT_MIN + Blk.random:NextNumber() * (BLK.REACT_MAX - BLK.REACT_MIN)
    if Blk.random:NextNumber() < BLK.SLOW_CHANCE then
        value += BLK.SLOW_MIN + Blk.random:NextNumber() * (BLK.SLOW_MAX - BLK.SLOW_MIN)
    end
    return value
end

local function blockMetered(character)
    for _, child in ipairs(character:GetChildren()) do
        if child:IsA("BillboardGui") and child.Enabled and string.sub(child.Name, -5) == "Meter" then
            return true
        end
    end
    return false
end

local function goalPosition(character)
    local folder = character:FindFirstChild("Attributes")
    local value = folder and folder:FindFirstChild("Goal")
    if value and value:IsA("ObjectValue") then
        local target = value.Value
        if target and target:IsA("BasePart") then
            return target.Position
        elseif target and target:IsA("Model") then
            return target:GetPivot().Position
        end
    end
    return nil
end

local function blockBallNear(position, reach)
    local folder = Workspace:FindFirstChild("Basketballs")
    if not folder then
        return nil
    end
    local any = false
    for _, child in ipairs(folder:GetChildren()) do
        local part = nil
        if child:IsA("BasePart") then
            part = child
        elseif child:IsA("Model") then
            part = child.PrimaryPart
        end
        if part then
            any = true
            if (part.Position - position).Magnitude <= reach then
                return true
            end
        end
    end
    if any then
        return false
    end
    return nil
end

local function blockReachable(root, character, theirs, reach, finish)
    local here, there = root.Position, theirs.Position
    if math.abs(there.Y - here.Y) > BLK.MAX_HEIGHT then
        return false
    end
    local toMe = flat(here - there)
    local distance = toMe.Magnitude
    if distance > reach then
        return false
    end
    if distance < BLK.POINT_BLANK then
        return true
    end
    local direction = toMe / distance
    local look = flat(theirs.CFrame.LookVector)
    if look.Magnitude > 0.01 and look.Unit:Dot(direction) < BLK.SHOOTER_FACING then
        local goal = goalPosition(character)
        local aim = goal and flat(goal - there) or Vector3.zero
        if aim.Magnitude < 0.01 or aim.Unit:Dot(direction) < BLK.SHOOTER_FACING then
            return false
        end
    end
    local mine = flat(root.CFrame.LookVector)
    if mine.Magnitude > 0.01 and mine.Unit:Dot(-direction) < BLK.OWN_FACING then
        return false
    end
    if finish then
        local rim, rimDistance = Hoops.nearest(there)
        if rim and flat(rim - here).Magnitude > rimDistance + 1 then
            return false
        end
    end
    return true
end

local function stepBlock()
    if not Flags.AutoBlock then
        if next(Blk.state) ~= nil then
            Blk.state = {}
        end
        return
    end
    local mine, root = Ctx.char, Ctx.hrp
    if not mine or not root then
        Blk.state = {}
        return
    end
    local now = os.clock()
    local ping = blockPing(now)
    local ready = not Ctx.hasBall and (Ctx.action == "" or Ctx.action == nil) and blockFree(mine)
        and not blockForced(mine) and mine:GetAttribute("InAir") ~= true and now - Blk.last >= BLK.COOLDOWN
    local range = Flags.BlockRange or 10
    local extra = (Flags.BlockDelay or 0) / 1000
    local readFakes = Flags.BlockReadFakes == true
    local fresh = {}
    for _, other in ipairs(Ctx.getOthers()) do
        local character, theirs = other.model, other.hrp
        if not (Flags.BlockTeamCheck and sameTeam(mine, character)) then
            local entry = Blk.state[character] or {}
            fresh[character] = entry
            local released = character:GetAttribute("ReleasedShot")
            if entry.Released == true and released == false then
                entry.FlipAt = now
            end
            entry.Released = released
            local kind = character:GetAttribute("Action")
            local finish = type(kind) == "string" and BLK_FINISHES[kind] or nil
            if not (type(kind) == "string" and BLK_SHOTS[kind]) and not finish then
                entry.Start = nil
                if character:GetAttribute("InAir") ~= true then
                    entry.Floor = theirs.Position.Y
                end
            else
                if entry.Start == nil then
                    entry.Start, entry.Done, entry.SawFalse, entry.Wait = now, false, false, nil
                end
                if released == false then
                    entry.SawFalse = true
                end
                if released == true and entry.SawFalse then
                    entry.Done = true
                end
                if ready and not entry.Done then
                    local elapsed = now - entry.Start
                    local flip = entry.FlipAt
                    local freshFlip = released == false and flip ~= nil and flip >= entry.Start - BLK.FLIP_WINDOW
                    local confirmed = finish ~= nil or freshFlip or blockMetered(character)
                    local wait = entry.Wait
                    if not wait then
                        if finish then
                            wait = blockReact() * 0.5 + extra
                        else
                            local speed = character:GetAttribute("ShotSpeed")
                            local release = BLK.RELEASE / ((type(speed) == "number" and speed > 0.05) and speed or 1)
                            wait = math.max(0, release - BLK.PEAK - ping - BLK.LEAD) + blockReact() + extra
                        end
                        entry.Wait = wait
                    end
                    local go = elapsed >= wait and released ~= true
                    if go and not confirmed and readFakes then
                        local floor = entry.Floor
                        local up = character:GetAttribute("InAir") == true
                            or (floor ~= nil and theirs.Position.Y - floor > BLK.LIFT)
                        go = elapsed >= BLK.FAKE_HOLD and up
                    end
                    if go and not holdsBall(character) and blockBallNear(theirs.Position, BLK.BALL_REACH) == false then
                        go = false
                    end
                    if go and blockReachable(root, character, theirs, finish and math.min(range, finish) or range, finish ~= nil) then
                        Blk.last = now
                        entry.Done = true
                        sendBlockJump()
                        ready = false
                    end
                end
            end
        end
    end
    Blk.state = fresh
end

beatSteps[#beatSteps + 1] = guarded("Auto Block", "AutoBlock", stepBlock)
beatSteps[#beatSteps + 1] = guarded("Lag Switch", "LagSwitch", stepLag)
beatSteps[#beatSteps + 1] = guarded("FPS Booster", "GfxBoost", stepGfx)

----------------------------------------------------------------------------------------------------
-- Auto Farm (1v1): queue, play offense, guard, block, rebound, stats, webhook
-- [mine] Remotes verified live: InterfaceService.LeaveRec (RemoteFunction) leaves a finished Blacktop game and
-- lands in "Blacktop Matchmaking"; QueueService.Ready(true) there starts the match search ("Match found").
-- NOT verified in a live match: movement, shot timing, block timing, rebound, make detection.
----------------------------------------------------------------------------------------------------
Farm.FARM_DIR = "JHub"
Farm.FARM_FILE = "JHub/farm.json"
Farm.FARM_SOURCE_FILE = "JHub_Combined.lua"

function Farm.newStats()
    return { games = 0, wins = 0, losses = 0, shots = 0, makes = 0, threes = 0, threeMakes = 0, blocks = 0,
        steals = 0, rebounds = 0, perfects = 0, points = 0, oppPoints = 0 }
end

Farm.session, Farm.life, Farm.kinds = Farm.newStats(), Farm.newStats(), {}
Farm.hooked = {}
Farm.blockState = {}
Farm.pending = nil
Farm.holdSince = nil
Farm.latch = false
Farm.lastBlock, Farm.lastRebound, Farm.lastSprint, Farm.lastAction = -math.huge, -math.huge, 0, 0
Farm.wasLoose, Farm.oppHadBall, Farm.hadBall = false, false, false
Farm.gameCounted = true
Farm.queued = -math.huge
Farm.leaving = -math.huge
Farm.sessionStart = os.time()
Farm.hits = 0

-- Auto Execute: re-runs JHub after every teleport (queue_on_teleport) so it follows you through matchmaking and games.
-- Source, in order: getgenv().JHubReload (a string of Lua), then a saved copy of this script in your executor workspace.
Farm.AUTOEXEC_FILE = "JHub/autoexec.json"
Farm.autoExec = { armed = false }
Farm.AUTOEXEC_GATE = [[
local okRead, saved = pcall(function() return isfile("JHub/autoexec.json") and readfile("JHub/autoexec.json") end)
if okRead and type(saved) == "string" and string.find(saved, '"enabled":false', 1, true) then return end
]]

function Farm.autoExecSource()
    local source = Env.JHubReload
    if type(source) == "string" and source ~= "" then
        return source
    end
    if type(isfile) == "function" then
        for _, path in ipairs({ Farm.FARM_SOURCE_FILE, "JHub/JHub_Combined.lua" }) do
            if isfile(path) then
                return ('loadstring(readfile("%s"))()'):format(path)
            end
        end
    end
    return nil
end

function Farm.autoExecWanted()
    return Flags.AutoExecute == true or Farm.resuming == true or (Flags.AutoFarm == true and Flags.FarmQueue == true)
end

function Farm.autoExecRead()
    if type(isfile) ~= "function" or type(readfile) ~= "function" then
        return nil
    end
    local ok, data = pcall(function()
        if isfile(Farm.AUTOEXEC_FILE) then
            return game:GetService("HttpService"):JSONDecode(readfile(Farm.AUTOEXEC_FILE))
        end
    end)
    return ok and type(data) == "table" and data or nil
end

function Farm.autoExecApply(announce)
    local wanted = Farm.autoExecWanted()
    if type(writefile) == "function" then
        pcall(function()
            if type(makefolder) == "function" and type(isfolder) == "function" and not isfolder(Farm.FARM_DIR) then
                makefolder(Farm.FARM_DIR)
            end
            writefile(Farm.AUTOEXEC_FILE, game:GetService("HttpService"):JSONEncode({
                enabled = wanted, setting = Flags.AutoExecute == true,
            }))
        end)
    end
    if wanted then
        if Farm.autoExec.armed then
            return true
        end
        if type(queue_on_teleport) ~= "function" then
            if announce then
                notify("Auto Execute", "Your executor has no queue_on_teleport.", "Warning", 6)
            end
            return false
        end
        local source = Farm.autoExecSource()
        if not source then
            if announce then
                notify("Auto Execute", "No script source. Save this script as JHub_Combined.lua in your executor workspace, or set getgenv().JHubReload.", "Warning", 8)
            end
            return false
        end
        local ok = pcall(queue_on_teleport, Farm.AUTOEXEC_GATE .. source)
        Farm.autoExec.armed = ok
        if ok and announce then
            notify("Auto Execute", "On. JHub re-runs after every teleport.", "Success", 5)
        end
        return ok
    elseif Farm.autoExec.armed then
        Farm.autoExec.armed = false
        if type(clear_teleport_queue) == "function" then
            pcall(clear_teleport_queue)
        end
        -- anything still queued reads enabled=false from the file above and exits
        if announce then
            notify("Auto Execute", "Off.", "Success", 4)
        end
    end
    return true
end

function Farm.bump(key, amount)
    amount = amount or 1
    Farm.session[key] += amount
    Farm.life[key] += amount
end

-- Persistence --------------------------------------------------------------------------------------
function Farm.farmSave()
    if type(writefile) ~= "function" then
        return
    end
    pcall(function()
        if type(makefolder) == "function" and type(isfolder) == "function" and not isfolder(Farm.FARM_DIR) then
            makefolder(Farm.FARM_DIR)
        end
        writefile(Farm.FARM_FILE, game:GetService("HttpService"):JSONEncode({
            enabled = Flags.AutoFarm == true, life = Farm.life, kinds = Farm.kinds, style = Flags.FarmStyle,
        }))
    end)
end

function Farm.farmLoad()
    if type(isfile) ~= "function" or type(readfile) ~= "function" then
        return nil
    end
    local ok, data = pcall(function()
        if isfile(Farm.FARM_FILE) then
            return game:GetService("HttpService"):JSONDecode(readfile(Farm.FARM_FILE))
        end
    end)
    if ok and type(data) == "table" then
        return data
    end
    return nil
end


function Farm.pct(a, b)
    if b <= 0 then
        return "0%"
    end
    return ("%.0f%%"):format(a / b * 100)
end

function Farm.farmStatsText(stats)
    return ("W/L %d-%d | FG %d/%d (%s) | 3PT %d/%d (%s) | Blocks %d | Steals %d | Rebounds %d | Perfect %d"):format(
        stats.wins, stats.losses, stats.makes, stats.shots, Farm.pct(stats.makes, stats.shots),
        stats.threeMakes, stats.threes, Farm.pct(stats.threeMakes, stats.threes),
        stats.blocks, stats.steals, stats.rebounds, stats.perfects)
end

-- Match results and session summaries go to the executor console (warn, because the game filters plain print).
function Farm.farmPost(title, body)
    if not Flags.FarmWebhook then
        return
    end
    warn(("[JHub Farm] %s\n%s"):format(title, body))
end

function Farm.farmSessionSummary()
    local minutes = math.max(1, math.floor((os.time() - Farm.sessionStart) / 60))
    Farm.farmPost("Session summary", ("Session %dm, %d games\n%s\n\nLifetime: %s"):format(
        minutes, Farm.session.games, Farm.farmStatsText(Farm.session), Farm.farmStatsText(Farm.life)))
end

-- Scoring: a hoop's Goal attribute changing to a non-zero value is treated as a make on that hoop. [unverified]
function Farm.myHoopPosition()
    return (Ctx.char and goalPosition(Ctx.char)) or Ctx.hoopPos
end

function Farm.onGoal(model)
    if not Alive or not Flags.AutoFarm then
        return
    end
    local value = model:GetAttribute("Goal")
    if value == nil or value == 0 or value == false then
        return
    end
    local mine = Farm.myHoopPosition()
    local ok, pivot = pcall(model.GetPivot, model)
    if not mine or not ok then
        return
    end
    Farm.hits += 1
    if flat(pivot.Position - mine).Magnitude < 8 then
        local pending = Farm.pending
        local points = (pending and pending.three) and 3 or 2
        Farm.bump("points", points)
        if pending and os.clock() - pending.at < 6 then
            Farm.bump("makes")
            if pending.three then
                Farm.bump("threeMakes")
            end
            local kind = Farm.kinds[pending.kind]
            if kind then
                kind.made += 1
            end
            Farm.pending = nil
        end
    else
        Farm.bump("oppPoints", 2)
    end
end

function Farm.watchHoops()
    local folder = Workspace:FindFirstChild(GameData.HoopsFolder)
    if not folder then
        return
    end
    for _, model in ipairs(folder:GetChildren()) do
        if not Farm.hooked[model] then
            Farm.hooked[model] = true
            Root:Give(model:GetAttributeChangedSignal("Goal"):Connect(function()
                Farm.onGoal(model)
            end))
        end
    end
end

-- Geometry -----------------------------------------------------------------------------------------
function Farm.farmCameraVector(delta, strength)
    local camera = Workspace.CurrentCamera
    if not camera then
        return nil
    end
    local look = camera.CFrame.LookVector * FLAT
    if look.Magnitude < 1e-3 then
        look = camera.CFrame.UpVector * FLAT
    end
    local right = camera.CFrame.RightVector * FLAT
    if look.Magnitude < 1e-3 or right.Magnitude < 1e-3 or delta.Magnitude < 1e-3 then
        return nil
    end
    look, right = look.Unit, right.Unit
    local direction = delta.Unit
    return Vector3.new(direction:Dot(right), 0, -direction:Dot(look)) * math.clamp(strength or 1, 0.1, 1)
end

function Farm.farmOpponent()
    local best, bestDistance = nil, math.huge
    local root = Ctx.hrp
    if not root then
        return nil
    end
    for _, other in ipairs(Ctx.getOthers()) do
        if not (Ctx.char and sameTeam(Ctx.char, other.model)) then
            local distance = flatDistance(root.Position, other.hrp.Position)
            if distance < bestDistance then
                best, bestDistance = other, distance
            end
        end
    end
    return best, bestDistance
end

-- 2v2 Mode (man-to-man) -----------------------------------------------------------------------------
-- The bot picks the opponent nearest to it when the game starts and guards that one for the whole game, whoever has the
-- ball. Only if that player leaves does it pick the nearest opponent again. [uncalibrated]: written from the game's data
-- model, not yet watched in a live 2v2.
Farm.man = nil

function Farm.farmMan()
    local root = Ctx.hrp
    if not root then
        return nil
    end
    local others = Ctx.getOthers()
    if Farm.man then
        for _, other in ipairs(others) do
            if other.model == Farm.man and not (Ctx.char and sameTeam(Ctx.char, other.model)) then
                return other
            end
        end
        Farm.man = nil -- he left (or switched teams): choose again
    end
    local best = Farm.assignMan(others)
    if best then
        Farm.man = best.model
        warn("[JHub Farm] 2v2: guarding " .. tostring(best.model.Name))
    end
    return best
end

-- Who guards whom. When both teammates run JHub, each one must end up on a different opponent, with no way to talk to the
-- other. So every copy works out the SAME pairing from the same positions: the pairing of my team to their team with the
-- smallest total distance (ties go by name order), and then takes the opponent that belongs to me.
function Farm.assignMan(others)
    local root, me = Ctx.hrp, Ctx.char
    if not root or not me then
        return nil
    end
    local mates, foes = { { name = me.Name, pos = root.Position, mine = true } }, {}
    for _, other in ipairs(others) do
        if sameTeam(me, other.model) then
            mates[#mates + 1] = { name = other.model.Name, pos = other.hrp.Position }
        else
            foes[#foes + 1] = { name = other.model.Name, pos = other.hrp.Position, other = other }
        end
    end
    if #foes == 0 then
        return nil
    end
    table.sort(mates, function(a, b)
        return a.name < b.name
    end)
    table.sort(foes, function(a, b)
        return a.name < b.name
    end)
    local bestCost, bestMine = math.huge, nil
    local used = {}
    local function search(i, cost, mineFoe)
        if i > #mates then
            if cost < bestCost - 1e-6 then
                bestCost, bestMine = cost, mineFoe
            end
            return
        end
        local anyFree = false
        for j, foe in ipairs(foes) do
            if not used[j] then
                anyFree = true
                used[j] = true
                local d = flatDistance(mates[i].pos, foe.pos)
                search(i + 1, cost + d, mates[i].mine and foe or mineFoe)
                used[j] = false
            end
        end
        if not anyFree then
            search(i + 1, cost, mineFoe)
        end
    end
    search(1, 0, nil)
    return bestMine and bestMine.other or nil
end

-- Selects the 2v2 queue once in matchmaking (QueueService.SelectMode is what the game's own mode list calls).
function Farm.select2v2()
    if Farm.modeSelected and os.clock() - Farm.modeSelected < 60 then
        return
    end
    Farm.modeSelected = os.clock()
    local key = "2v2"
    local okInfo, ok, info = pcall(Farm.farmInvoke, "QueueService", "GetModes")
    if okInfo and ok == true and type(info) == "table" and type(info.Order) == "table" then
        for _, mode in ipairs(info.Order) do
            if string.find(string.lower(tostring(mode)), "2v2", 1, true) or string.find(string.lower(tostring(mode)), "2 v 2", 1, true) then
                key = mode
                break
            end
        end
    end
    local okSelect, called, success, message = pcall(Farm.farmInvoke, "QueueService", "SelectMode", key)
    warn(("[JHub Farm] 2v2: SelectMode(%s) -> %s %s %s"):format(tostring(key), tostring(called), tostring(success), tostring(message)))
end

function Farm.farmBall()
    local folder = Workspace:FindFirstChild("Basketballs")
    if not folder then
        return nil
    end
    for _, child in ipairs(folder:GetChildren()) do
        local part = child:IsA("BasePart") and child or (child:IsA("Model") and child.PrimaryPart) or nil
        if part and finiteVector(part.Position) then
            return part
        end
    end
    return nil
end

function Farm.farmStopSprint()
    if Ctx.char and Ctx.char:GetAttribute("Sprinting") and os.clock() - Farm.lastSprint > 0.3 then
        Farm.lastSprint = os.clock()
        fire("InputService", "Sprint", false)
    end
end

function Farm.farmSprint(moving)
    if moving and Ctx.char and not Ctx.char:GetAttribute("Sprinting") and os.clock() - Farm.lastSprint > 0.3 then
        Farm.lastSprint = os.clock()
        fire("InputService", "Sprint", true)
    end
end

-- Offense ------------------------------------------------------------------------------------------
Farm.KIND_SPOT = { Close = 5, Mid = 15, Three = 24 }

-- [live] Action values seen on the local character while holding the ball: "" (standing/moving with the ball),
-- "Dribbling" (a dribble move, ~0.8s), "Shooting", "ContactPlant", "PickingUp". Without the ball moving reads "Moving".
-- The shared canAct() demands Action == "" and so skipped every frame spent in a dribble move; the farm uses its own gate.
Farm.SHOOT_OK = { [""] = true, Dribbling = true } -- Dribbling allowed: [unverified] that the server accepts a shot from it
Farm.SHOT_ACTIONS = { Shooting = true, MovingShot = true, Layup = true, ContactLayup = true, ClutchLayup = true, Dunking = true }
Farm.LATCH_START_TIMEOUT = 0.9 -- [uncalibrated] seconds to wait for the shot Action to appear before the latch is dropped
Farm.LATCH_MAX = 3 -- [uncalibrated] hard cap on how long the latch can hold while the ball is still in hand
Farm.SHOT_CLOCK = 24 -- [clip] the possession clock starts at 24
Farm.FORCE_REMAINING = 5 -- [uncalibrated] seconds left on the clock at which a contested shot is accepted
Farm.SEP_MOVE_EVERY = 0.55 -- [uncalibrated] seconds between dribble moves while shaking the defender
Farm.SEP_SIDE_EVERY = 0.7 -- [uncalibrated] seconds before the sidestep flips direction
-- Take back: after a steal or defensive rebound the game recolours workspace.Map.Courts.<court>.<half>.Takeback to
-- RGB(255,89,89) (Court component OnUpdate "TakeBack") and the ball must be carried back before a shot counts.
-- [live] after a make the ball is handed over about 45 studs from the hoop; the Takeback mesh apex is about 36 studs out.
Farm.TAKEBACK_DIST = 42 -- [uncalibrated] flat distance from the hoop to carry the ball to
Farm.TAKEBACK_MAX = 44 -- stay inside the 45-stud hand-over spot so we do not walk out of bounds
Farm.latchAt, Farm.shotSeen, Farm.retries = -math.huge, false, 0

function Farm.canDribble()
    local char = Ctx.char
    if not char or not Ctx.hasBall or not Farm.SHOOT_OK[Ctx.action] then
        return false
    end
    return not char:GetAttribute("Debounce")
end

Farm.TAKEBACK_GRACE = 0.25 -- seconds after getting the ball before a shot is allowed, so the game's red line has time to show

function Farm.canShoot()
    if not Farm.canDribble() or Farm.takeBackRequired() then
        return false
    end
    -- The game recolours the line a moment after a steal or rebound. A shot in that first moment is a take back violation.
    return Farm.holdSince == nil or os.clock() - Farm.holdSince >= Farm.TAKEBACK_GRACE
end

function Farm.takeBackInstance(hoop)
    local tb = Farm.tbInst
    if tb and tb.Parent and Farm.tbHoop and flatDistance(Farm.tbHoop, hoop) < 5 then
        return tb
    end
    if os.clock() - (Farm.tbSearchAt or -math.huge) < 0.4 then -- was 3s: the line was unseen for seconds after it was recreated
        return nil
    end
    Farm.tbSearchAt = os.clock()
    local map = Workspace:FindFirstChild("Map")
    local courts = map and map:FindFirstChild("Courts")
    if not courts then
        return nil
    end
    local best, bestDistance
    for _, descendant in ipairs(courts:GetDescendants()) do
        if descendant.Name == "Takeback" and descendant:IsA("BasePart") then
            local distance = flatDistance(descendant.Position, hoop)
            if not bestDistance or distance < bestDistance then
                best, bestDistance = descendant, distance
            end
        end
    end
    if best then
        Farm.tbInst, Farm.tbHoop = best, hoop
    end
    return best
end

function Farm.takeBackRequired()
    local hoop = Farm.myHoopPosition()
    if not hoop then
        return false
    end
    local tb = Farm.takeBackInstance(hoop)
    if not tb then
        return false -- [unverified] no Takeback object found: treated as not required
    end
    -- The game fades the line in, so catch any clearly red tint instead of waiting for the final RGB(255,89,89).
    local color = tb.Color
    return color.R > 0.85 and color.R - color.G > 0.2 and color.R - color.B > 0.2
end

function Farm.farmKind(name)
    local entry = Farm.kinds[name]
    if not entry then
        entry = { att = 0, made = 0 }
        Farm.kinds[name] = entry
    end
    return entry
end

-- Smart mode: expected points with a Laplace prior, so it explores early and settles on what actually goes in.
function Farm.farmChooseKind()
    local style = Flags.FarmStyle
    if style == "Dunk" then
        return "Close"
    elseif style == "Threes" then
        return "Three"
    elseif style == "Mid-range" then
        return "Mid"
    end
    -- Smart: layups first. Threes are taken on top of this whenever he is wide (farmOffense); mid range only when forced.
    if true then
        return "Close"
    end
    local best, bestValue = "Close", -1
    for _, name in ipairs({ "Close", "Mid", "Three" }) do
        local entry = Farm.farmKind(name)
        local points = name == "Three" and 3 or 2
        local prior = name == "Close" and 0.6 or (name == "Mid" and 0.4 or 0.33)
        local value = points * (entry.made + prior * 4) / (entry.att + 4)
        if value > bestValue then
            best, bestValue = name, value
        end
    end
    return best
end

function Farm.farmShoot(kind, distance, retry)
    Farm.latch, Farm.latchKind = true, kind
    Farm.latchAt, Farm.shotSeen = os.clock(), false
    Meter.force()
    local three = distance >= 21.5
    if not retry then -- a retry re-sends the same attempt, it is not a new shot in the stats
        Farm.farmKind(kind).att += 1
        Farm.bump("shots")
        if three then
            Farm.bump("threes")
        end
        Farm.pending = { at = os.clock(), kind = kind, three = three }
        Farm.retries = 0
    end
    Tel.count(retry and "farm.shot_retry" or "farm.shot_fired")
    -- Odd retries send the other input style (space-jump <-> plain E) in case the first one is not accepted.
    local spaceStyle = (kind == "Close") ~= (retry == true and Farm.retries % 2 == 1)
    if spaceStyle then
        fire("InputService", "Shoot", { Shoot = true, Input = "E", UseSpace = true })
        fire("InputService", "Jump")
        -- [live] this used to release blindly after 0.15s, which graded 1 (very early, 0%) on every layup and also taught
        -- Auto Calibrate to release ever later. The meter releases it now; this is only the safety.
        task.delay(1.2, function()
            fire("InputService", "Shoot", { Shoot = false })
        end)
    else
        fire("InputService", "Shoot", { Shoot = true, Input = "E" })
        task.delay(1.2, function()
            fire("InputService", "Shoot", { Shoot = false }) -- safety release if the meter never fired
        end)
    end
end

-- [live] The game's own shot clock label: PlayerGui.UI.MainFrame.ShotclockFrame.Shotclock (text is the seconds left).
-- The old estimate counted from when the bot got the ball and let the clock run out (SHOTCLOCK VIOLATION in the clips).
function Farm.shotClockLeft()
    local ok, value = pcall(function()
        local label = Farm.clockLabel
        if not (label and label.Parent) then
            local gui = LocalPlayer:FindFirstChild("PlayerGui")
            local ui = gui and gui:FindFirstChild("UI")
            local main = ui and ui:FindFirstChild("MainFrame")
            local frame = main and main:FindFirstChild("ShotclockFrame")
            label = frame and frame:FindFirstChild("Shotclock")
            Farm.clockLabel = label
        end
        return label and tonumber(label.Text)
    end)
    return ok and value or nil
end

function Farm.shotClockForced(held)
    local left = Farm.shotClockLeft()
    if left then
        return left <= Farm.FORCE_REMAINING
    end
    return held >= Farm.SHOT_CLOCK - Farm.FORCE_REMAINING - 2
end

-- Open = the defender is far enough for this shot type, or is trailing us. A trailing defender still counts as a
-- contest unless he is at least 80% of the open distance away.
function Farm.isOpen(root, hoop, defender, kind, distance, defVel)
    if not defender then
        return true, math.huge
    end
    local defDistance = flatDistance(root.Position, defender)
    local need = Farm.KIND_OPEN[kind] or 5
    if kind == "Close" then
        -- a long run at the rim needs a bigger cushion: he closes the gap while we drive (+0.25 stud per stud of run)
        need += math.clamp((distance - 8) * 0.25, 0, 4)
    end
    -- Where he will be a moment from now. A defender who is sprinting at us is a contest even if he is still 6 studs off.
    local ahead = defender
    if typeof(defVel) == "Vector3" then
        ahead = defender + flat(defVel) * 0.4
    end
    local gap = math.min(defDistance, flatDistance(root.Position, ahead))
    -- [live] A defender BEHIND us (we are between him and the hoop, shooting away from him) cannot contest: shots from
    -- there are green every time. Taking one is always allowed once he is clearly behind and not on top of us.
    local toHoopDir = flat(hoop - root.Position)
    if toHoopDir.Magnitude > 0.5 then
        toHoopDir = toHoopDir.Unit
        local along = flat(defender - root.Position):Dot(toHoopDir) -- negative = behind us
        local alongAhead = flat(ahead - root.Position):Dot(toHoopDir)
        local behindBy = kind == "Close" and Farm.BEHIND_CLOSE or Farm.BEHIND_JUMPER
        if along <= -behindBy and alongAhead <= -0.5 and defDistance >= Farm.BEHIND_GAP then
            return true, math.max(gap, need + 0.1)
        end
    end
    local open = gap >= need
    -- a defender trailing behind us (farther from the hoop than we are) is a weaker contest than one in front. Never
    -- for a layup or dunk though: that is the chaser who gets a hand up at the rim.
    if kind ~= "Close" then
        local trailing = flatDistance(defender, hoop) > distance + 1.5
        if not open and gap >= need * (trailing and 0.85 or 0.95) then
            open = trailing or flatDistance(defender, hoop) > distance + 2
        end
    end
    return open, gap
end


Farm.BEHIND_JUMPER = 2 -- [uncalibrated] studs behind us (toward our own half) before a jumper counts as uncontested
Farm.BEHIND_CLOSE = 3 -- same for layups and dunks, slightly stricter: a chaser can still block from behind
Farm.BEHIND_GAP = 2.5 -- but not if he is right on our back
Farm.KIND_OPEN = { Close = 6, Mid = 8, Three = 9 } -- defender distance that counts as open enough to shoot
Farm.KIND_ARC = { Close = 80, Mid = 70, Three = 60 } -- degrees either side of the court axis
Farm.ARC_STEPS = 13

function Farm.segmentDistance(point, a, b)
    local ab = flat(b - a)
    local length = ab.Magnitude
    if length < 0.1 then
        return flat(point - a).Magnitude
    end
    local t = math.clamp(flat(point - a):Dot(ab) / (length * length), 0, 1)
    return flat(point - (a + ab * t)).Magnitude
end

function Farm.onFloor(position)
    local params = RaycastParams.new()
    params.FilterType = Enum.RaycastFilterType.Exclude
    local ignore = {}
    local characters = Workspace:FindFirstChild(GameData.CharactersFolder)
    if characters then
        ignore[#ignore + 1] = characters
    end
    local balls = Workspace:FindFirstChild("Basketballs")
    if balls then
        ignore[#ignore + 1] = balls
    end
    params.FilterDescendantsInstances = ignore
    local ok, hit = pcall(Workspace.Raycast, Workspace, position + Vector3.new(0, 8, 0), Vector3.new(0, -40, 0), params)
    return ok and hit ~= nil
end

function Farm.farmFindSpot(root, hoop, opponent, radius, kind)
    local mine = root.Position
    local axis, far = nil, 0
    for _, other in ipairs(Hoops.list) do
        local d = flatDistance(other, hoop)
        if d > far + 1 then
            far, axis = d, flat(other - hoop)
        end
    end
    if not axis or axis.Magnitude < 1 then
        axis = flat(mine - hoop)
    end
    if axis.Magnitude < 0.5 then
        return nil
    end
    axis = axis.Unit
    local defender, defFuture
    if opponent then
        defender = opponent.hrp.Position
        defFuture = defender
    end
    local base = math.atan2(axis.Z, axis.X)
    local arc = Farm.KIND_ARC[kind] or 70
    local best, bestScore
    for i = 0, Farm.ARC_STEPS - 1 do
        local angle = base + math.rad(-arc + 2 * arc * i / (Farm.ARC_STEPS - 1))
        local spot = hoop + Vector3.new(math.cos(angle), 0, math.sin(angle)) * radius
        local travel = flatDistance(mine, spot)
        local score = -travel * 0.35
        if defender then
            score += math.min(flatDistance(defFuture, spot), 12) * 1.6
            if flatDistance(defender, spot) < travel * 0.9 then
                score -= 6 -- they beat me there
            end
            local lane = Farm.segmentDistance(defFuture, mine, spot)
            if lane < 4 then
                score -= (4 - lane) * 2.5 -- the way there runs through them
            end
        end
        if Farm.spot and flatDistance(Farm.spot, spot) < 2 then
            score += 3 -- stick with the plan unless something is clearly better
        end
        if (not bestScore or score > bestScore) and Farm.onFloor(Vector3.new(spot.X, mine.Y, spot.Z)) then
            best, bestScore = spot, score
        end
    end
    return best
end

-- Sidestep across the defender and fire a dribble move every SEP_MOVE_EVERY seconds until he is no longer on us.

-- Carry the ball back past the take back line. The game's own flag (Takeback recoloured) decides when it is done.

-- Dribble moves ------------------------------------------------------------------------------------
-- Singles only: no double crossovers, tweens or behind-the-back combos, they cost stamina and time.
-- [orig] argument shape: InputService.Dribble(input, sprinting, moveDirection). The letters come from this script's
-- own Moves list (Z/C = left/right cross, X = Step Back, ZXC/CXZ = spin). [unverified in a live match] that each one
-- plays the move named here; the recipe is at the end of this block.
Farm.MOVES_BY_HAND = { -- from the game's Dribbling.Input config, which depends on the hand holding the ball
    R = { Cross = "Z", Hesitation = "C", StepBack = "X", SpinLeft = "CXZ", SpinRight = "CXZ", BehindBack = "CX", DoubleCross = "ZZ" },
    L = { Cross = "C", Hesitation = "Z", StepBack = "X", SpinLeft = "ZXC", SpinRight = "ZXC", BehindBack = "ZX", DoubleCross = "CC" },
}
Farm.STEPBACK_EVERY = 3 -- seconds between step backs, it is a once-in-a-while move
Farm.MOVE_COOLDOWN = 1.9 -- [live] a spin holds the Dribbling action for ~0.75s and the bot barely moves during it. At 0.8s
-- the next move started the moment the last one ended, so the bot spun in place under the defender for 20s+.
-- 1.9s leaves about a second of real driving between moves.
Farm.moveAt, Farm.lastMove = -math.huge, nil

function Farm.moveInput(name)
    local hand = Ctx.char and Ctx.char:GetAttribute("Hand")
    local map = Farm.MOVES_BY_HAND[hand == "L" and "L" or "R"]
    return map[name] or map.Hesitation
end

function Farm.doMove(name)
    local now = os.clock()
    if now - Farm.moveAt < Farm.MOVE_COOLDOWN or not Farm.canDribble() then
        return false
    end
    Farm.moveAt, Farm.lastMove = now, name
    local hist = Farm.moveHist or {}
    table.insert(hist, 1, name)
    hist[3] = nil
    Farm.moveHist = hist
    Farm.sideFlip = -(Farm.sideFlip or 1) -- the drive direction alternates with every move
    Farm.farmSprint(true)
    fire("InputService", "Dribble", Farm.moveInput(name), true, Vector3.zero) -- always sprinting while dribbling
    Tel.count("farm.move." .. name)
    return true
end

-- +1 when the defender is on my right as I face `target`, -1 when on my left.
function Farm.defenderSide(root, target, defender)
    local forward = flat(target - root.Position)
    local toDefender = flat(defender - root.Position)
    if forward.Magnitude < 0.5 or toDefender.Magnitude < 0.1 then
        return 1
    end
    return forward.Unit:Cross(toDefender.Unit).Y < 0 and 1 or -1
end

-- Move choice: spin first, then hesitation and step back; the plain crossover only as a rare variety pick.
-- Never the same move twice in a row.
function Farm.pickMove(root, hoop, defender, kind, distance, radius, target)
    local toDefender = flat(defender - root.Position)
    local gap = toDefender.Magnitude
    local now = os.clock()
    -- a step back is the way to buy a three against a defender who is glued on: allowed wherever a three is in range
    local inZone = (kind ~= "Close" and distance <= radius + 3) or (distance >= 17 and distance <= Farm.MAX_RANGE)
    -- Spin to get past him, once the spin has made room in the shot zone a step back is the follow up.
    if Farm.lastMove == "SpinLeft" and now - Farm.moveAt < 3.2 and gap >= 4 and inZone
        and now - (Farm.stepBackAt or -math.huge) > Farm.STEPBACK_EVERY then
        Farm.stepBackAt = now
        return "StepBack"
    end
    -- Otherwise a weighted random pick that never repeats either of the last two moves, so it does not spam one move.
    -- BehindBack and DoubleCross are extra variety (the bot looked repetitive with four moves); inputs from the game's move list
    local weights = { SpinLeft = 40, Hesitation = 30, Cross = 25, BehindBack = 14, DoubleCross = 14 }
    local mix = Flags.FarmPlayLikeMe and Farm.Rec and Farm.Rec.moveMix()
    if mix then -- your own habits: each move weighted by how often you play it
        weights = {}
        for _, name in ipairs({ "SpinLeft", "Hesitation", "Cross", "BehindBack", "DoubleCross" }) do
            weights[name] = 10 + (mix[name] or 0) * 90
        end
    end
    if inZone and now - (Farm.stepBackAt or -math.huge) > Farm.STEPBACK_EVERY then
        weights.StepBack = mix and (10 + (mix.StepBack or 0) * 90) or 15
    end
    local hist = Farm.moveHist or {}
    for _, recent in ipairs(hist) do
        weights[recent] = nil
    end
    local total = 0
    for _, w in pairs(weights) do
        total += w
    end
    if total <= 0 then
        weights, total = { SpinLeft = 1, Hesitation = 1, Cross = 1 }, 3
    end
    local roll, pick = math.random() * total, "SpinLeft"
    for name, w in pairs(weights) do
        roll -= w
        if roll <= 0 then
            pick = name
            break
        end
    end
    if pick == "StepBack" then
        Farm.stepBackAt = now
    end
    return pick
end

-- Get away from a defender who is on us. When contested the bot goes wide: it picks the side he is not on, and
-- alternates through wing / baseline / top angles using the shot spot offset so it covers the whole half court.
function Farm.beatDefender(root, hoop, defender, kind, distance, radius, target)
    target = target or Farm.spot or hoop
    local forward = flat(target - root.Position)
    if forward.Magnitude < 0.5 then
        forward = flat(hoop - root.Position)
    end
    if forward.Magnitude < 0.5 then
        return
    end
    local dir = forward.Unit
    local side = Farm.defenderSide(root, target, defender)
    local left = Vector3.new(dir.Z, 0, -dir.X) -- left of the facing direction
    local lateral = left * side * ((Farm.sideFlip or 1) > 0 and 1 or -0.6) -- off his side, every other move a lighter cut back across
    local away = flat(root.Position - defender)
    -- swing wider the closer he is, and re-pick the side every couple of seconds so the bot roams the court
    -- Mostly forward at the target with a sidestep off his side. The old mix was mostly sideways and away from him, so
    -- the bot circled the defender instead of attacking the rim.
    local phase = math.floor(os.clock() / 2.2) % 3
    local wide = 0.55 + (phase == 1 and 0.35 or 0)
    local desired = lateral * wide + dir * 1.6
    if away.Magnitude > 0.1 then
        desired += away.Unit * 0.15
    end
    Farm.vector = Farm.farmCameraVector(desired, 1)
    Farm.farmSprint(true)
    if Flags.FarmSmartOffence then
        Farm.doMove(Farm.pickMove(root, hoop, defender, kind, distance, radius, target))
    end
end
-- Verify the moves in game: fire each Farm.MOVES entry with the ball and read which animation plays (Animator
-- AnimationPlayed, ids in the game's AnimationStore: Crossover, Spin, HalfSpin, StepBack ...). Fix Farm.MOVES if a
-- letter plays something else.

-- Carry the ball back past the take back line. The game's own flag (Takeback recoloured) decides when it is done.
function Farm.clearBall(root, hoop, defender, kind, distance)
    local axis, far = nil, 0
    for _, other in ipairs(Hoops.list) do
        local d = flatDistance(other, hoop)
        if d > far + 1 then
            far, axis = d, flat(other - hoop)
        end
    end
    if not axis or axis.Magnitude < 1 then
        axis = flat(root.Position - hoop)
    end
    if axis.Magnitude < 0.5 then
        return
    end
    local dist = math.min(Farm.TAKEBACK_DIST + (Farm.tbExtra or 0), Farm.TAKEBACK_MAX)
    local target = hoop + axis.Unit * dist
    local toTarget = flat(target - root.Position)
    if toTarget.Magnitude < 2 then
        Farm.tbAtTarget = Farm.tbAtTarget or os.clock()
        if os.clock() - Farm.tbAtTarget > 1.5 then -- still red at the target: go a little further back
            Farm.tbExtra = math.min((Farm.tbExtra or 0) + 2, Farm.TAKEBACK_MAX - Farm.TAKEBACK_DIST)
            Farm.tbAtTarget = os.clock()
        end
    else
        Farm.tbAtTarget = nil
    end
    if defender and flatDistance(root.Position, defender) < 5 then
        Farm.beatDefender(root, hoop, defender, kind, distance, Farm.KIND_SPOT[kind] or 15, target)
        return
    end
    if toTarget.Magnitude > 1 then
        Farm.vector = Farm.farmCameraVector(toTarget, 1)
        Farm.farmSprint(true)
    end
end

-- The offense. Order of business every frame the ball is in hand:
--   1. take back required (game flag)      -> carry the ball back, no shot
--   2. in range and open (or clock nearly out) -> shoot
--   3. defender on us                      -> beat him: sidestep plus one single dribble move at a time
--   4. otherwise                           -> walk to the best open spot for the chosen shot


Farm.SETTLE_SPEED = 3 -- studs/s: at or below this the shot counts as standing
Farm.SETTLE_MAX = 0.6 -- seconds to wait for the brake before shooting anyway

Farm.DUNK_START = 23.5 -- [live] free throw line = 23 studs from the hoop (FreeThrowCricle_L centre to hoop)
Farm.MAX_RANGE = 27 -- studs from the hoop; no shot is ever taken from farther out than this
Farm.CAMP_DIST = 13 -- [uncalibrated] a defender this close to the hoop is camping the rim
Farm.SUPER_WIDE = 14 -- [uncalibrated] defender this far away = nobody near: the three is taken from a wider band
Farm.SUPER_WIDE_FROM = 20.5 -- [uncalibrated] closest distance a super wide three is taken from (normally 23)
Farm.WIDE_THREE = 10 -- defender distance at which a three is taken from deep
Farm.STUCK_AFTER = 2.5 -- seconds contested before the bot resets back to the three point line
Farm.RETREAT_DIST = 25 -- [uncalibrated] distance from the hoop that counts as the three point line

-- Unit vector from my hoop toward the middle of the court (the other hoop), used to find the three point line.
function Farm.courtAxis(hoop)
    local hoops = Workspace:FindFirstChild("Hoops")
    local best
    if hoops then
        for _, h in ipairs(hoops:GetChildren()) do
            local ok, pivot = pcall(h.GetPivot, h)
            if ok then
                local d = flat(pivot.Position - hoop).Magnitude
                if d > 20 and (not best or d > best.d) then
                    best = { d = d, p = pivot.Position }
                end
            end
        end
    end
    if best then
        return flat(best.p - hoop).Unit
    end
    local me = Ctx.hrp and flat(Ctx.hrp.Position - hoop) or Vector3.new(1, 0, 0)
    return me.Magnitude > 0.1 and me.Unit or Vector3.new(1, 0, 0)
end

-- Lag Switch assist ---------------------------------------------------------------------------------------------
-- When he has stayed on us (contested) for LAG_AFTER seconds, hold the position stream so he guards the spot where we
-- appear frozen, drive around him to the rim, and send the stream again the moment the shot starts.
Farm.LAG_AFTER = 1.0 -- [uncalibrated] seconds contested before the lag switch is used
Farm.LAG_MAX = 2.5 -- [uncalibrated] never hold longer than this, whatever happens
Farm.LAG_COOLDOWN = 4 -- seconds between uses

function Farm.lagOff(why)
    Farm.lagMode = false
    Farm.lagOffAt = os.clock()
    if Lag.on and Lag.assist then -- only ever release our own lag, never one the user switched on in the Lag Switch tab
        Lag.set(false)
        Tel.count("farm.lag_off_" .. tostring(why))
    end
end

function Farm.lagOn(nowS, disguise)
    if Lag.on or Farm.lagBroken then
        return false
    end
    if not disguise and (not Flags.FarmLag or nowS - (Farm.lagOffAt or -math.huge) < Farm.LAG_COOLDOWN) then
        return false
    end
    if not installLagGate() then
        Farm.lagBroken = true -- no hookmetamethod here: stop trying
        return false
    end
    Lag.set(true, true) -- independent of the Lag Switch tab: its toggle stays as the user left it
    if not Lag.on then
        return false
    end
    Farm.lagMode, Farm.lagAt = true, nowS
    Tel.count("farm.lag_on")
    return true
end

-- Runs every farm frame. Releases on the shot, on losing the ball, on the time cap, or if the user switched it off.
function Farm.lagTick()
    if not Farm.lagMode then
        return
    end
    local nowS = os.clock()
    local why
    if not Flags.AutoFarm then
        why = "farm_off"
    elseif not Lag.on or not Lag.assist then
        Farm.lagMode = false -- released by the 10s safety, or the user took over with the Lag Switch tab
        return
    elseif not Ctx.hasBall and not Farm.disguise then -- a disguise spike is also used while guarding
        why = "ball_lost"
    elseif Farm.latch and Farm.SHOT_ACTIONS[Ctx.action] then
        why = "shot"
    elseif nowS - Farm.lagAt > Farm.LAG_MAX then
        why = "time"
    end
    if why then
        Farm.lagOff(why)
    end
end

-- Lag disguise ---------------------------------------------------------------------------------------------------
-- Short fake lag spikes at random moments, so that the lag the assist uses to get past a defender looks like this player
-- simply lags now and then. Never started, and cut short at once, when a good shot is coming or going up: those stay
-- perfectly smooth.
Farm.DISGUISE_EVERY = { 4, 11 } -- seconds between spikes (random in this range)
Farm.DISGUISE_LEN = { 0.25, 0.7 } -- how long a spike lasts

function Farm.goodShotSoon(nowS)
    if Farm.latch or Farm.pending or Farm.SHOT_ACTIONS[Ctx.action] or Ctx.action == "Shooting" then
        return true
    end
    -- an open look exists, or one was just in range: the next frames are probably the shot
    return nowS - (Farm.goodAt or -math.huge) < 1.0 or nowS - (Farm.approachAt or -math.huge) < 1.2
end

function Farm.disguiseTick()
    if not Flags.FarmLagDisguise or Farm.lagBroken then
        if Farm.disguise and Farm.lagMode then
            Farm.disguise = nil
            Farm.lagOff("disguise_off")
        end
        return
    end
    local nowS = os.clock()
    if Farm.disguise then
        if not Farm.lagMode then
            Farm.disguise = nil -- ended by something else (shot, ball lost, time cap)
        elseif nowS >= Farm.disguise.untilT or Farm.goodShotSoon(nowS) then
            Farm.disguise = nil
            Farm.lagOff("disguise")
        end
        return
    end
    if not Farm.disguiseNext then
        Farm.disguiseNext = nowS + Farm.DISGUISE_EVERY[1] + math.random() * (Farm.DISGUISE_EVERY[2] - Farm.DISGUISE_EVERY[1])
    end
    if nowS < Farm.disguiseNext or Lag.on or Farm.lagMode then
        return
    end
    local hrp = Ctx.hrp
    local opp = Farm.farmOpponent()
    local oppAction = opp and opp.model and opp.model:GetAttribute("Action")
    if not hrp or Ctx.char == nil or Farm.goodShotSoon(nowS) or Farm.takeBackRequired()
        or Ctx.char:GetAttribute("InAir") == true or (oppAction and Farm.SHOT_ACTIONS[oppAction]) then
        Farm.disguiseNext = nowS + 0.5 -- try again shortly
        return
    end
    local ball = Farm.farmBall()
    local rim = Farm.myHoopPosition()
    if rim and Ctx.hasBall and flatDistance(hrp.Position, rim) <= Farm.DUNK_START + 3 then
        Farm.disguiseNext = nowS + 0.5 -- near the rim with the ball: a shot is about to happen
        return
    end
    if ball and not Ctx.hasBall and not (opp and holdsBall(opp.model)) then
        Farm.disguiseNext = nowS + 0.5 -- loose ball (rebound): keep it smooth
        return
    end
    if Farm.lagOn(nowS, true) then
        local len = Farm.DISGUISE_LEN[1] + math.random() * (Farm.DISGUISE_LEN[2] - Farm.DISGUISE_LEN[1])
        Farm.disguise = { untilT = nowS + len }
        Farm.disguiseNext = nowS + len + Farm.DISGUISE_EVERY[1] + math.random() * (Farm.DISGUISE_EVERY[2] - Farm.DISGUISE_EVERY[1])
    else
        Farm.disguiseNext = nowS + 2
    end
end

function Farm.farmOffense(opponent)
    local root = Ctx.hrp
    local hoop = Farm.myHoopPosition()
    if not root or not hoop then
        return
    end
    if Farm.holdSince == nil then
        Farm.spot, Farm.spotAt = nil, 0
        Farm.drive, Farm.contestSince, Farm.driveAt = nil, nil, nil
    end
    Farm.holdSince = Farm.holdSince or os.clock()
    do
        local now, last = os.clock(), Farm.lastPos
        if last and now > last.t then
            Farm.moveSpeed = flat(root.Position - last.p).Magnitude / (now - last.t)
        end
        Farm.lastPos = { p = root.Position, t = now }
    end
    if Farm.latch then
        if Farm.latchKind == "Close" then
            -- dunk / layup: keep sprinting at the rim while space is held, do not stop and gather
            Farm.vector = Farm.farmCameraVector(flat(hoop - root.Position), 1)
            Farm.farmSprint(true)
        else
            Farm.vector = nil -- jumper: stand still while it goes up
        end
        return
    end
    local held = os.clock() - Farm.holdSince
    local distance = flatDistance(root.Position, hoop)
    local kind = Farm.chosen or Farm.farmChooseKind()
    Farm.chosen = kind
    local defender = opponent and opponent.hrp.Position

    -- Rim protector: he sits in the paint and does not come out to guard. A layup into him never opens up, so the bot
    -- used to spin and drive into the wall until the clock forced a bad shot. While he stays that deep and is not on
    -- us, take the open jumper from the three point line instead; if he steps out to guard, the normal drive resumes.
    if defender and Flags.FarmStyle == "Smart" and not Farm.takeBackRequired() then
        local gapNow = flatDistance(defender, root.Position)
        if flatDistance(defender, hoop) <= Farm.CAMP_DIST and gapNow >= Farm.KIND_OPEN.Three
            and distance >= 15 and distance <= Farm.MAX_RANGE then
            if kind ~= "Three" or Farm.drive then
                Farm.drive, Farm.contestSince, Farm.driveAt = nil, nil, nil
                Farm.spot, Farm.spotAt = nil, 0
                Tel.count("farm.camper")
            end
            kind = "Three"
            Farm.chosen = "Three"
        elseif kind == "Three" and Farm.campKind then
            Farm.chosen, kind = nil, "Close" -- he came out: back to attacking the rim
            Farm.spot, Farm.spotAt = nil, 0
        end
        Farm.campKind = kind == "Three" and flatDistance(defender, hoop) <= Farm.CAMP_DIST
    end

    if Farm.takeBackRequired() then
        Farm.clearBall(root, hoop, defender, kind, distance)
        return
    end
    Farm.tbExtra, Farm.tbAtTarget = nil, nil

    -- Stuck handling: if he has stayed on us for STUCK_AFTER seconds, stop forcing jumpers. Go back to the three point
    -- line (pulling him out with us), then attack the rim from there for a layup.
    local nowS = os.clock()
    local defVel = opponent and opponent.hrp.AssemblyLinearVelocity
    local _, contestGap = Farm.isOpen(root, hoop, defender, kind, distance, defVel)
    local contested = defender ~= nil and contestGap < (Farm.KIND_OPEN[kind] or 5)
    if contested and not Farm.drive then
        Farm.contestSince = Farm.contestSince or nowS
        if nowS - Farm.contestSince >= Farm.STUCK_AFTER then
            Farm.drive, Farm.driveAt = "retreat", nowS
        end
    elseif not contested and not Farm.drive then
        Farm.contestSince = nil
    end
    if Flags.FarmLag and contested and not Farm.lagMode and Farm.contestSince and nowS - Farm.contestSince >= Farm.LAG_AFTER
        and distance >= 8 and distance <= 32 and not Farm.takeBackRequired() and Farm.lagOn(nowS) then
        -- he is guarding us: freeze what he sees and go straight around him to the rim
        Farm.drive, Farm.driveAt = "attack", nowS
        Farm.chosen, kind = "Close", "Close"
        Farm.spot, Farm.spotAt = nil, 0
    end
    if Farm.drive == "retreat" then
        local axis = Farm.courtAxis(hoop)
        local left = Vector3.new(axis.Z, 0, -axis.X)
        local lateral = math.clamp(flat(root.Position - hoop):Dot(left), -10, 10)
        local line = hoop + axis * Farm.RETREAT_DIST + left * lateral
        local toLine = flat(line - root.Position)
        if distance >= Farm.RETREAT_DIST - 1.5 or nowS - Farm.driveAt > 3 or toLine.Magnitude < 1.5 then
            Farm.drive, Farm.driveAt = "attack", nowS
            Farm.chosen, kind = "Close", "Close"
            Farm.spot, Farm.spotAt = nil, 0
        else
            Farm.vector = Farm.farmCameraVector(toLine, 1)
            Farm.farmSprint(true)
            return
        end
    end
    if Farm.drive == "attack" then
        kind = "Close"
    end

    local radius = Farm.KIND_SPOT[kind]
    -- Contested shots are only taken when the clock is nearly out, or a drive has been fighting for 5s with no way past.
    -- (At the rim with a hand up is NOT a reason: the bot keeps spinning/driving to get free first.)
    local forced = Farm.shotClockForced(held)
    if Farm.drive == "attack" and nowS - Farm.driveAt > 8 then
        forced = true
    end
    if distance > Farm.MAX_RANGE then
        forced = false -- never a forced heave from this far out (e.g. right after the take-back): drive in instead
    end
    if forced then
        radius = math.max(radius, distance)
    end
    local open, defDistance = Farm.isOpen(root, hoop, defender, kind, distance, defVel)
    -- wide window: any open look inside the shot band is taken, not only the ones at the exact spot
    local inRange = distance <= radius + 3 and (kind == "Close" or distance >= radius - 5)
    if distance > Farm.MAX_RANGE then
        inRange = false
    end
    if kind == "Close" then
        -- dunk run: hold space from the free throw line (23 studs from the hoop) and keep driving at the rim
        inRange = distance <= Farm.DUNK_START
    end
    if forced and kind == "Close" and distance > 10 then
        -- clock or stuck: shoot from where we are, labelled by how far out that is
        kind = distance >= 21.5 and "Three" or "Mid"
        radius = math.max(Farm.KIND_SPOT[kind], distance)
        inRange = true
    elseif kind ~= "Three" and Farm.drive ~= "attack" and distance <= Farm.MAX_RANGE and defDistance >= Farm.WIDE_THREE
        and distance >= (defDistance >= Farm.SUPER_WIDE and Farm.SUPER_WIDE_FROM or 23) then
        -- wide open from deep: take the three
        kind, radius, open, inRange = "Three", Farm.KIND_SPOT.Three, true, true
    end
    if open and distance <= Farm.MAX_RANGE then
        Farm.approachAt = os.clock() -- an open look exists: the lag disguise keeps out of the way
    end
    if inRange and (open or forced) then
        Farm.goodAt = os.clock()
    end
    if inRange and (open or forced) and Farm.canShoot() then
        -- Plant before a jumper: shooting while moving makes the game use the (worse) moving shot. Brake first,
        -- shoot once nearly still; give up waiting after SETTLE_MAX so a shot is never lost to this. Layups and
        -- dunks (Close) keep their momentum.
        local speed = Farm.moveSpeed or 99 -- measured from position deltas; AssemblyLinearVelocity reads 0 on this character
        Farm.settleAt = Farm.settleAt or os.clock()
        if kind ~= "Close" and speed > Farm.SETTLE_SPEED and os.clock() - Farm.settleAt < Farm.SETTLE_MAX then
            Farm.vector = Vector3.zero
            return
        end
        Farm.settleAt = nil
        Farm.vector = kind == "Close" and Farm.farmCameraVector(flat(hoop - root.Position), 1) or nil
        Farm.farmShoot(kind, distance)
        return
    end
    Farm.settleAt = nil

    local now = os.clock()
    if not Farm.spot or now - (Farm.spotAt or 0) > 0.2 then
        Farm.spotAt = now
        Farm.spot = Farm.farmFindSpot(root, hoop, opponent, radius, kind) or Farm.spot
    end
    if defender and not open and defDistance < (Farm.KIND_OPEN[kind] or 5) + 3 then
        Farm.beatDefender(root, hoop, defender, kind, distance, radius, Farm.spot)
        return
    end
    local toSpot = Farm.spot and flat(Farm.spot - root.Position) or flat(hoop - root.Position)
    local desired
    if toSpot.Magnitude > 1 then
        desired = toSpot.Unit
    else
        local radial = flat(root.Position - hoop)
        if radial.Magnitude > 0.1 then
            desired = -radial.Unit * math.clamp((distance - radius) / 3, -1, 1)
        end
    end
    if desired and desired.Magnitude > 0.05 then
        Farm.vector = Farm.farmCameraVector(desired, 1)
        Farm.farmSprint(true)
    end
end

-- Defense ------------------------------------------------------------------------------------------
Farm.FARM_SHOTS = { Shooting = true, MovingShot = true }
Farm.FARM_FINISH = { Layup = true, ContactLayup = true, ClutchLayup = true, Dunking = true }
-- [live] the receiver of a lob (including a self lob) has Action CatchingLob while waiting for the ball in the air;
-- AwaitingPass is the same wait for a normal alley-oop. The game's own code treats both as "going for the ball".
-- [live] a self lob (alley-oop) goes: Passing (ball thrown at the rim) -> +0.3s CatchingLob -> +0.7s Dunking at the rim.
-- He starts ~20 studs out and the ball is at the rim in about a second, so the bot has to run to the rim at Passing.
Farm.FARM_LOB = { Passing = true, CatchingLob = true, AwaitingPass = true }
Farm.LOB_NEAR = 7 -- [uncalibrated] flat studs: a lob this close to us is contested with a jump right away
Farm.LOB_JUMP_REACH = 8 -- [uncalibrated] flat studs from the ball at which we jump for it
Farm.LOB_MIN_HEIGHT, Farm.LOB_MAX_HEIGHT = 1.5, 12 -- [uncalibrated] ball height above our root that we can jump into

function Farm.farmJump()
    pressBlockJump() -- the game's own Space sequence: Shoot{UseSpace} + Jump, key-up after a short hold
    Tel.count("farm.jump")
end

-- Jumps at shooters and dunkers. Shots are timed to the release, dunks and layups are met at the rim, and a missed
-- takeoff (still on the ground a moment later) is retried once.
-- [live] While sprinting without the ball the character's Action is "Moving", so the old test (Action == "") was false
-- on every run to the rim and the bot never jumped for a lob or a block it had to run for. Only real busy actions block it.
Farm.JUMP_BUSY = { Blocking = true, Shooting = true, Dunking = true, PickingUp = true, Gathering = true, ContactPlant = true,
    Pushing = true, Stunned = true, Fouled = true, Ankles = true, Passing = true }
function Farm.canJumpNow(char)
    return char:GetAttribute("InAir") ~= true and not Farm.JUMP_BUSY[char:GetAttribute("Action") or ""]
end

function Farm.farmBlock(opponent)
    local root, mine = Ctx.hrp, Ctx.char
    if not opponent or not root or not mine then
        return false
    end
    local model, theirs = opponent.model, opponent.hrp
    local action = model:GetAttribute("Action")
    local shot = type(action) == "string" and Farm.FARM_SHOTS[action]
    local finish = type(action) == "string" and Farm.FARM_FINISH[action]
    local state = Farm.blockState[model] or {}
    Farm.blockState[model] = state
    -- ReleasedShot flips to false the moment a shot starts, usually one frame BEFORE his Action says Shooting, so it has to
    -- be watched all the time, not only once the shot has been noticed (the Auto Block tab does the same).
    do
        local nowReleased = model:GetAttribute("ReleasedShot")
        if nowReleased == false and state.prevReleased ~= false then
            state.flipAt = os.clock()
        end
        state.prevReleased = nowReleased
    end
    -- Lobs: run under the ball, not at the catcher, and jump into it so he cannot catch it clean.
    if type(action) == "string" and Farm.FARM_LOB[action] then
        local ball = Farm.farmBall()
        local rim = goalPosition(model)
        -- run to the rim (where the lob ends), not after the ball which is already faster than we are
        local target = rim or (ball and ball.Position) or theirs.Position
        local aim = flat(target - root.Position)
        if aim.Magnitude > 1.5 then
            Farm.vector = Farm.farmCameraVector(aim, 1)
            Farm.farmSprint(true)
        end
        local now = os.clock()
        local grounded = Farm.canJumpNow(mine)
        if state.lobAt == nil or now - state.lobAt > 3 then
            state.lobAt = now
            warn(("[JHub Farm] lob (%s): ball %.1f studs from me, he is %.1f from me, rim %.1f from me"):format(
                tostring(action), ball and flatDistance(ball.Position, root.Position) or -1,
                flatDistance(theirs.Position, root.Position), rim and flatDistance(rim, root.Position) or -1))
        end
        if grounded and now - Farm.lastBlock > 0.7 then
            local ballUp = ball and (ball.Position.Y - root.Position.Y) or 0
            local reach
            -- [live] A lob that starts next to us (a steal into a self lob, or a pass off a screen) leaves the ball just
            -- above his head within arm's reach and he is already closer to the rim than we are, so running to the rim
            -- is a race we lose. Jump at the ball while it is still next to us to knock it down or take the catch away.
            if ball and ballUp >= 0.5 and ballUp <= Farm.LOB_MAX_HEIGHT and flatDistance(ball.Position, root.Position) <= Farm.LOB_NEAR then
                Farm.lastBlock = now
                Farm.farmJump()
                Tel.count("farm.lob_jump")
                state.start, state.done, state.retried = nil, false, false
                return true
            end
            if rim then
                -- jump once we are under the rim and the ball (or he) is coming down onto it
                reach = aim.Magnitude <= Farm.LOB_JUMP_REACH
                    and (ball == nil or (ballUp >= Farm.LOB_MIN_HEIGHT and flatDistance(ball.Position, rim) <= 14))
            else
                reach = ball and aim.Magnitude <= Farm.LOB_JUMP_REACH and ballUp >= Farm.LOB_MIN_HEIGHT and ballUp <= Farm.LOB_MAX_HEIGHT
            end
            if reach then
                Farm.lastBlock = now
                Farm.farmJump()
                Tel.count("farm.lob_jump")
            end
        end
        state.start, state.done, state.retried = nil, false, false
        return true
    end
    if not shot and not finish then
        state.start, state.done, state.retried = nil, false, false
        return false
    end
    local now = os.clock()
    if state.start == nil then
        state.start, state.done, state.retried = now, false, false
        state.sawFalse, state.warned = false, false
        local speed = model:GetAttribute("ShotSpeed")
        local release = BLK.RELEASE / ((type(speed) == "number" and speed > 0.05) and speed or 1)
        state.wait = finish and 0.03 or (math.max(0, release - BLK.PEAK - blockPing(now) - BLK.LEAD) + 0.03)
    end
    local elapsed = now - state.start
    local distance = flatDistance(root.Position, theirs.Position)
    local reach = finish and 10 or 14
    -- Release tracking, as in the Auto Block tab: ReleasedShot false = still in the shooter's hands, true = the ball has left.
    local released = model:GetAttribute("ReleasedShot")
    if released == false then
        state.sawFalse = true
    end
    if released == true and state.sawFalse and not finish then
        state.done = true -- the ball is gone, a jump now blocks nothing
    end
    -- Chase: close the gap toward the shooter or the rim while they are going up.
    if distance > 2.5 and distance < 24 then
        local target = finish and (goalPosition(model) or theirs.Position) or theirs.Position
        Farm.vector = Farm.farmCameraVector(flat(target - root.Position), 1)
        Farm.farmSprint(true)
    end
    local grounded = Farm.canJumpNow(mine)
    local cooled = now - Farm.lastBlock > 0.9
    -- [fix] A real shot is confirmed by the shooter's meter or a fresh ReleasedShot flip, exactly like the Auto Block tab.
    -- The old test waited for the shooter to be in the air or for 0.3s, which on a standing shot meant the jump left
    -- after the ball was already gone (the jump peaks about 0.35s after it starts, the release is at about 0.48s).
    local confirmed = finish ~= nil and finish ~= false
        or blockMetered(model)
        or (released == false and state.flipAt ~= nil and state.flipAt >= state.start - BLK.FLIP_WINDOW)
        or model:GetAttribute("InAir") == true
        or elapsed >= math.max(state.wait, 0.12) -- [fix] was 0.3s: the jump left after the ball (release is at about 0.48s)
    local heightOk = math.abs(theirs.Position.Y - root.Position.Y) <= BLK.MAX_HEIGHT
    if not state.done and grounded and cooled and distance <= reach and elapsed >= state.wait and heightOk and confirmed then
        state.done = true
        Farm.lastBlock = now
        if Farm.gHeld and not Flags.AutoGuard then
            setGuardKey(false) -- let go of the guard stance before the jump so the server does not eat it
            Farm.gHeld = false
        end
        Farm.farmJump()
        Tel.count("farm.block_jump")
        task.delay(0.14, function() -- retry once if we did not leave the ground
            if Alive and Flags.AutoFarm and not state.retried and Ctx.char
                and Ctx.char:GetAttribute("InAir") ~= true and model.Parent then
                local still = model:GetAttribute("Action")
                if still == action then
                    state.retried = true
                    Farm.farmJump()
                end
            end
        end)
    elseif not state.done and not state.warned and elapsed >= state.wait + 0.2 then
        state.warned = true
        Tel.count("farm.block_skipped")
        warn(("[JHub Farm] block skipped (%s): dist %.1f/%d, height ok %s, grounded %s (my action %s, inAir %s), cooled %s, confirmed %s, released %s")
            :format(tostring(action), distance, reach, tostring(heightOk), tostring(grounded), tostring(mine:GetAttribute("Action")),
                tostring(mine:GetAttribute("InAir")), tostring(cooled), tostring(confirmed), tostring(released)))
    end
    return true
end

Farm.BEATEN_BY = 1.5 -- [uncalibrated] studs closer to the hoop than us before we count as beaten
Farm.RECOVER_SPRINT = true -- sprint only while recovering from being beaten, never while guarding in front

function Farm.farmGuard(opponent)
    Farm.farmStopSprint() -- never sprint while guarding
    local root = Ctx.hrp
    if not root or not opponent then
        return
    end
    Farm.gWanted = true -- Hold G: the stance is held for as long as this runs (see Farm.applyG)
    local hoop = chooseAttackedHoop({ model = opponent.model, hrp = opponent.hrp })
    if not hoop then
        return
    end
    local velocity = opponent.hrp.AssemblyLinearVelocity * FLAT
    local predicted = opponent.hrp.Position + velocity * 0.25
    local toHoop = (hoop - predicted) * FLAT
    local stand = predicted

    -- Beaten: he is past us (closer to the hoop than we are). The spot between him and the hoop is now on the far side
    -- of his body, so walking at it pushed straight into him and the bot stood stuck behind. Take the shoulder instead:
    -- run along our own side of him to a point on the hoop side, cutting the angle, and flip sides if we stop moving.
    local ourD, hisD = flatDistance(root.Position, hoop), flatDistance(opponent.hrp.Position, hoop)
    if ourD > hisD + Farm.BEATEN_BY and toHoop.Magnitude > 1 then
        local nowG = os.clock()
        local axis = toHoop.Unit
        local lateral = Vector3.new(axis.Z, 0, -axis.X)
        local mine = flat(root.Position - opponent.hrp.Position)
        if not Farm.beatenSide or nowG > (Farm.beatenUntil or 0) then
            Farm.beatenSide = mine:Dot(lateral) >= 0 and 1 or -1
            Farm.beatenUntil = nowG + 1.2
        end
        -- stuck check: barely moved in the last 0.5s while we are trying to get around
        local last = Farm.beatenLast
        if not last or nowG - last.t > 0.5 then
            if last and flat(root.Position - last.pos).Magnitude < 0.6 then
                Farm.beatenSide = -Farm.beatenSide
                Farm.beatenUntil = nowG + 1.2
                Tel.count("farm.guard_unstick")
            end
            Farm.beatenLast = { pos = root.Position, t = nowG }
        end
        local target = predicted + axis * 3.5 + lateral * Farm.beatenSide * 3.2 + velocity * 0.4
        local delta = (target - root.Position) * FLAT
        if delta.Magnitude > 0.3 then
            Farm.vector = Farm.farmCameraVector(delta, 1)
            if Farm.RECOVER_SPRINT and ourD - hisD > Farm.BEATEN_BY + 1.5 then
                Farm.farmSprint(true) -- recovering, not guarding: walking cannot catch a ball handler
            end
        end
        return
    end
    Farm.beatenSide, Farm.beatenLast = nil, nil

    -- anti ankle breaker: while he is working a dribble move, give extra room instead of lunging at the fake
    local theirs = opponent.model and opponent.model:GetAttribute("Action")
    local giveRoom = (theirs == "Dribbling" or theirs == "Ankles" or theirs == "BlowingBy") and 2.5 or 0
    if toHoop.Magnitude > 0.5 then
        local scout = Flags.FarmScout and Farm.Rec and opponent.model and Farm.Rec.guardAdjust(opponent.model.Name) or 0
        stand = predicted + toHoop.Unit * math.min((Flags.GuardDist or 4) + giveRoom + scout, toHoop.Magnitude)
    end
    local delta = (stand - root.Position) * FLAT
    if delta.Magnitude > 0.4 then
        local strength = math.clamp(delta.Magnitude, 0.3, 1)
        if giveRoom > 0 and delta.Magnitude < 3 then
            strength = math.min(strength, 0.5) -- no overcommitting on the fake
        end
        Farm.vector = Farm.farmCameraVector(delta, strength)
    elseif velocity.Magnitude < 1.2 and giveRoom == 0 and toHoop.Magnitude > 0.5 then
        Farm.guardIdle(root, stand, toHoop)
    end
end

-- He is standing still and we are on our spot: shuffle a little instead of freezing, like a person would. Short side
-- steps (sometimes a half step in or out) at irregular intervals, never more than ~1.8 studs from the spot.
Farm.IDLE_RADIUS = 1.8

function Farm.guardIdle(root, stand, toHoop)
    local now = os.clock()
    local state = Farm.idle
    if not state then
        state = { nextAt = now + 0.4 + math.random() * 0.8, burstUntil = 0, dir = nil, side = math.random() < 0.5 and 1 or -1 }
        Farm.idle = state
    end
    local axis = toHoop.Unit
    local lateral = Vector3.new(axis.Z, 0, -axis.X)
    if now < state.burstUntil and state.dir then
        Farm.vector = Farm.farmCameraVector(state.dir, 0.5)
        return
    end
    if now < state.nextAt then
        return
    end
    local offset = flat(root.Position - stand)
    local pick
    if offset.Magnitude > Farm.IDLE_RADIUS then
        pick = -offset.Unit -- drifted: step back toward the spot
    elseif math.random() < 0.25 then
        pick = axis * ((math.random() < 0.5) and 1 or -1) -- a half step in or out
    else
        state.side = -state.side -- alternate sides most of the time
        if math.random() < 0.3 then
            state.side = -state.side
        end
        pick = lateral * state.side
    end
    state.dir = pick
    state.burstUntil = now + 0.12 + math.random() * 0.16
    state.nextAt = state.burstUntil + 0.6 + math.random() * 1.4
end

-- Rebound: chase the loose ball to where it comes down, box out by staying between the opponent and the ball, jump for it.
function Farm.farmRebound(opponent, ball)
    local root = Ctx.hrp
    if not root or not ball then
        return
    end
    local velocity = ball.AssemblyLinearVelocity
    local landing = ball.Position + Vector3.new(velocity.X, 0, velocity.Z) * 0.35
    local target = landing
    if opponent then
        local away = flat(landing - opponent.hrp.Position)
        if away.Magnitude > 0.5 then
            target = landing - away.Unit * 1.2 -- sit on the hoop side of them
        end
    end
    local delta = flat(target - root.Position)
    local distance = delta.Magnitude
    if distance > 1.2 then
        Farm.vector = Farm.farmCameraVector(delta, 1)
        Farm.farmSprint(distance > 5)
    end
    local height = ball.Position.Y - root.Position.Y
    local grounded = Ctx.char and Ctx.char:GetAttribute("InAir") ~= true
    if distance < 7 and height > 1.5 and height < 11 and grounded and os.clock() - Farm.lastRebound > 0.7 then
        Farm.lastRebound = os.clock()
        Farm.farmJump()
    end
end

-- Queue / leave loop -------------------------------------------------------------------------------
function Farm.farmInvoke(serviceName, remoteName, ...)
    local service = remoteService(serviceName)
    local target = service and service:FindFirstChild(remoteName)
    if target and target:IsA("RemoteFunction") then
        return pcall(target.InvokeServer, target, ...)
    end
    return false
end

-- Lobby hotkey: press P then Y (within 1.5s) to go straight to the Blacktop lobby (matchmaking). The same jump runs once
-- when JHub loads while you are in the Plaza / main menu ("Auto Lobby On Join" toggle in the Farm tab).
-- [live] InterfaceService.JoinPlace("BlacktopMatchmaking") is the exact call the Plaza's Blacktop prompt makes (RemoteFunction
-- verified to exist); InterfaceService.LeaveRec leaves a finished Blacktop game into the lobby. NOT verified: LeaveRec in the
-- middle of a game. The lobby is its own place (78438427735992), so the last fallback is a plain teleport there.
Farm.Lobby = (function()
    local M = { lastP = -math.huge, busy = false, PLACE = 78438427735992 }

    local function inLobby()
        return workspace:GetAttribute("Gamemode") == "BlacktopMatchmaking" or game.PlaceId == M.PLACE
    end

    local function wait(sec)
        local t = os.clock()
        while Alive and os.clock() - t < sec and not inLobby() do
            task.wait(0.25)
        end
        return inLobby()
    end

    function M.go(quiet)
        if M.busy then
            return
        end
        if inLobby() then
            if not quiet then
                notify("Lobby", "Already in the Blacktop lobby.", "Info", 3)
            end
            return
        end
        M.busy = true
        notify("Lobby", "Going to the Blacktop lobby...", "Info", 3)
        task.spawn(function()
            local inMatch = workspace:GetAttribute("Gamemode") == "Blacktop"
            -- [live] a server teleport takes well over 5 seconds, so a call the game ACCEPTED (it returns true) gets 30s
            -- before anything else is tried; a refused or missing call falls through at once.
            local function attempt(name, ...)
                local okCall, okInvoke, accepted = pcall(Farm.farmInvoke, "InterfaceService", name, ...)
                if name == "LeaveRec" then
                    return okCall and okInvoke == true and accepted ~= false -- its result when it works is not known
                end
                return okCall and okInvoke == true and accepted ~= false and accepted ~= nil
            end
            local first = inMatch and attempt("LeaveRec") or (not inMatch and attempt("JoinPlace", "BlacktopMatchmaking"))
            if not wait(first and 30 or 1) and Alive then
                -- the other route (LeaveRec outside a match is ignored, JoinPlace inside one is not meant for it)
                local second
                if inMatch then
                    second = attempt("JoinPlace", "BlacktopMatchmaking")
                else
                    second = attempt("LeaveRec")
                end
                if not wait(second and 30 or 3) and Alive then
                    warn("[JHub] Lobby: the game did not move us, teleporting to the lobby place directly")
                    pcall(function()
                        game:GetService("TeleportService"):Teleport(M.PLACE, LocalPlayer)
                    end)
                end
            end
            task.wait(6)
            M.busy = false
        end)
    end

    Root:Give(UserInputService.InputBegan:Connect(function(input)
        if UserInputService:GetFocusedTextBox() then
            return
        end
        if input.KeyCode == Enum.KeyCode.P then
            M.lastP = os.clock()
        elseif input.KeyCode == Enum.KeyCode.Y and os.clock() - M.lastP < 1.5 then
            M.lastP = -math.huge
            M.go()
        end
    end))

    -- On join: only from the Plaza / main menu, never from a match, the lobby or another mode, so an auto-exec re-run
    -- after the queue teleports you into a game does not pull you back out.
    task.spawn(function()
        local t = os.clock()
        while Alive and workspace:GetAttribute("Gamemode") == nil and os.clock() - t < 10 do
            task.wait(0.25)
        end
        task.wait(1.5)
        local mode = workspace:GetAttribute("Gamemode")
        if Alive and Flags.FarmAutoLobby and (mode == "Plaza" or mode == "MainMenu" or mode == "Main") then
            M.go(true)
        end
    end)
    return M
end)()

function Farm.farmFinishGame()
    if Farm.gameCounted then
        return
    end
    Farm.gameCounted = true
    local session = Farm.session
    local mine, theirs = session.points - (Farm.gamePoints or 0), session.oppPoints - (Farm.gameOpp or 0)
    Farm.bump("games")
    local result = "unknown"
    if mine > 0 or theirs > 0 then
        if mine > theirs then
            Farm.bump("wins")
            result = "WIN"
        else
            Farm.bump("losses")
            result = "LOSS"
        end
    end
    Farm.farmPost(("Match %s"):format(result), ("Score (detected) %d - %d\n%s"):format(mine, theirs, Farm.farmStatsText(Farm.session)),
        result == "WIN" and 5763719 or (result == "LOSS" and 15548997 or 9807270))
    if Farm.session.games % 10 == 0 then
        Farm.farmSessionSummary()
    end
    Farm.farmSave()
end

-- Finds the visible "READY" label of the Queue UI and clicks its button with a real mouse click at its position.
function Farm.farmClickReady()
    if not (Alive and Flags.AutoFarm and Flags.FarmQueue) or workspace:GetAttribute("Gamemode") ~= "BlacktopMatchmaking" then
        return
    end
    local gui = LocalPlayer:FindFirstChild("PlayerGui")
    if not gui then
        return
    end
    local target
    for _, d in ipairs(gui:GetDescendants()) do
        if d:IsA("TextLabel") and d.Text == "READY" and d.Visible and d:GetFullName():find("Queue") then
            target = d
            break
        end
    end
    if not target then
        return -- already UNREADY / LOCKED, or the UI is not up
    end
    local ok, err = pcall(function()
        local vim = game:GetService("VirtualInputManager")
        local inset = game:GetService("GuiService"):GetGuiInset()
        local holder = target:FindFirstAncestorWhichIsA("GuiButton") or target.Parent or target
        local pos = holder.AbsolutePosition + holder.AbsoluteSize / 2 + inset
        vim:SendMouseMoveEvent(pos.X, pos.Y, game)
        task.wait(0.05)
        vim:SendMouseButtonEvent(pos.X, pos.Y, 0, true, game, 0)
        task.wait(0.06)
        vim:SendMouseButtonEvent(pos.X, pos.Y, 0, false, game, 0)
    end)
    warn("[JHub Farm] pressed READY button: " .. tostring(ok) .. " " .. tostring(err or ""))
end

function Farm.farmFlow()
    local mode = workspace:GetAttribute("Gamemode")
    local now = os.clock()
    if mode == "Blacktop" then
        local over = workspace:GetAttribute("GameOver") == true
        -- [live] GameOver can already be true during warm-up, so only leave after a live game was seen
        -- (or after 90s of continuous GameOver, for joining a game that is already finished).
        if not over then
            if Farm.over ~= false then
                Farm.over = false
                Farm.sawPlaying = true
                Farm.overSince = nil
                Farm.man = nil -- 2v2: pick the man to guard again for this game
                Farm.gameCounted = false
                Farm.gamePoints, Farm.gameOpp = Farm.session.points, Farm.session.oppPoints
            end
            if now - (Farm.lastWatch or -math.huge) > 3 then
                Farm.lastWatch = now
                Farm.watchHoops()
            end
            return true
        end
        Farm.over = true
        Farm.overSince = Farm.overSince or now
        if Farm.sawPlaying then
            Farm.farmFinishGame()
        end
        if Flags.FarmQueue and (Farm.sawPlaying or now - Farm.overSince > 90) and now - Farm.leaving > 8 then
            Farm.leaving = now
            task.delay(1.5 + math.random() * 2.5, function()
                if Alive and Flags.AutoFarm and Flags.FarmQueue and workspace:GetAttribute("GameOver") == true then
                    Farm.farmInvoke("InterfaceService", "LeaveRec")
                end
            end)
        end
        return false
    elseif mode == "BlacktopMatchmaking" then
        if Flags.FarmQueue and now - Farm.queued > 12 then
            Farm.queued = now
            task.delay(2 + math.random() * 3, function()
                if Alive and Flags.AutoFarm and Flags.FarmQueue and workspace:GetAttribute("Gamemode") == "BlacktopMatchmaking" then
                    -- the game's own button calls QueueService:Ready(true) and gets (success, message) back
                    if Flags.Farm2v2 then
                        Farm.select2v2()
                        task.wait(0.4)
                    end
                    local ok, success, message = Farm.farmInvoke("QueueService", "Ready", true)
                    if ok and success == false then
                        warn("[JHub Farm] Ready was refused: " .. tostring(message))
                    end
                    -- The remote alone does not move the on-screen button (the game keeps its own state), and may not
                    -- queue us. If the Queue UI still says READY a moment later, press the real button.
                    task.delay(1.5, Farm.farmClickReady)
                end
            end)
        end
        return false
    end
    return mode == "Park" -- Park 1v1 pad joining is not implemented; play if you are already in a game
end

-- Main step ----------------------------------------------------------------------------------------
function Farm.stepFarm()
    Farm.vector = nil
    if not Flags.AutoFarm then
        return
    end
    if not Ctx.char or not Ctx.hrp then
        -- [live] In the Blacktop lobby ("BlacktopMatchmaking") the player has no character in workspace.Characters, so the
        -- old early return meant farmFlow never ran there and the bot left the game but never pressed READY.
        Farm.latch, Farm.chosen, Farm.holdSince, Farm.pending = false, nil, nil, nil
        if workspace:GetAttribute("Gamemode") == "BlacktopMatchmaking" then
            Farm.farmFlow()
        end
        return
    end
    if not Farm.farmFlow() then
        Farm.latch, Farm.chosen, Farm.holdSince, Farm.pending = false, nil, nil, nil
        return
    end
    local opponent = Farm.farmOpponent()
    local ball = Farm.farmBall()
    local oppHasBall = opponent ~= nil and holdsBall(opponent.model)
    local loose = ball ~= nil and not Ctx.hasBall and not oppHasBall
    local man2v2, teamHasBall
    if Flags.Farm2v2 then
        -- With two players on each side the ball can be held by the other opponent or by a teammate, which is not "loose".
        local anyEnemyHas, anyoneHas = false, Ctx.hasBall == true
        for _, other in ipairs(Ctx.getOthers()) do
            if holdsBall(other.model) then
                anyoneHas = true
                if Ctx.char and sameTeam(Ctx.char, other.model) then
                    teamHasBall = true
                else
                    anyEnemyHas = true
                end
            end
        end
        oppHasBall = anyEnemyHas
        loose = ball ~= nil and not anyoneHas
        man2v2 = Farm.farmMan()
    end

    -- stat events from state changes
    if Ctx.hasBall and not Farm.hadBall then
        if Farm.oppHadBall then
            Farm.bump("steals")
        elseif Farm.wasLoose then
            Farm.bump("rebounds")
        end
        Farm.chosen, Farm.holdSince, Farm.latch = nil, nil, false
    end
    if not Ctx.hasBall then
        Farm.latch, Farm.holdSince = false, nil
    end
    Farm.hadBall, Farm.oppHadBall, Farm.wasLoose = Ctx.hasBall, oppHasBall, loose

    -- Latch watchdog. The latch means "a shot is going up, stand still". If the shot input never turned into a shot
    -- Action while we still hold the ball, the old code stood still forever with the ball in hand.
    if Farm.latch and Ctx.hasBall then
        local since = os.clock() - Farm.latchAt
        if Farm.SHOT_ACTIONS[Ctx.action] then
            Farm.shotSeen = true
        end
        if not Farm.shotSeen and since > Farm.LATCH_START_TIMEOUT then
            Tel.count("farm.latch_timeout")
            fire("InputService", "Shoot", { Shoot = false })
            Farm.latch = false
            Farm.retries += 1
            if Farm.retries <= 3 and Farm.canShoot() and Farm.pending then
                task.defer(Farm.farmShoot, Farm.pending.kind, flatDistance(Ctx.hrp.Position, Farm.myHoopPosition() or Ctx.hrp.Position), true)
            end
        elseif since > Farm.LATCH_MAX then
            Tel.count("farm.latch_max")
            Farm.latch = false
        end
        -- Release stalled in the Shooting action with the ball still in hand: resend the key-up.
        if Ctx.action == "Shooting" and since > 1.3 and os.clock() - (Farm.lastForce or 0) > 0.4 then
            Farm.lastForce = os.clock()
            Tel.count("farm.release_forced")
            fire("InputService", "Shoot", { Shoot = false })
        end
    end

    Farm.lagTick()
    Farm.disguiseTick()
    if Ctx.hasBall then
        Farm.farmOffense(opponent)
        return
    end
    if Flags.Farm2v2 and man2v2 then
        -- Man-to-man: contest any shooter in reach, rebound a loose ball, otherwise stay goal-side of our own man.
        if Flags.FarmBlock then
            for _, other in ipairs(Ctx.getOthers()) do
                if not (Ctx.char and sameTeam(Ctx.char, other.model)) and Farm.farmBlock(other) then
                    return
                end
            end
        end
        if loose and Flags.FarmRebound then
            Farm.farmRebound(man2v2, ball)
        elseif holdsBall(man2v2.model) and Flags.FarmGuard then
            Farm.farmGuard(man2v2) -- he has the ball: guard him, and G goes down (Hold G For Me)
        elseif not teamHasBall and Flags.FarmGuard then
            -- He does not have the ball: stay goal-side of him but keep G up. farmGuard asks for G every time it runs,
            -- so the request is cancelled right after.
            Farm.farmGuard(man2v2)
            Farm.gWanted = false
        else
            local toMan = flat(man2v2.hrp.Position - Ctx.hrp.Position)
            if toMan.Magnitude > 6 then
                Farm.vector = Farm.farmCameraVector(toMan, 0.6)
            end
        end
        return
    end
    local blocking = false
    if Flags.FarmBlock then
        blocking = Farm.farmBlock(opponent)
    end
    if blocking then
        return
    end
    if loose and Flags.FarmRebound then
        Farm.farmRebound(opponent, ball)
    elseif oppHasBall and Flags.FarmGuard then
        Farm.farmGuard(opponent)
    elseif opponent then
        local toOpp = flat(opponent.hrp.Position - Ctx.hrp.Position)
        if toOpp.Magnitude > 6 then
            Farm.vector = Farm.farmCameraVector(toOpp, 0.6)
        end
    end
end

-- Hold G: presses and holds G while the bot is guarding the ball handler, lets go otherwise (and when Auto Farm is off).
-- The game drops the stance after a shot, block or jump while our key state still says down, so if the game says we are
-- not holding G for a moment we release for one frame and press again.
function Farm.applyG()
    local want = Flags.AutoFarm == true and Flags.FarmHoldG == true and Farm.gWanted == true and Ctx.char ~= nil
    Farm.gWanted = false
    local now = os.clock()
    if want then
        Farm.gHeld = true
        if Guard.keyDown and Ctx.char:GetAttribute("HoldingG") ~= true then
            Farm.gNotHeld = Farm.gNotHeld or now
            if now - Farm.gNotHeld > 0.25 then
                Farm.gNotHeld = nil
                setGuardKey(false)
                Farm.gRepress = now
                return
            end
        else
            Farm.gNotHeld = nil
        end
        if Farm.gRepress and now - Farm.gRepress < 0.05 then
            return -- one frame up so the game sees a new key press
        end
        setGuardKey(true)
    elseif Farm.gHeld then
        Farm.gHeld, Farm.gNotHeld, Farm.gRepress = false, nil, nil
        if not Flags.AutoGuard then
            setGuardKey(false)
        end
    end
end

do
    local stepInner = Farm.stepFarm
    function Farm.stepFarm()
        if Flags.AutoFarm then
            Farm.botAt = os.clock()
        end
        local ok, err = pcall(stepInner)
        Farm.applyG() -- always runs, so an error in the bot can never leave G stuck down
        if not ok then
            error(err, 0)
        end
    end
end

-- Block counting: opponent shot ended with our Blocking action around the same time. [estimated]
function Farm.farmWatchBlocks()
    local char = Ctx.char
    if not char or Farm.blockHook == char then
        return
    end
    Farm.blockHook = char
    Root:Give(char:GetAttributeChangedSignal("Action"):Connect(function()
        if char:GetAttribute("Action") == "Blocking" and Flags.AutoFarm then
            Farm.pendingBlock = os.clock()
        end
    end))
end

function Farm.farmWatcher()
    Farm.farmWatchBlocks()
    local when = Farm.pendingBlock
    if when and os.clock() - when > 0.6 then
        Farm.pendingBlock = nil
        local opponent = Farm.farmOpponent()
        if opponent and opponent.model:GetAttribute("ReleasedShot") == false then
            Farm.bump("blocks")
        end
    end
end

Farm.UI_FILE = "JHub/ui.json"

function Farm.uiPrefRead()
    if type(isfile) ~= "function" or type(readfile) ~= "function" then
        return false
    end
    local ok, data = pcall(function()
        if isfile(Farm.UI_FILE) then
            return game:GetService("HttpService"):JSONDecode(readfile(Farm.UI_FILE))
        end
    end)
    return ok and type(data) == "table" and data.hideOnLoad == true
end

function Farm.uiPrefWrite(value)
    if type(writefile) ~= "function" then
        return
    end
    pcall(function()
        if type(makefolder) == "function" and type(isfolder) == "function" and not isfolder(Farm.FARM_DIR) then
            makefolder(Farm.FARM_DIR)
        end
        writefile(Farm.UI_FILE, game:GetService("HttpService"):JSONEncode({ hideOnLoad = value == true }))
    end)
end

-- Closes the menu once its opening animation has finished. Needs a keyboard, otherwise there is no way to reopen it.
function Farm.hideUIOnLoad(window)
    if not Farm.uiPrefRead() or not UserInputService.KeyboardEnabled then
        return
    end
    task.spawn(function()
        local state = window and window.__lib and window.__lib.Window and window.__lib.Window.State
        for _ = 1, 60 do
            if not Alive or not state then
                return
            end
            task.wait(0.25)
            if state.Visible == true and (tonumber(state.VisibilityAnim) or 1) >= 0.99 then
                state.Visible = false
                return
            end
        end
    end)
end

function Farm.start()
    local saved = Farm.farmLoad()
    if saved then
        if type(saved.life) == "table" then
            for key, value in pairs(Farm.newStats()) do
                Farm.life[key] = tonumber(saved.life[key]) or value
            end
        end
        if type(saved.kinds) == "table" then
            for name, entry in pairs(saved.kinds) do
                if type(entry) == "table" then
                    Farm.kinds[name] = { att = tonumber(entry.att) or 0, made = tonumber(entry.made) or 0 }
                end
            end
        end
        if type(saved.style) == "string" then
            Flags.FarmStyle = saved.style
        end
    end
    local feedback = remote("InterfaceService", "ShowFeedback")
    if feedback then
        Root:Give(feedback.OnClientEvent:Connect(function(owner, _, grade)
            if Flags.AutoFarm and owner == Ctx.char and tonumber(grade) == 5 then
                Farm.bump("perfects")
            end
        end))
    end
    -- Re-run JHub after every teleport (matchmaking, then the match, then matchmaking again)
    local autoSaved = Farm.autoExecRead()
    if autoSaved and autoSaved.setting == true and Farm.autoExecToggle then
        task.defer(function()
            if Alive then
                Farm.autoExecToggle:SetValue(true)
            end
        end)
    end
    -- Until the saved Auto Farm state has been restored (4s below) count it as on, so the autoexec file is not
    -- rewritten as "disabled" and the next teleport does not skip re-running the script.
    Farm.resuming = saved ~= nil and saved.enabled == true
    Farm.autoExecApply(false)
    Root:Give(Farm.farmSave)
    Farm.watchHoops()
    if saved and saved.enabled == true and Farm.toggle then
        task.delay(4, function()
            if Alive then
                Farm.toggle:SetValue(true)
            end
            -- The lobby place has no Shoot/Jump remotes and no PlayerModule controls yet, so the toggle's Needs check
            -- refuses and Auto Farm silently stays off there (the farm flow never ran, so it never pressed Ready).
            -- Nothing in the lobby needs those, so switch the flag on directly (the match re-run turns the real toggle on).
            if Alive and not Flags.AutoFarm and workspace:GetAttribute("Gamemode") == "BlacktopMatchmaking" then
                Flags.AutoFarm = true
                Farm.autoExecApply(false)
                warn("[JHub Farm] Auto Farm resumed in the lobby")
            end
            -- Loaded early (the Blacktop showcase), the game's remotes and the player module may not be there yet and the
            -- toggle refuses. Keep trying for a minute instead of staying off for the whole match.
            for _ = 1, 30 do
                if not Alive or Flags.AutoFarm then
                    break
                end
                task.wait(2)
                if Alive and not Flags.AutoFarm and Farm.toggle and remote("InputService", "Shoot") and remote("InputService", "Jump") then
                    pcall(function()
                        Farm.toggle:SetValue(true)
                    end)
                end
            end
            Farm.resuming = false
            Farm.farmSave()
            Farm.autoExecApply(false)
        end)
    end
end

beatSteps[#beatSteps + 1] = guarded("Auto Farm", "AutoFarm", Farm.stepFarm)
beatSteps[#beatSteps + 1] = guarded("Auto Farm Stats", nil, Farm.farmWatcher)

local Window = Library:CreateWindow({
    Title = "JHUB",
    GameName = "Practical Basketball",
    Version = VERSION,
    Home = {
        QuickLabel = "Quick Toggles",
        QuickStart = {
            { Title = "Perfect Timing", Flag = "PerfectTiming", Icon = "zap" },
            { Title = "Auto Shoot", Flag = "AutoShoot", Icon = "target" },
            { Title = "Auto Block", Flag = "AutoBlock", Icon = "shield" },
            { Title = "Player ESP", Flag = "ESP", Icon = "eye" },
        },
    },
})

local function toggle(box, flag, text, description, options)
    options = options or {}
    local object
    object = box:AddToggle(flag, {
        Text = text,
        Description = description,
        Default = Defaults[flag] == true,
        Bindable = options.Keybind ~= nil,
        Callback = function(value)
            if value and options.Needs then
                local ok, why = options.Needs()
                if not ok then
                    Flags[flag] = false
                    notify(text, why, "Warning", 6)
                    task.defer(function()
                        object:SetValue(false, true)
                    end)
                    return
                end
            end
            Flags[flag] = value
            if options.OnChange then
                options.OnChange(value)
            end
        end,
    })
    if options.Keybind then
        object:AddKeybind({ Mode = options.Keybind })
    end
    UIObjects[flag] = object
    return object
end

local function slider(box, flag, text, description, minimum, maximum, suffix)
    return box:AddSlider(flag, {
        Text = text, Description = description, Default = Defaults[flag], Min = minimum, Max = maximum,
        Decimals = 0, Suffix = suffix or "",
        Callback = function(value)
            if type(value) == "number" and value == value then
                Flags[flag] = value -- [fix] a nil here wiped GuardDist and Auto Guard crashed on math.min(nil)
            end
        end,
    })
end

-- Keybind wipe [mine]: one confirmation dialog shared by every red reset button.
local DribbleBindIds = {} -- bind ids of every dribble move button and the combo play button

local function wipeKeybinds()
    Combo.stop()
    local count = Window:WipeBinds()
    Override.refresh()
    notify("Keybinds", ("Wiped %d keybind%s."):format(count, count == 1 and "" or "s"), "Success", 5)
end

local function askWipeKeybinds()
    local count = Window:CountBinds()
    Window:Confirm({
        Title = "WARNING",
        Danger = true,
        YesLabel = "WIPE KEYBINDS",
        NoLabel = "Cancel",
        Lines = {
            "This removes EVERY keybind in JHub (" .. count .. " set right now):",
            "dribble moves, the combo, and every toggle.",
            "If you use an auto-load config it is re-saved without them.",
            "This cannot be undone.",
        },
        Yes = wipeKeybinds,
    })
end

