Farm.SPIN_SIDE = { ["Spin Hesi L to R"] = "L", ["Spin Hesi R to L"] = "R" } -- the hand each spin starts from
-- Dribble moves and combo creator. Every move is a button with its own keybind (click the key box next to it).
-- A bound key does only that move: see the Dribble keybind override section for how the game's own dribble is blocked.
do
    local tab = offense:AddTab("Dribble Combos")
    local safety = tab:AddGroupbox("Keybind Safety")
    safety:AddLabel("A key bound here replaces the game's own dribble on that key. Panic button wipes every keybind in JHub.")
    safety:AddDangerButton({ Text = "EMERGENCY: RESET ALL KEYBINDS", Func = askWipeKeybinds })

    local groups = {}
    for _, move in ipairs(Moves) do
        if not groups[move.group] then
            groups[move.group] = tab:AddGroupbox(move.group)
        end
        local bindId = "Move_" .. move.name:gsub("%s+", "_")
        DribbleBindIds[#DribbleBindIds + 1] = bindId
        groups[move.group]:AddButton({
            Text = move.name,
            Description = move.desc .. ". Click to play it, or bind a key.",
            Bind = bindId,
            Func = function()
                -- Both spins on one key: play the one that starts from the hand you are dribbling with (right hand =
                -- right to left, left hand = left to right), instead of firing both at once.
                local side = Farm.SPIN_SIDE[move.name]
                if side then
                    local otherName = side == "L" and "Spin Hesi R to L" or "Spin Hesi L to R"
                    local mine = Window:GetBind(bindId)
                    local theirs = Window:GetBind((("Move_" .. otherName:gsub("%s+", "_"))))
                    if mine and theirs and mine == theirs then
                        local hand = Ctx.char and Ctx.char:GetAttribute("Hand")
                        if (hand == "L" and "L" or "R") ~= side then
                            return
                        end
                    end
                end
                if not playMove(move) then
                    notify(move.name, "InputService.Dribble not found on this build.", "Warning")
                end
            end,
        })
    end

    local creator = offense:AddTab("Combo Creator")
    local build = creator:AddGroupbox("Create Combo")
    local sequenceLabel = build:AddLabel("Sequence: empty. Add moves below.")
    local function refreshSequence()
        local count = #Flags.ComboMoves
        if count == 0 then
            sequenceLabel:SetText("Sequence: empty. Add moves below.")
            return
        end
        local text = table.concat(Flags.ComboMoves, " > ")
        if #text > 70 then
            text = "..." .. text:sub(-67)
        end
        sequenceLabel:SetText(("%d move%s: %s"):format(count, count == 1 and "" or "s", text))
    end
    build:AddDropdown("ComboAddMove", {
        Text = "Add Move", Description = "Each pick is added to the end of the combo. The same move can be added more than once.",
        Values = MoveNames,
        Get = function()
            return "Pick a move to add"
        end,
        Set = function(_, value)
            if MovesByName[value] then
                Flags.ComboMoves[#Flags.ComboMoves + 1] = value
                refreshSequence()
            end
        end,
    })
    build:AddButton({ Text = "Remove Last Move", Func = function()
        table.remove(Flags.ComboMoves)
        refreshSequence()
    end })
    build:AddButton({ Text = "Clear Sequence", Func = function()
        Flags.ComboMoves = {}
        refreshSequence()
    end })
    DribbleBindIds[#DribbleBindIds + 1] = "ComboPlay"
    build:AddButton({
        Text = "Play / Stop Combo",
        Description = "Click to play or stop the combo, or bind a key to it. A bound key does only this.",
        Bind = "ComboPlay",
        Func = Combo.play,
    })
    toggle(creator:AddGroupbox("Loop"), "LoopCombo", "Loop Play Combo", "Repeats the combo until stopped")
    local keybinds = creator:AddGroupbox("Keybind Safety")
    keybinds:AddDangerButton({ Text = "EMERGENCY: RESET ALL KEYBINDS", Func = askWipeKeybinds })
end

