----------------------------------------------------------------------------------------------------
-- Gameplay capture ("Capture" tab). Learns how each player plays (dribble moves and their rhythm, shot distance, how
-- open the shot was, speed, sprinting, how close they guard) and keeps it in JHub/Capture/ so it can be sent for review.
-- Your own lifetime profile is kept in JHub/Capture/lifetime.json (it only records while Auto Farm is OFF, so it is
-- you playing and not the bot). Everyone else goes in players.json, the last 500 events in recent.json.
----------------------------------------------------------------------------------------------------
Farm.Rec = (function()
    local Rec = {
        dir = "JHub/Capture",
        files = { me = "JHub/Capture/lifetime.json", players = "JHub/Capture/players.json", recent = "JHub/Capture/recent.json" },
        me = nil, players = {}, events = {}, state = {}, conns = {},
        dirty = false, lastSave = os.clock(), acc = 0, fb = nil, fbConn = nil,
        MAX_EVENTS = 500, MAX_PLAYERS = 60, SAMPLE = 0.25, SAVE_EVERY = 15,
    }
    local DRIBBLE = { Dribbling = true, Ankles = true, BlowingBy = true }
    local DIST_EDGES, DIST_LABELS = { 6, 12, 18, 24 }, { "0-6", "6-12", "12-18", "18-24", "24+" }
    local GAP_EDGES, GAP_LABELS = { 3, 6, 10 }, { "<3", "3-6", "6-10", "10+" }
    local TIME_EDGES, TIME_LABELS = { 0.5, 1, 2, 4 }, { "<0.5s", "0.5-1s", "1-2s", "2-4s", "4s+" }
    -- input string -> move name, per hand (same table the bot uses to play its own moves)
    local MOVE_NAMES = {
        R = { Z = "Cross", C = "Hesitation", X = "StepBack", CXZ = "SpinLeft", CX = "BehindBack", ZZ = "DoubleCross" },
        L = { C = "Cross", Z = "Hesitation", X = "StepBack", ZXC = "SpinLeft", ZX = "BehindBack", CC = "DoubleCross" },
    }

    local function bucket(value, edges, labels)
        for index, edge in ipairs(edges) do
            if value < edge then
                return labels[index]
            end
        end
        return labels[#labels]
    end

    local function add(tbl, key, amount)
        key = tostring(key)
        tbl[key] = (tbl[key] or 0) + (amount or 1)
    end

    local function round(value, places)
        local scale = 10 ^ (places or 1)
        return math.floor(value * scale + 0.5) / scale
    end

    local function newProfile(name)
        return {
            name = name, first = os.time(), last = os.time(), secs = 0, ballSecs = 0, shots = 0, sessions = 0,
            actions = {}, moveGap = {}, inputGap = {}, holdToShot = {}, shotDist = {}, shotGap = {}, shotKind = {},
            shotMove = {}, spd = { ball = 0, nBall = 0, free = 0, nFree = 0 }, sprint = {}, defGap = {}, heat = {},
            inputs = {}, grades = {},
        }
    end

    local function fill(profile, name)
        for key, value in pairs(newProfile(name)) do
            if profile[key] == nil then
                profile[key] = value
            end
        end
        if type(profile.spd) ~= "table" then
            profile.spd = newProfile(name).spd
        end
        return profile
    end

    local function active(name)
        if Flags.RecOn ~= true then
            return false
        end
        if name ~= LocalPlayer.Name then
            return true
        end
        -- yours only while the bot is not playing: flag off, and the bot has not driven anything for 10 seconds
        return not Flags.AutoFarm and os.clock() - (Farm.botAt or -math.huge) > 10
    end

    function Rec.profile(name)
        if name == LocalPlayer.Name then
            Rec.me = Rec.me or newProfile(name)
            return Rec.me
        end
        local profile = Rec.players[name]
        if not profile then
            local count, worst, worstSecs = 0, nil, nil
            for key, value in pairs(Rec.players) do
                count += 1
                if not worstSecs or (value.secs or 0) < worstSecs then
                    worst, worstSecs = key, value.secs or 0
                end
            end
            if count >= Rec.MAX_PLAYERS and worst then
                Rec.players[worst] = nil
            end
            profile = newProfile(name)
            Rec.players[name] = profile
        end
        return profile
    end

    function Rec.stateFor(name)
        local st = Rec.state[name]
        if not st then
            st = { lastAction = "", speed = 0, hadBall = false }
            Rec.state[name] = st
        end
        return st
    end

    function Rec.event(name, kind, data)
        data = data or {}
        data.t, data.p, data.e = os.time(), name, kind
        local list = Rec.events
        list[#list + 1] = data
        if #list > Rec.MAX_EVENTS then
            table.remove(list, 1)
        end
        Rec.dirty = true
    end

    function Rec.hoopDist(model, hrp)
        if not hrp then
            return nil
        end
        local hoop = chooseAttackedHoop({ model = model, hrp = hrp })
        return hoop and flatDistance(hrp.Position, hoop) or nil
    end

    local function others(model, visit)
        local folder = Characters
        if not folder then
            return
        end
        for _, other in ipairs(folder:GetChildren()) do
            if other ~= model and other:IsA("Model") and other.Name ~= GameData.IgnoredCharacterName then
                local ohrp = other:FindFirstChild("HumanoidRootPart")
                if ohrp then
                    visit(other, ohrp)
                end
            end
        end
    end

    function Rec.nearestOther(model, hrp)
        local best
        others(model, function(_, ohrp)
            local distance = flatDistance(hrp.Position, ohrp.Position)
            if not best or distance < best then
                best = distance
            end
        end)
        return best
    end

    function Rec.ballHolder(model)
        local found
        others(model, function(other, ohrp)
            if not found and holdsBall(other) then
                found = ohrp
            end
        end)
        return found
    end

    function Rec.onShot(model, hrp, action, st, profile, now)
        profile.shots += 1
        add(profile.shotKind, action)
        local distance = Rec.hoopDist(model, hrp)
        if distance then
            add(profile.shotDist, bucket(distance, DIST_EDGES, DIST_LABELS))
        end
        local gap = hrp and Rec.nearestOther(model, hrp)
        if gap then
            add(profile.shotGap, bucket(gap, GAP_EDGES, GAP_LABELS))
        end
        add(profile.shotMove, st.speed > 4 and "moving" or "still")
        if st.gotBallAt then
            add(profile.holdToShot, bucket(now - st.gotBallAt, TIME_EDGES, TIME_LABELS))
        end
        Rec.event(model.Name, "shot", {
            a = action, d = distance and round(distance), g = gap and round(gap), v = round(st.speed),
            h = st.gotBallAt and round(now - st.gotBallAt),
        })
    end

    function Rec.onAction(model, action)
        local name = model.Name
        if not active(name) then
            return
        end
        action = tostring(action or "")
        local st = Rec.stateFor(name)
        if action == st.lastAction then
            return
        end
        local previous = st.lastAction
        st.lastAction = action
        if action == "" then
            return
        end
        local now = os.clock()
        local profile = Rec.profile(name)
        local hrp = model:FindFirstChild("HumanoidRootPart")
        add(profile.actions, action)
        if DRIBBLE[action] and holdsBall(model) then
            if st.lastDribbleAt then
                add(profile.moveGap, bucket(now - st.lastDribbleAt, TIME_EDGES, TIME_LABELS))
            end
            st.lastDribbleAt = now
            local distance = Rec.hoopDist(model, hrp)
            Rec.event(name, "move", { a = action, d = distance and round(distance) })
        elseif Farm.SHOT_ACTIONS[action] and not Farm.SHOT_ACTIONS[previous] then
            Rec.onShot(model, hrp, action, st, profile, now)
        end
        Rec.dirty = true
    end

    function Rec.hook(model)
        if Rec.conns[model] or not model:IsA("Model") then
            return
        end
        Rec.conns[model] = model:GetAttributeChangedSignal("Action"):Connect(function()
            pcall(Rec.onAction, model, model:GetAttribute("Action"))
        end)
    end

    function Rec.sampleModel(model, hrp, st, step)
        local profile = Rec.profile(model.Name)
        profile.secs += step
        profile.last = os.time()
        local sprinting = model:GetAttribute("Sprinting") == true
        local hasBall = holdsBall(model)
        if hasBall then
            profile.ballSecs += step
            if not st.hadBall then
                st.gotBallAt = os.clock()
            end
            profile.spd.ball += st.speed
            profile.spd.nBall += 1
            add(profile.sprint, sprinting and "ballOn" or "ballOff")
            local distance = Rec.hoopDist(model, hrp)
            if distance then
                local gap = Rec.nearestOther(model, hrp)
                add(profile.heat, bucket(distance, DIST_EDGES, DIST_LABELS) .. "|" .. (gap and bucket(gap, GAP_EDGES, GAP_LABELS) or "?"))
            end
        else
            st.gotBallAt = nil
            profile.spd.free += st.speed
            profile.spd.nFree += 1
            local holder = Rec.ballHolder(model)
            if holder then -- he has the ball: how close is this player guarding him, and are they sprinting while doing it
                add(profile.defGap, bucket(flatDistance(hrp.Position, holder.Position), GAP_EDGES, GAP_LABELS))
                add(profile.sprint, sprinting and "defOn" or "defOff")
            end
        end
        st.hadBall = hasBall
        Rec.dirty = true
    end

    -- Shot feedback grade of the local player (5 = green), recorded for human play only.
    local function bindFeedback()
        local target = remote("InterfaceService", "ShowFeedback")
        if not target or target == Rec.fb then
            return
        end
        if Rec.fbConn then
            pcall(Rec.fbConn.Disconnect, Rec.fbConn)
        end
        Rec.fb = target
        Rec.fbConn = target.OnClientEvent:Connect(function(owner, _, grade)
            if owner == Ctx.char and active(LocalPlayer.Name) then
                add(Rec.profile(LocalPlayer.Name).grades, tonumber(grade) or "?")
                Rec.dirty = true
            end
        end)
    end

    function Rec.sample(dt)
        Rec.acc += dt
        if Rec.acc < Rec.SAMPLE then
            return
        end
        local step = Rec.acc
        Rec.acc = 0
        local gate = Env.__JHubRecGate
        if gate then
            gate.watch = Flags.RecOn == true and not Flags.AutoFarm
        end
        if Flags.RecOn then
            bindFeedback()
        end
        for model, connection in pairs(Rec.conns) do
            if not model.Parent then
                pcall(connection.Disconnect, connection)
                Rec.conns[model] = nil
                Rec.state[model.Name] = nil
            end
        end
        local folder = Characters
        if Flags.RecOn and folder then
            for _, model in ipairs(folder:GetChildren()) do
                if model:IsA("Model") and model.Name ~= GameData.IgnoredCharacterName then
                    Rec.hook(model)
                    local hrp = model:FindFirstChild("HumanoidRootPart")
                    if hrp then
                        local st = Rec.stateFor(model.Name)
                        if st.lastPos then
                            st.speed = flat(hrp.Position - st.lastPos).Magnitude / step
                        end
                        st.lastPos = hrp.Position
                        if active(model.Name) then
                            Rec.sampleModel(model, hrp, st, step)
                        end
                    end
                end
            end
        end
        if Rec.dirty and os.clock() - Rec.lastSave > Rec.SAVE_EVERY then
            Rec.save()
        end
    end

    -- Your own inputs: what the game receives from you (dribble move strings, shot presses, jumps). Method-style calls
    -- only, so the bot's own pcall(FireServer) calls never end up here.
    function Rec.onRemote(remote, a, b)
        if not remote.Parent or remote.Parent.Name ~= "InputService" or not active(LocalPlayer.Name) then
            return
        end
        local name = remote.Name
        local profile = Rec.profile(LocalPlayer.Name)
        local st = Rec.stateFor(LocalPlayer.Name)
        local now = os.clock()
        if name == "Dribble" then
            local hand = Ctx.char and Ctx.char:GetAttribute("Hand") or "?"
            -- The game keeps one growing key buffer ("XXZ", "XXZC", ...) that is only extended, so record just the newly
            -- added keys of each call, not the whole buffer (that made a new profile key for every press).
            local text = tostring(a)
            local prev = st.lastStr or ""
            local added = text:sub(1, #prev) == prev and text:sub(#prev + 1) or text
            st.lastStr = text
            if #text > 200 then
                st.lastStr = text:sub(-40)
            end
            if added == "" then
                return
            end
            if #added > 3 then
                added = added:sub(-1)
            end
            local spin = MOVE_NAMES[tostring(hand)] and (tostring(hand) == "R" and "CXZ" or "ZXC")
            local key = tostring(hand) .. ":" .. ((spin and text:sub(-3) == spin) and spin or added)
            add(profile.inputs, key)
            if st.lastInput then
                add(profile.inputGap, bucket(now - st.lastInput, TIME_EDGES, TIME_LABELS))
            end
            st.lastInput = now
            local hrp = Ctx.hrp
            local distance = hrp and Rec.hoopDist(Ctx.char, hrp)
            Rec.event(LocalPlayer.Name, "input", { k = key, s = b == true, d = distance and round(distance) })
        elseif name == "Shoot" and typeof(a) == "table" and a.Shoot == true then
            add(profile.inputs, "shoot:" .. tostring(a.Input) .. (a.UseSpace and ":space" or ""))
        elseif name == "Jump" then
            add(profile.inputs, "jump")
        end
        Rec.dirty = true
    end

    -- A dribble move played by JHub itself because you pressed a keybind or ran the combo. The game's own key handler is
    -- bypassed then, so the hook never sees it. Same "<hand>:<input>" key as a real key press.
    function Rec.noteScript(input)
        if not active(LocalPlayer.Name) then
            return
        end
        local profile = Rec.profile(LocalPlayer.Name)
        local st = Rec.stateFor(LocalPlayer.Name)
        local now = os.clock()
        local hand = Ctx.char and Ctx.char:GetAttribute("Hand") or "?"
        local key = tostring(hand) .. ":" .. tostring(input)
        add(profile.inputs, key)
        if st.lastInput then
            add(profile.inputGap, bucket(now - st.lastInput, TIME_EDGES, TIME_LABELS))
        end
        st.lastInput = now
        local distance = Ctx.hrp and Rec.hoopDist(Ctx.char, Ctx.hrp)
        Rec.event(LocalPlayer.Name, "input", { k = key, s = true, d = distance and round(distance), b = true })
        Rec.dirty = true
    end

    function Rec.install()
        if type(hookmetamethod) ~= "function" or type(newcclosure) ~= "function" or type(getnamecallmethod) ~= "function" then
            return false
        end
        local gate = Env.__JHubRecGate
        if not gate then
            gate = { watch = false, installed = false }
            Env.__JHubRecGate = gate
        end
        gate.handler = Rec.onRemote -- a re-executed script replaces the handler; the hook itself is installed once
        if not gate.installed then
            local original
            original = hookmetamethod(game, "__namecall", newcclosure(function(self, ...)
                if gate.watch and gate.handler and getnamecallmethod() == "FireServer" and typeof(self) == "Instance" then
                    pcall(gate.handler, self, ...) -- capture must never break a game call
                end
                return original(self, ...)
            end))
            gate.installed = true
        end
        return true
    end

    -- Files ------------------------------------------------------------------------------------------------------
    local function flatName(path)
        return (path:gsub("/", "_"))
    end

    local function readJson(path)
        if type(isfile) ~= "function" or type(readfile) ~= "function" then
            return nil
        end
        -- Both the folder file and the flat fallback file may exist; use whichever was written last.
        local function stamp(data)
            local best = type(data.last) == "number" and data.last or 0
            for _, value in pairs(data) do
                if type(value) == "table" and type(value.last) == "number" and value.last > best then
                    best = value.last
                end
            end
            if type(data.events) == "table" then
                local lastEvent = data.events[#data.events]
                best = type(lastEvent) == "table" and tonumber(lastEvent.t) or best
            end
            return best
        end
        local found, foundStamp = nil, -1
        for _, candidate in ipairs({ path, flatName(path) }) do
            local ok, data = pcall(function()
                if isfile(candidate) then
                    return HttpService:JSONDecode(readfile(candidate))
                end
            end)
            if ok and type(data) == "table" then
                local mark = stamp(data)
                if mark > foundStamp then
                    found, foundStamp = data, mark
                end
            end
        end
        return found
    end

    local function ensureFolders()
        if type(makefolder) ~= "function" then
            return
        end
        for _, folder in ipairs({ "JHub", Rec.dir }) do
            local exists = false
            if type(isfolder) == "function" then
                local ok, found = pcall(isfolder, folder)
                exists = ok and found == true
            end
            if not exists then
                pcall(makefolder, folder)
            end
        end
    end

    -- Returns ok, error text. Tries JHub/Capture/<file> first and a flat <JHub_Capture_file> in the workspace root if the
    -- folder cannot be written.
    local function writeJson(path, data)
        if type(writefile) ~= "function" then
            return false, "this executor has no writefile"
        end
        local encoded
        local okEncode, errEncode = pcall(function()
            encoded = HttpService:JSONEncode(data)
        end)
        if not okEncode then
            return false, "could not encode: " .. tostring(errEncode)
        end
        ensureFolders()
        local ok, err = pcall(writefile, path, encoded)
        if ok then
            return true
        end
        local okFlat = pcall(writefile, flatName(path), encoded)
        if okFlat then
            return true
        end
        return false, tostring(err)
    end

    function Rec.save()
        Rec.lastSave = os.clock()
        local ok, firstError = true, nil
        local function put(path, data)
            local good, err = writeJson(path, data)
            if not good then
                ok, firstError = false, firstError or err
            end
        end
        if Rec.me then
            put(Rec.files.me, Rec.me)
        end
        put(Rec.files.players, Rec.players)
        put(Rec.files.recent, { events = Rec.events })
        Rec.dirty = not ok -- keep trying every interval until a write works
        Rec.lastError = firstError
        if ok then
            Rec.savedAt = os.clock()
        end
        return ok, firstError
    end

    -- Summaries (readable percentages) -----------------------------------------------------------------------------
    local function shares(tbl)
        local total = 0
        for _, value in pairs(tbl or {}) do
            total += value
        end
        local out = {}
        if total > 0 then
            for key, value in pairs(tbl) do
                out[key] = round(value / total * 100)
            end
        end
        return out
    end

    -- Names the game's shot feedback uses, as seen in logs: 5 Perfect, 4 Good, 2 Early, 7 Late. Others stay as numbers.
    local GRADE_NAMES = { ["2"] = "Early", ["4"] = "Good", ["5"] = "Perfect", ["7"] = "Late" }
    function Rec.gradeNames(grades)
        local out = {}
        for key, count in pairs(grades or {}) do
            local name = GRADE_NAMES[tostring(key)]
            out[name and (tostring(key) .. " " .. name) or tostring(key)] = count
        end
        return out
    end

    function Rec.summary(p)
        local spd = p.spd or {}
        local top = {}
        for key, count in pairs(p.heat or {}) do
            top[#top + 1] = { key, count }
        end
        table.sort(top, function(x, y)
            return x[2] > y[2]
        end)
        local heat = {}
        for index = 1, math.min(#top, 12) do
            heat[top[index][1]] = top[index][2]
        end
        return {
            name = p.name, minutes = round((p.secs or 0) / 60), ballPercent = (p.secs or 0) > 0 and round((p.ballSecs or 0) / p.secs * 100) or 0,
            shots = p.shots, sessions = p.sessions,
            avgSpeedWithBall = (spd.nBall or 0) > 0 and round(spd.ball / spd.nBall) or nil,
            avgSpeedWithoutBall = (spd.nFree or 0) > 0 and round(spd.free / spd.nFree) or nil,
            actionPercent = shares(p.actions), timeBetweenMovesPercent = shares(p.moveGap),
            timeBetweenInputsPercent = shares(p.inputGap), secondsHoldingBeforeShotPercent = shares(p.holdToShot),
            shotDistancePercent = shares(p.shotDist), defenderGapAtShotPercent = shares(p.shotGap),
            shotKinds = p.shotKind, shotMovingOrStill = p.shotMove, sprintSamples = p.sprint,
            guardingGapPercent = shares(p.defGap), inputs = p.inputs, grades = Rec.gradeNames(p.grades), mostTimeWithBall = heat,
        }
    end

    function Rec.export()
        local list = {}
        for _, profile in pairs(Rec.players) do
            list[#list + 1] = profile
        end
        table.sort(list, function(x, y)
            return (x.secs or 0) > (y.secs or 0)
        end)
        local players = {}
        for index = 1, math.min(#list, 10) do
            players[#players + 1] = Rec.summary(list[index])
        end
        local recent = {}
        for index = math.max(1, #Rec.events - 119), #Rec.events do
            recent[#recent + 1] = Rec.events[index]
        end
        return HttpService:JSONEncode({
            jhub = VERSION, exportedUtc = os.date("!%Y-%m-%d %H:%M:%S"),
            note = "me = your own lifetime profile (recorded with Auto Farm off). players = everyone else.",
            me = Rec.me and Rec.summary(Rec.me) or nil, players = players, recentEvents = recent,
        })
    end

    -- Capture for one match: events since the match began, your lifetime profile, and the players seen in it.
    function Rec.matchExport()
        local since = Rec.matchStart or 0
        local events, seen, order = {}, {}, {}
        for _, event in ipairs(Rec.events) do
            if (event.t or 0) >= since then
                events[#events + 1] = event
                if event.p and event.p ~= LocalPlayer.Name and not seen[event.p] then
                    seen[event.p] = true
                    order[#order + 1] = event.p
                end
            end
        end
        if #events == 0 then
            return nil
        end
        while #events > 300 do
            table.remove(events, 1)
        end
        local players = {}
        for index = 1, math.min(#order, 10) do
            local profile = Rec.players[order[index]]
            if profile then
                players[#players + 1] = Rec.summary(profile)
            end
        end
        return HttpService:JSONEncode({
            jhub = VERSION, user = LocalPlayer.Name, exportedUtc = os.date("!%Y-%m-%d %H:%M:%S"), matchStart = since,
            note = "me = this user's lifetime profile. players = opponents seen this match. events = this match only.",
            me = Rec.me and Rec.summary(Rec.me) or nil, players = players, matchEvents = events,
        })
    end

    function Rec.copy()
        Rec.save()
        local text = Rec.export()
        if type(setclipboard) == "function" and pcall(setclipboard, text) then
            notify("Capture", ("Copied %d characters. Paste it into the chat."):format(#text), "Success", 5)
        else
            notify("Capture", "No clipboard here. Send the files in your executor's workspace: JHub/Capture/", "Warning", 8)
        end
    end

    function Rec.reset()
        Rec.me = newProfile(LocalPlayer.Name)
        Rec.me.sessions = 1
        Rec.players, Rec.events, Rec.state = {}, {}, {}
        if type(delfile) == "function" and type(isfile) == "function" then
            for _, path in pairs(Rec.files) do
                for _, candidate in ipairs({ path, (path:gsub("/", "_")) }) do
                    pcall(function()
                        if isfile(candidate) then
                            delfile(candidate)
                        end
                    end)
                end
            end
        end
        Rec.dirty = true
        Rec.save()
        notify("Capture", "Tracking reset. Lifetime profile and all learned players were cleared.", "Success", 5)
    end

    function Rec.statsText()
        local me = Rec.me
        local count = 0
        for _ in pairs(Rec.players) do
            count += 1
        end
        local status
        if Rec.savedAt then
            status = ("saved %ds ago"):format(os.clock() - Rec.savedAt)
        elseif Rec.lastError then
            status = "NOT SAVING: " .. tostring(Rec.lastError):sub(1, 40)
        else
            status = "not saved yet"
        end
        return ("You %.1fm, %d shots, %d players, %s"):format(me and (me.secs or 0) / 60 or 0, me and me.shots or 0, count, status)
    end

    -- Learning, used by Auto Farm --------------------------------------------------------------------------------
    -- "Play Like Me": the share of each dribble move in your own lifetime profile, or nil until there are enough.
    function Rec.moveMix()
        local me = Rec.me
        if not me then
            return nil
        end
        local counts, total = {}, 0
        -- The game gets the keys of a chain as they are pressed (Z, ZC, ZCC, ...), so only the newest key of each call
        -- is one new press. A spin string (CXZ right hand, ZXC left hand) counts once as a spin.
        for key, count in pairs(me.inputs or {}) do
            local hand, input = key:match("^(%a):(%u+)$")
            local names = hand and MOVE_NAMES[hand]
            local name
            if names then
                name = names[input] -- exact single move or spin
                if not name and input:sub(-3) ~= "CXZ" and input:sub(-3) ~= "ZXC" then
                    name = names[input:sub(-1)] -- newest key of a longer chain
                end
            end
            if name then
                counts[name] = (counts[name] or 0) + count
                total += count
            end
        end
        if total < 20 then
            return nil
        end
        for name, count in pairs(counts) do
            counts[name] = count / total
        end
        return counts
    end

    -- "Scout Opponents": how far to stand off a player, from how that player has shot. + = farther.
    function Rec.guardAdjust(name)
        local profile = Rec.players[name]
        if not profile or (profile.shots or 0) < 8 then
            return 0
        end
        local total = 0
        for _, count in pairs(profile.shotDist or {}) do
            total += count
        end
        if total < 8 then
            return 0
        end
        local close = (profile.shotDist["0-6"] or 0) / total
        local deep = ((profile.shotDist["18-24"] or 0) + (profile.shotDist["24+"] or 0)) / total
        local move = profile.shotMove or {}
        local still = (move.still or 0) / math.max(1, (move.still or 0) + (move.moving or 0))
        if close >= 0.55 and still >= 0.4 then
            return 0 -- a rim camper: he waits under the basket and dunks standing, so extra room does nothing
        elseif close >= 0.55 then
            return 1.5 -- a driver: give more room so he cannot blow by
        elseif deep >= 0.5 then
            return -1 -- a shooter: close out tighter
        end
        return 0
    end

    function Rec.start()
        local me = readJson(Rec.files.me)
        Rec.me = me and fill(me, LocalPlayer.Name) or newProfile(LocalPlayer.Name)
        Rec.me.sessions = (Rec.me.sessions or 0) + 1
        do -- older files stored whole key buffers per press; fold them into one key per press (newest key)
            local folded, changed = {}, false
            for key, count in pairs(Rec.me.inputs or {}) do
                local hand, text = key:match("^(%a):(%u+)$")
                if hand and #text > 3 then
                    key, changed = hand .. ":" .. text:sub(-1), true
                end
                folded[key] = (folded[key] or 0) + count
            end
            if changed then
                Rec.me.inputs = folded
            end
        end
        local players = readJson(Rec.files.players)
        if players then
            for name, profile in pairs(players) do
                if type(profile) == "table" then
                    Rec.players[name] = fill(profile, name)
                end
            end
        end
        local recent = readJson(Rec.files.recent)
        if recent and type(recent.events) == "table" then
            Rec.events = recent.events
        end
        if Flags.RecOn then
            Rec.install()
        end
        Env.__JHubRecNote = Rec.noteScript
        Rec.dirty = true
        Rec.lastSave = os.clock() - Rec.SAVE_EVERY + 5 -- first autosave 5s after load, so the files exist straight away
        Root:Give(RunService.Heartbeat:Connect(guarded("Capture", "RecOn", Rec.sample)))
        Root:Give(function()
            Rec.stopped = true
            Env.__JHubRecNote = nil
            local gate = Env.__JHubRecGate
            if gate then
                gate.handler, gate.watch = nil, false
            end
            for _, connection in pairs(Rec.conns) do
                pcall(connection.Disconnect, connection)
            end
            if Rec.fbConn then
                pcall(Rec.fbConn.Disconnect, Rec.fbConn)
            end
            if Rec.dirty then
                Rec.save()
            end
        end)
    end

    return Rec
end)()

-- Capture tab: lifetime gameplay capture, reset, copy
do
    local tab = farmCategory:AddTab("Capture")
    local box = tab:AddGroupbox("Gameplay Capture")
    toggle(box, "RecOn", "Capture Lifetime Gameplay", "Records how you play (dribble moves and how often, hold time, shot distance, how open you were, speed, sprinting, shot grades) into JHub/Capture/lifetime.json, and how every other player plays into players.json. Your own play is only recorded while Auto Farm is OFF, so the profile is you and not the bot.", {
        OnChange = function(value)
            if value then
                Farm.Rec.install()
            end
        end,
    })
    local stats = box:AddLabel("Capture: starting")
    box:AddButton({ Text = "Copy to Clipboard", Func = function()
        Farm.Rec.copy()
    end })
    box:AddDangerButton({ Text = "Reset Tracking", Func = function()
        Window:Confirm({
            Title = "RESET TRACKING",
            Danger = true,
            YesLabel = "RESET",
            NoLabel = "Cancel",
            Lines = {
                "This clears your lifetime profile and every player JHub has learned.",
                "The files in JHub/Capture/ are deleted and started fresh.",
                "This cannot be undone.",
            },
            Yes = function()
                Farm.Rec.reset()
            end,
        })
    end })
    box:AddLabel("It saves by itself every 15 seconds. Copy to Clipboard puts a summary on your clipboard (your profile, the 10 most-seen players, the last 120 events). Paste it in chat. Files: JHub/Capture/ in your executor's workspace folder.")

    local learn = tab:AddGroupbox("Use What It Learned")
    toggle(box, "RecWebhook", "Send With Match Reports", "At the end of each match the Discord match report (when ReportCfg.Webhook is set) also gets a capture file for that match: your profile, the opponents seen and this match's events. Includes the Roblox names of players you played against.")
    toggle(learn, "FarmPlayLikeMe", "Play Like Me", "Auto Farm picks its dribble moves in the same proportions you use them (needs about 20 recorded dribble inputs from you with Auto Farm off).")
    toggle(learn, "FarmScout", "Scout Opponents", "Auto Farm guards a player who mostly drives to the rim from farther back, and a player who mostly shoots deep from closer (needs about 8 shots seen from that player).")

    task.spawn(function()
        while not Farm.Rec.stopped do
            pcall(function()
                stats:SetText(Farm.Rec.statsText())
            end)
            task.wait(5)
        end
    end)
end

