do
    Override.keyNames = function()
        local names = {}
        for _, id in ipairs(DribbleBindIds) do
            local key = Window:GetBind(id)
            if key then
                names[#names + 1] = key
            end
        end
        return names
    end
    beatSteps[#beatSteps + 1] = guarded("Dribble Override", nil, Override.step)
