----------------------------------------------------------------------------------------------------
-- Start up
----------------------------------------------------------------------------------------------------
Calibration.load()
Hoops.refresh()
bindMeterRemotes()
bindAnkleBreaker()
-- The Characters folder is created when the match starts. Loading in the showcase (before that) used to leave it nil
-- for the whole session; this picks it up the moment it exists.
if not Characters then
    task.spawn(function()
        while Alive and not Characters do
            local folder = Workspace:FindFirstChild(GameData.CharactersFolder)
            if folder then
                Characters = folder
                Hoops.refresh()
                bindAnkleBreaker()
                break
            end
            task.wait(0.25)
        end
    end)
end
installJumpCapture()
Ctx.update()
Farm.start()
Farm.hideUIOnLoad(Window)
Farm.Rec.start()

local libraryUnload = Window.Unload
local function unload()
    if not Alive then
        return
    end
    Alive = false
    Root:Clean()
    pcall(libraryUnload, Window)
    if Env.JHub and Env.JHub.Unload == unload then
        Env.JHub = nil
    end
end
-- The library's close button and a re-execute both call Window:Unload(); route them through the full cleanup.
Window.Unload = function()
    unload()
end
Env.JHub = { Version = VERSION, Unload = unload }

local missing = {}
for service, names in pairs({ Input = GameData.Remotes.Input, Meter = GameData.Remotes.Meter, Interface = GameData.Remotes.Interface, Player = GameData.Remotes.Player }) do
    for _, name in ipairs(names) do
        if not remote(service .. "Service", name) then
            missing[#missing + 1] = service .. "Service." .. name
        end
    end
end
if #missing > 0 then
    notify("JHub", "Missing on this build: " .. table.concat(missing, ", ") .. ". Related features are gated.", "Warning", 8)
else
    notify("JHub", "Practical Basketball v" .. VERSION .. " loaded.", "Success", 4)
end
